#define JS_MKPTR(tag, ptr) (((uint64_t)(uint32_t)(tag) << 32) | (uintptr_t)(ptr))

#define JS_FLOAT64_TAG_ADDEND (0x7ff80000 - JS_TAG_FIRST + 1)
#define JS_NAN (0x7ff8000000000000ULL)

static inline double js_int64_to_float64(int64_t v) {
    union { uint64_t i; double d; } u;
    u.i = v;
    return u.d;
}

static inline JSValue __js_NewFloat64(JSContext *ctx, double d) {
    union { double d; uint64_t u64; } u;
    JSValue v;
    u.d = d;
    if (((u.u64 & 0x7fffffffffffffff) > 0x7ff0000000000000ULL)) {
        v = JS_NAN;
    } else {
        v = u.u64 - ((uint64_t)JS_FLOAT64_TAG_ADDEND << 32);
    }
    return v;
}

