static inline int JS_VALUE_IS_NAN(JSValue v) {
    uint32_t tag = v >> 32;
    return tag == (uint32_t)(JS_TAG_FLOAT64 + JS_FLOAT64_TAG_ADDEND) &&
        (uint32_t)v == (uint32_t)(JS_NAN >> 32);
}

