static inline uint32_t min_uint32(uint32_t a, uint32_t b) { return a < b ? a : b; }
static inline int64_t max_int64(int64_t a, int64_t b) { return a < b ? b : a; }
static inline int64_t min_int64(int64_t a, int64_t b) { return a < b ? a : b; }

/* For clz32, ctz32 etc. */
static inline int clz32(unsigned int a)
{
    int n;
    if (a == 0)
        return 32;
    n = 0;
    if (a <= 0x0000FFFF) { n += 16; a <<= 16; }
    if (a <= 0x00FFFFFF) { n += 8; a <<= 8; }
    if (a <= 0x0FFFFFFF) { n += 4; a <<= 4; }
    if (a <= 0x3FFFFFFF) { n += 2; a <<= 2; }
    if (a <= 0x7FFFFFFF) { n += 1; }
    return n;
}

/* Dynamic array */
typedef struct DynBuf {
    uint8_t *buf;
    size_t size;
    size_t allocated_size;
    BOOL error; /* TRUE if a memory error occurred */
    DynBufReallocFunc *realloc_func;
    void *opaque; /* for realloc_func */
} DynBuf;

typedef void *DynBufReallocFunc(void *opaque, void *ptr, size_t size);

