        *q++ = (c & 0x3f) | 0x80;
    } else if (c < 0x10000) {
        *q++ = (c >> 12) | 0xe0;
        *q++ = ((c >> 6) & 0x3f) | 0x80;
        *q++ = (c & 0x3f) | 0x80;
    } else {
        *q++ = (c >> 18) | 0xf0;
        *q++ = ((c >> 12) & 0x3f) | 0x80;
        *q++ = ((c >> 6) & 0x3f) | 0x80;
        *q++ = (c & 0x3f) | 0x80;
    }
    return q - buf;
}

/* return the UTF-8 encoded code point from 'p' and advance 'p' */
int unicode_from_utf8(const uint8_t *p, int max_len, const uint8_t **pp)
{
    int l, c, b, i;
    c = *p++;
    if (c < 0x80) {
        l = 0;
    } else if (c < 0xc0) {
        return -1; /* invalid */
    } else if (c < 0xe0) {
        l = 1;
        c &= 0x1f;
    } else if (c < 0xf0) {
        l = 2;
        c &= 0xf;
    } else if (c < 0xf8) {
        l = 3;
        c &= 0x7;
    } else {
        return -1;
    }
    if (l > (max_len - 1))
        return -1;
    for(i = 0; i < l; i++) {
        b = *p++;
        if (b < 0x80 || b >= 0xc0)
            return -1;
        c = (c << 6) | (b & 0x3f);
    }
    if (pp)
        *pp = p;
    return c;
}

int utf8_encode(uint8_t *buf, uint32_t c)
{
    return unicode_to_utf8(buf, c);
}
