 */
#include <stdlib.h>
#include <stdio.h>
#include <stdarg.h>
#include <inttypes.h>
#include <string.h>
#include <assert.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <time.h>
#if defined(__APPLE__)
#include <malloc/malloc.h>
#elif defined(__linux__)
#include <malloc.h>
#elif defined(__FreeBSD__)
#include <malloc_np.h>
#endif

#include "cutils.h"
#include "quickjs-libc.h"

extern const uint8_t qjsc_repl[];
extern const uint32_t qjsc_repl_size;
extern const uint8_t qjsc_qjscalc[];
extern const uint32_t qjsc_qjscalc_size;

static int eval_buf(JSContext *ctx, const void *buf, int buf_len,
                    const char *filename, int eval_flags)
{
    JSValue val;
    int ret;

    if ((eval_flags & JS_EVAL_TYPE_MASK) == JS_EVAL_TYPE_MODULE) {
        /* for the modules, we compile then run to be able to set
           import.meta */
        val = JS_Eval(ctx, buf, buf_len, filename,
                      eval_flags | JS_EVAL_FLAG_COMPILE_ONLY);
        if (!JS_IsException(val)) {
            js_module_set_import_meta(ctx, val, TRUE, TRUE);
            val = JS_EvalFunction(ctx, val);
        }
    } else {
        val = JS_Eval(ctx, buf, buf_len, filename, eval_flags);
    }
    if (JS_IsException(val)) {
        js_std_dump_error(ctx);
        ret = -1;
    } else {
        ret = 0;
    }
    JS_FreeValue(ctx, val);
    return ret;
}

static int eval_file(JSContext *ctx, const char *filename, int module)
{
    uint8_t *buf;
    int ret, eval_flags;
    size_t buf_len;

    buf = js_load_file(ctx, &buf_len, filename);
    if (!buf) {
        perror(filename);
        exit(1);
    }

    if (module < 0) {
        module = (has_suffix(filename, ".mjs") ||
                  JS_DetectModule((const char *)buf, buf_len));
    }
    if (module)
        eval_flags = JS_EVAL_TYPE_MODULE;
    else
        eval_flags = JS_EVAL_TYPE_GLOBAL;
    ret = eval_buf(ctx, buf, buf_len, filename, eval_flags);
    js_free(ctx, buf);
    return ret;
}

static int has_suffix(const char *str, const char *suffix)
{
    size_t len = strlen(str);
    size_t slen = strlen(suffix);
    return (len >= slen && !memcmp(str + len - slen, suffix, slen));
}

/* also used to initialize the worker context */
static JSContext *JS_NewCustomContext(JSRuntime *rt)
{
    JSContext *ctx;
    ctx = JS_NewContext(rt);
    if (!ctx)
        return NULL;
#ifdef CONFIG_BIGNUM
    JS_AddIntrinsicBigFloat(ctx);
    JS_AddIntrinsicBigDecimal(ctx);
    JS_AddIntrinsicOperators(ctx);
    JS_EnableBignumExt(ctx, TRUE);
#endif
    return ctx;
}

static uint64_t parse_memory_size(const char *str)
{
    const char *p;
    uint64_t v;
    v = strtoull(str, (char **)&p, 10);
    if (*p) {
        char c = *p;
        if (c == 'k' || c == 'K')
            v *= 1024;
        else if (c == 'm' || c == 'M')
            v *= 1024 * 1024;
        else if (c == 'g' || c == 'G')
            v *= 1024 * 1024 * 1024;
    }
    return v;
}

void help(void)
{
    printf("QuickJS version " CONFIG_VERSION "\n"
           "usage: qjs [options] [file [args]]\n"
           "-h  --help         list options\n"
           "-e  --eval EXPR    evaluate EXPR\n"
           "-i  --interactive  go to interactive mode\n"
           "-m  --module       load as ES6 module (default=autodetect)\n"
           "    --script       load as ES6 script (default=autodetect)\n"
           "    --strict       force strict mode\n"
           "-I  --include file include an additional file\n"
           "    --std          make 'std' and 'os' available to the loaded script\n"
           "-T  --trace        trace memory allocation\n"
           "-d  --dump         dump the memory usage stats\n"
           "    --memory-limit n  limit the memory usage to 'n' bytes (SI suffixes allowed)\n"
           "    --stack-size n    limit the stack size to 'n' bytes (SI suffixes allowed)\n"
           "    --no-unhandled-rejection  ignore unhandled promise rejections\n"
           "-s                    strip all the debug info\n"
           "    --strip-source    strip the source code\n"
           "-q  --quit         just instantiate the interpreter and quit\n"
           );
    exit(0);
}

int main(int argc, char **argv)
{
    JSRuntime *rt;
    JSContext *ctx;
    struct trace_malloc_data trace_data = { NULL };
    int optind;
    char *expr = NULL;
    int interactive = 0;
    int dump_memory = 0;
    int trace_memory = 0;
    int empty_run = 0;
    int module = -1;
    int load_std = 0;
    int dump_unhandled_promise_rejection = 1;
    size_t memory_limit = 0;
    char *include_list[32];
    int i, include_count = 0;
    size_t stack_size = 0;
    int strip_flags = 0;

    /* cannot use getopt because we want to pass the command line to
       the script */
    optind = 1;
    while (optind < argc && *argv[optind] == '-') {
        char *arg = argv[optind] + 1;
        const char *longopt = "";
        /* a long option */
        if (*arg == '-') {
            longopt = arg + 1;
            arg += strlen(arg);
            /* --help, --interactive, etc. */
        }
        if (arg[0] == '\0' || strstart(longopt, "help", NULL)) {
            help();
        } else if (!strcmp(arg, "e") || strstart(longopt, "eval", NULL)) {
            if (optind + 1 >= argc) {
                fprintf(stderr, "qjs: missing expression for -e\n");
                exit(2);
            }
            expr = argv[optind + 1];
            optind++;
        } else if (!strcmp(arg, "I") || strstart(longopt, "include", NULL)) {
            if (optind + 1 >= argc) {
                fprintf(stderr, "qjs: missing filename for -I\n");
                exit(2);
            }
            if (include_count >= (int)(sizeof(include_list)/sizeof(*include_list))) {
                fprintf(stderr, "qjs: too many included files\n");
                exit(2);
            }
            include_list[include_count++] = argv[optind + 1];
            optind++;
        } else if (!strcmp(arg, "i") || strstart(longopt, "interactive", NULL)) {
            interactive++;
        } else if (!strcmp(arg, "m") || strstart(longopt, "module", NULL)) {
            module = 1;
        } else if (strstart(longopt, "script", NULL)) {
            module = 0;
        } else if (strstart(longopt, "strict", NULL)) {
            strip_flags |= JS_EVAL_FLAG_STRICT;
        } else if (!strcmp(arg, "d") || strstart(longopt, "dump", NULL)) {
            dump_memory++;
        } else if (!strcmp(arg, "T") || strstart(longopt, "trace", NULL)) {
            trace_memory++;
        } else if (strstart(longopt, "std", NULL)) {
            load_std = 1;
        } else if (strstart(longopt, "no-unhandled-rejection", NULL)) {
            dump_unhandled_promise_rejection = 0;
        } else if (!strcmp(arg, "q") || strstart(longopt, "quit", NULL)) {
            empty_run++;
        } else if (!strcmp(arg, "s")) {
            strip_flags |= JS_EVAL_FLAG_STRIP;
        } else if (strstart(longopt, "strip-source", NULL)) {
            strip_flags |= JS_EVAL_FLAG_STRIP;
        } else if (strstart(longopt, "memory-limit", NULL)) {
            if (optind + 1 >= argc) {
                fprintf(stderr, "qjs: missing memory limit\n");
                exit(2);
            }
            memory_limit = parse_memory_size(argv[optind + 1]);
            optind++;
        } else if (strstart(longopt, "stack-size", NULL)) {
            if (optind + 1 >= argc) {
                fprintf(stderr, "qjs: missing stack size\n");
                exit(2);
            }
            stack_size = parse_memory_size(argv[optind + 1]);
            optind++;
        } else {
            fprintf(stderr, "qjs: unknown option '%s'\n", argv[optind]);
            fprintf(stderr, "QuickJS version " CONFIG_VERSION "\n"
                    "usage: qjs [options] [file [args]]\n"
                    "-h  --help         list options\n"
                    );
            exit(2);
        }
        optind++;
    }

    if (trace_memory) {
        js_trace_malloc_init(&trace_data);
        rt = JS_NewRuntime2(&trace_mf, &trace_data);
    } else {
        rt = JS_NewRuntime();
    }
    if (!rt) {
        fprintf(stderr, "qjs: cannot allocate JS runtime\n");
        exit(2);
    }
    if (memory_limit != 0)
        JS_SetMemoryLimit(rt, memory_limit);
    if (stack_size != 0)
        JS_SetMaxStackSize(rt, stack_size);
    js_std_set_worker_new_context_func(JS_NewCustomContext);
    js_std_init_handlers(rt);
    ctx = JS_NewCustomContext(rt);
    if (!ctx) {
        fprintf(stderr, "qjs: cannot allocate JS context\n");
        exit(2);
    }

    /* loader for ES6 modules */
    JS_SetModuleLoaderFunc(rt, NULL, js_module_loader, NULL);

    if (!dump_unhandled_promise_rejection) {
        JS_SetHostPromiseRejectionTracker(rt, NULL, NULL);
    } else {
        JS_SetHostPromiseRejectionTracker(rt, js_std_promise_rejection_tracker,
                                          NULL);
    }

    if (!empty_run) {
        js_std_add_helpers(ctx, argc - optind, argv + optind);

        /* system modules */
        if (load_std) {
            const char *str = "import * as std from 'std';\n"
                "import * as os from 'os';\n"
                "globalThis.std = std;\n"
                "globalThis.os = os;\n";
            eval_buf(ctx, str, strlen(str), "<input>", JS_EVAL_TYPE_MODULE);
        }

        for(i = 0; i < include_count; i++) {
            if (eval_file(ctx, include_list[i], module))
                goto fail;
        }

        if (expr) {
            if (eval_buf(ctx, expr, strlen(expr), "<cmdline>", 
                         JS_EVAL_TYPE_GLOBAL | (strip_flags & JS_EVAL_FLAG_STRICT)))
                goto fail;
        } else if (optind >= argc) {
            /* interactive mode */
            interactive = 1;
        } else {
            const char *filename;
            filename = argv[optind];
            if (eval_file(ctx, filename, module))
                goto fail;
        }

        if (interactive) {
            js_std_eval_binary(ctx, qjsc_repl, qjsc_repl_size, 0);
        }
        js_std_loop(ctx);
    }

    if (dump_memory) {
        JSMemoryUsage stats;
        JS_ComputeMemoryUsage(rt, &stats);
        JS_DumpMemoryUsage(stdout, &stats, rt);
    }
    js_std_free_handlers(rt);
    JS_FreeContext(ctx);
    JS_FreeRuntime(rt);

    if (dump_memory && trace_memory) {
        static const char header[] = "Memory allocation trace:\n";
        js_trace_malloc_dump_report(stderr, &trace_data);
    }
    return 0;
fail:
    js_std_free_handlers(rt);
    JS_FreeContext(ctx);
    JS_FreeRuntime(rt);
    return 1;
}
QJS_C_EOF

