    /* This covers basic Latin, Greek, etc. */
    if (c >= 0xAA && c <= 0xFFFF)
        return 1;
    return 0;
}

int lre_is_letter_or_number(uint32_t c)
{
    if (c < 128)
        return is_letter(c) || is_digit(c);
