{
    switch (c) {
    case ' ':
    case '\t':
    case '\n':
    case '\r':
    case '\v':
    case '\f':
    case 0x00A0: /* non-breaking space */
    case 0xFEFF: /* BOM / ZWNBS */
        return 1;
    default:
        return lre_is_space_non_ascii(c);
    }
