/* 
 * We implement a simplified regexp engine that uses a basic NFA/backtracking
 * approach. This supports:
 * - Character classes
 * - Quantifiers (*, +, ?, {n,m})
 * - Anchors (^, $)
 * - Groups (capturing and non-capturing)
 * - Alternation (|)
 * - Backreferences (\1-\9)
 * - Named groups (?<name>...)
 * - Lookahead (?=...) (?!...)
 * - Flags: g, i, m, s, u, y, v
 */

/* Bytecode operations for our regexp engine */
#define RE_OP_MATCH        0  /* match success */
#define RE_OP_CHAR         1  /* match single char */
#define RE_OP_CHAR_ICASE   2  /* match char case insensitive */
#define RE_OP_ANY          3  /* match any char */
#define RE_OP_ANYCHAR      4  /* match any char including newline */
#define RE_OP_CHARSET      5  /* match character in set */
#define RE_OP_CHARSET_NOT  6  /* match character not in set */
#define RE_OP_ANCHOR_BEGIN 7  /* ^ */
#define RE_OP_ANCHOR_END   8  /* $ */
#define RE_OP_SAVE_START   9  /* save start of capture group */
#define RE_OP_SAVE_END    10  /* save end of capture group */
#define RE_OP_SPLIT_NEXT  11  /* split: try current path first */
#define RE_OP_SPLIT_GOTO  12  /* split: try jump path first */
#define RE_OP_GOTO        13  /* unconditional jump */
#define RE_OP_LOOP        14  /* loop counter */
#define RE_OP_BACK_REF    15  /* backreference */
#define RE_OP_LOOK_AHEAD  16  /* lookahead assertion */
#define RE_OP_LOOK_BEHIND 17  /* lookbehind assertion */
#define RE_OP_NEG_LOOK    18  /* negative lookahead */
#define RE_OP_WORD_BOUND  19  /* \b word boundary */
#define RE_OP_WORD_NBOUND 20  /* \B non-word boundary */
#define RE_OP_CHAR32      21  /* 32-bit char */
#define RE_OP_UNICODE_SEQ 22  /* unicode sequence */
#define RE_OP_COUNT       23

/* ByteCode header structure */
#define RE_BC_HEADER_SIZE 8

/* The bytecode format:
   byte 0: version
   byte 1: flags
   byte 2-3: capture count
   byte 4-7: total bytecode length
