    bb->buf = NULL;
    bb->size = 0;
    bb->pos = 0;
}

static int bb_put(ByteBuf *bb, uint8_t c) {
    if (bb->pos >= bb->size) {
        size_t new_size = bb->size < 64 ? 64 : bb->size * 2;
        uint8_t *new_buf = realloc(bb->buf, new_size);
        if (!new_buf) return -1;
