                        /* Positive lookahead */
                        dbuf_putstr(&out, "(?=");
                        i += 2;
                    } else if (c2 == '!') {
                        /* Negative lookahead */
                        dbuf_putstr(&out, "(?!");
                        i += 2;
                    } else if (c2 == '<') {
                        /* Lookbehind or named group */
                        if (i + 3 < len && (js_pattern[i+3] == '=' || js_pattern[i+3] == '!')) {
