    const char *str = (const char *)cbuf;
    const char *p = str + cindex;

    int nmatch = capture_count + 1;
    if (nmatch > MAX_CAPTURES) nmatch = MAX_CAPTURES;

    regmatch_t matches[MAX_CAPTURES];
    memset(matches, -1, sizeof(matches[0]) * nmatch);

    int eflags = 0;
    if (cindex > 0)
        eflags |= REG_NOTBOL;

    int r = regexec(&preg, p, nmatch, matches, eflags);
    regfree(&preg);

    if (r != 0) {
        return 0; /* no match */
    }

    /* Fill capture array */
    for (int i = 0; i < capture_count; i++) {
        if (i < nmatch && matches[i].rm_so >= 0) {
            capture[2*i] = (uint8_t *)(p + matches[i].rm_so);
            capture[2*i+1] = (uint8_t *)(p + matches[i].rm_eo);
        } else {
            capture[2*i] = NULL;
            capture[2*i+1] = NULL;
        }
    }

    return 1;
}
