    bb_put(bb, (v >> 16) & 0xff);
    bb_put(bb, (v >> 24) & 0xff);
    return 0;
}

/* Since implementing a full regexp engine from scratch is very complex,
   and we need QuickJS-compatible behavior, let me use a different approach:

   I'll write a bridge to POSIX extended regex, converting the JS regex syntax
   to POSIX syntax. This won't be perfect but will handle common cases.

   For production use, we need the full QuickJS regexp implementation.
*/

#include <sys/types.h>
#include <regex.h>

#define MAX_CAPTURES 50

/* Our "bytecode" is actually a wrapper around POSIX regex */
typedef struct {
    uint16_t flags;
    uint16_t capture_count;
    uint32_t group_names_offset; /* 0 if no named groups */
    /* actual regex data follows */
    uint32_t pattern_len;
    /* followed by: pattern string (null terminated) */
    /* followed by: group names (if any) */
} ReBC;

/* Convert JS regex to POSIX extended regex */
/* Returns malloc'd string or NULL on error */
static char *js_to_posix_re(const char *js_pattern, int len, int flags,
                              int *pcapture_count, int *phas_named)
{
    DynBuf out;
    int i = 0;
    int capture_count = 1; /* count starts from 1 */
    int has_named = 0;

    dbuf_init(&out);
    *phas_named = 0;

    while (i < len) {
        unsigned char c = (unsigned char)js_pattern[i];

        if (c == '\\') {
            i++;
            if (i >= len) break;
            c = (unsigned char)js_pattern[i];
            switch(c) {
            case 'd':
                dbuf_putstr(&out, "[0-9]");
                break;
            case 'D':
                dbuf_putstr(&out, "[^0-9]");
                break;
            case 'w':
                dbuf_putstr(&out, "[a-zA-Z0-9_]");
                break;
            case 'W':
                dbuf_putstr(&out, "[^a-zA-Z0-9_]");
                break;
            case 's':
                dbuf_putstr(&out, "[ \\t\\n\\r\\f\\v]");
                break;
            case 'S':
                dbuf_putstr(&out, "[^ \\t\\n\\r\\f\\v]");
                break;
            case 'n':
                dbuf_putstr(&out, "\\n");
                break;
            case 'r':
                dbuf_putstr(&out, "\\r");
                break;
            case 't':
                dbuf_putstr(&out, "\\t");
                break;
            case 'b':
                dbuf_putstr(&out, "\\b");
                break;
            case 'B':
                dbuf_putstr(&out, "\\B");
                break;
            case '0':
                dbuf_putstr(&out, "\\0");
                break;
            case 'p': case 'P':
                /* Unicode property - skip for now */
                dbuf_putstr(&out, ".");
                /* skip {name} if present */
                i++;
                if (i < len && js_pattern[i] == '{') {
                    while (i < len && js_pattern[i] != '}') i++;
                }
                i--;
                break;
            default:
                /* Escape the char */
                if ((c >= '0' && c <= '9') || c == '\\' || 
                    c == '.' || c == '*' || c == '+' || c == '?' ||
                    c == '(' || c == ')' || c == '[' || c == ']' ||
                    c == '{' || c == '}' || c == '^' || c == '$' ||
                    c == '|') {
                    dbuf_putc(&out, '\\');
                }
                dbuf_putc(&out, c);
                break;
            }
        } else if (c == '(') {
            /* Check for special groups */
            if (i + 1 < len && js_pattern[i+1] == '?') {
                if (i + 2 < len) {
                    char c2 = js_pattern[i+2];
                    if (c2 == ':') {
                        /* Non-capturing group */
                        dbuf_putstr(&out, "(?:");
                        i += 2;
                    } else if (c2 == '=') {
                        /* Positive lookahead */
                        dbuf_putstr(&out, "(?=");
                        i += 2;
                    } else if (c2 == '!') {
                        /* Negative lookahead */
                        dbuf_putstr(&out, "(?!");
                        i += 2;
                    } else if (c2 == '<') {
                        /* Lookbehind or named group */
                        if (i + 3 < len && (js_pattern[i+3] == '=' || js_pattern[i+3] == '!')) {
                            /* Lookbehind */
                            dbuf_putc(&out, '(');
                            dbuf_putc(&out, '?');
                            dbuf_putc(&out, '<');
                            dbuf_putc(&out, js_pattern[i+3]);
                            capture_count++;
                            i += 3;
                        } else {
                            /* Named group (?<name>...) */
                            has_named = 1;
                            capture_count++;
                            dbuf_putc(&out, '(');
                            /* Skip the name */
                            i += 3;
                            while (i < len && js_pattern[i] != '>') i++;
                            /* i now points to '>' */
                        }
                    } else {
                        dbuf_putc(&out, c);
                        capture_count++;
                    }
                } else {
                    dbuf_putc(&out, c);
                }
            } else {
                dbuf_putc(&out, c);
                capture_count++;
            }
        } else {
            dbuf_putc(&out, c);
        }
        i++;
    }

    dbuf_putc(&out, 0); /* null terminate */
    *pcapture_count = capture_count;
    *phas_named = has_named;
    return (char *)out.buf;
}

/* Compile a JavaScript regex to our bytecode format */
uint8_t *lre_compile(int *plen, char *error_msg, int error_msg_size,
                     const char *buf, size_t buf_len, int re_flags,
                     void *opaque)
{
    (void)opaque;
    int capture_count = 1;
    int has_named = 0;

    /* Convert JS pattern to POSIX */
    char *posix_pat = js_to_posix_re(buf, buf_len, re_flags, &capture_count, &has_named);
    if (!posix_pat) {
        snprintf(error_msg, error_msg_size, "out of memory");
        return NULL;
    }

    /* Validate the regex with POSIX */
    regex_t preg;
    int cflags = REG_EXTENDED;
    if (re_flags & LRE_FLAG_IGNORECASE)
        cflags |= REG_ICASE;
    if (re_flags & LRE_FLAG_MULTILINE)
        cflags |= REG_NEWLINE;

    int r = regcomp(&preg, posix_pat, cflags);
    if (r != 0) {
        char errbuf[256];
        regerror(r, &preg, errbuf, sizeof(errbuf));
        snprintf(error_msg, error_msg_size, "Invalid regular expression: %s", errbuf);
        free(posix_pat);
        return NULL;
    }
    regfree(&preg);

    /* Build our bytecode buffer */
    /* Format:
       [flags:2][capture_count:2][group_names_offset:4][pattern_len:4][pattern:N+1]
    */
    size_t pat_len = strlen(posix_pat);
    size_t total_size = 2 + 2 + 4 + 4 + pat_len + 1;
    /* Also store original JS flags for use during exec */
    /* Store original pattern too for special handling */
    size_t js_pat_len = buf_len;
    total_size += 4 + js_pat_len + 1; /* original JS pattern */
    total_size += 4; /* original flags */

    uint8_t *bc = malloc(total_size);
    if (!bc) {
        free(posix_pat);
        snprintf(error_msg, error_msg_size, "out of memory");
        return NULL;
    }

    size_t pos = 0;
    /* flags */
    bc[pos++] = re_flags & 0xff;
    bc[pos++] = (re_flags >> 8) & 0xff;
    /* capture_count */
    bc[pos++] = capture_count & 0xff;
    bc[pos++] = (capture_count >> 8) & 0xff;
    /* group_names_offset = 0 for now */
    bc[pos++] = 0; bc[pos++] = 0; bc[pos++] = 0; bc[pos++] = 0;
    /* POSIX pattern length */
    bc[pos++] = (pat_len) & 0xff;
    bc[pos++] = (pat_len >> 8) & 0xff;
    bc[pos++] = (pat_len >> 16) & 0xff;
    bc[pos++] = (pat_len >> 24) & 0xff;
    /* POSIX pattern */
    memcpy(bc + pos, posix_pat, pat_len + 1);
    pos += pat_len + 1;
    /* JS pattern length */
    bc[pos++] = (js_pat_len) & 0xff;
    bc[pos++] = (js_pat_len >> 8) & 0xff;
    bc[pos++] = (js_pat_len >> 16) & 0xff;
    bc[pos++] = (js_pat_len >> 24) & 0xff;
    /* JS pattern */
    memcpy(bc + pos, buf, js_pat_len);
    pos += js_pat_len;
    bc[pos++] = 0;
    /* original flags as int */
    bc[pos++] = re_flags & 0xff;
    bc[pos++] = (re_flags >> 8) & 0xff;
    bc[pos++] = (re_flags >> 16) & 0xff;
    bc[pos++] = (re_flags >> 24) & 0xff;

    free(posix_pat);
    *plen = pos;
    return bc;
}

/* Execute compiled regexp */
/* returns 1 if match, 0 if no match, < 0 on error */
/* capture[0], capture[1] = start/end of match */
/* capture[2], capture[3] = group 1 start/end */
/* etc. */
int lre_exec(uint8_t **capture, const uint8_t *bc_buf, const uint8_t *cbuf,
             int cindex, int clen, int cbuf_type, void *opaque)
{
    (void)opaque;

    int re_flags = bc_buf[0] | (bc_buf[1] << 8);
    int capture_count = bc_buf[2] | (bc_buf[3] << 8);

    /* Get POSIX pattern */
    uint32_t posix_pat_len = bc_buf[8] | (bc_buf[9] << 8) | (bc_buf[10] << 16) | (bc_buf[11] << 24);
    const char *posix_pat = (const char *)(bc_buf + 12);

    /* Build POSIX regex */
    regex_t preg;
    int cflags = REG_EXTENDED;
    if (re_flags & LRE_FLAG_IGNORECASE)
        cflags |= REG_ICASE;
    if (re_flags & LRE_FLAG_MULTILINE)
        cflags |= REG_NEWLINE;

    if (regcomp(&preg, posix_pat, cflags) != 0) {
        return -1;
    }

    /* The input string */
    const char *str = (const char *)cbuf;
    const char *p = str + cindex;

    int nmatch = capture_count + 1;
    if (nmatch > MAX_CAPTURES) nmatch = MAX_CAPTURES;

    regmatch_t matches[MAX_CAPTURES];
    memset(matches, -1, sizeof(matches[0]) * nmatch);

    int eflags = 0;
    if (cindex > 0)
        eflags |= REG_NOTBOL;

    int r = regexec(&preg, p, nmatch, matches, eflags);
    regfree(&preg);

    if (r != 0) {
        return 0; /* no match */
    }

    /* Fill capture array */
    for (int i = 0; i < capture_count; i++) {
        if (i < nmatch && matches[i].rm_so >= 0) {
            capture[2*i] = (uint8_t *)(p + matches[i].rm_so);
            capture[2*i+1] = (uint8_t *)(p + matches[i].rm_eo);
        } else {
            capture[2*i] = NULL;
            capture[2*i+1] = NULL;
        }
    }

    return 1;
}
