typedef struct JSObject JSObject;
typedef struct JSClass JSClass;
typedef uint32_t JSClassID;
typedef uint32_t JSAtom;

typedef struct JSValue {
    union {
        int32_t int32;
        double float64;
        void *ptr;
    } u;
    int64_t tag;
} JSValue;

typedef const JSValue JSValueConst;

/* Value tags */
#define JS_TAG_FIRST       (-11)
#define JS_TAG_BIG_DECIMAL (-11)
#define JS_TAG_BIG_INT     (-10)
#define JS_TAG_BIG_FLOAT   (-9)
#define JS_TAG_SYMBOL      (-8)
#define JS_TAG_STRING      (-7)
#define JS_TAG_MODULE      (-3)
#define JS_TAG_FUNCTION_BYTECODE (-2)
#define JS_TAG_OBJECT      (-1)
#define JS_TAG_INT          0
#define JS_TAG_BOOL         1
#define JS_TAG_NULL         2
#define JS_TAG_UNDEFINED    3
#define JS_TAG_UNINITIALIZED 4
#define JS_TAG_CATCH_OFFSET 5
#define JS_TAG_EXCEPTION    6
#define JS_TAG_FLOAT64      7

#define JS_VALUE_GET_TAG(v) ((int32_t)(v).tag)
#define JS_VALUE_GET_INT(v) ((v).u.int32)
#define JS_VALUE_GET_BOOL(v) ((v).u.int32)
#define JS_VALUE_GET_FLOAT64(v) ((v).u.float64)
#define JS_VALUE_GET_PTR(v) ((v).u.ptr)

#define JS_MKVAL(tag, val) (JSValue){ .u = { .int32 = (val) }, .tag = (tag) }
#define JS_MKPTR(tag, ptr) (JSValue){ .u = { .ptr = (ptr) }, .tag = (tag) }

#define JS_NULL      JS_MKVAL(JS_TAG_NULL, 0)
#define JS_UNDEFINED JS_MKVAL(JS_TAG_UNDEFINED, 0)
#define JS_FALSE     JS_MKVAL(JS_TAG_BOOL, 0)
#define JS_TRUE      JS_MKVAL(JS_TAG_BOOL, 1)
#define JS_EXCEPTION JS_MKVAL(JS_TAG_EXCEPTION, 0)
#define JS_UNINITIALIZED JS_MKVAL(JS_TAG_UNINITIALIZED, 0)
#define JS_NAN       (JSValue){ .u = { .float64 = __builtin_nan("") }, .tag = JS_TAG_FLOAT64 }

static inline JS_BOOL JS_IsNumber(JSValueConst v) {
    int tag = JS_VALUE_GET_TAG(v);
    return tag == JS_TAG_INT || tag == JS_TAG_FLOAT64;
}
static inline JS_BOOL JS_IsBigInt(JSContext *ctx, JSValueConst v) {
    (void)ctx;
    return JS_VALUE_GET_TAG(v) == JS_TAG_BIG_INT;
}
static inline JS_BOOL JS_IsBool(JSValueConst v) {
    return JS_VALUE_GET_TAG(v) == JS_TAG_BOOL;
}
static inline JS_BOOL JS_IsNull(JSValueConst v) {
    return JS_VALUE_GET_TAG(v) == JS_TAG_NULL;
}
static inline JS_BOOL JS_IsUndefined(JSValueConst v) {
    return JS_VALUE_GET_TAG(v) == JS_TAG_UNDEFINED;
}
