    JSContext *ctx;
    trace_malloc_data trace_data;
    int optind;
    char *expr = NULL;
    int interactive = 0;
    int dump_memory = 0;
    int trace_memory = 0;
    int empty_run = 0;
    int module = -1;
    int load_std = 0;
    int dump_unhandled_promise_rejection = 1;
    size_t memory_limit = 0;
    char *include_list[32];
    int i, include_count = 0;
    size_t stack_size = 0;
    int strict_mode = 0;

    optind = 1;
    while (optind < argc && *argv[optind] == '-') {
        char *arg = argv[optind] + 1;
        const char *longopt = "";
        if (*arg == '-') {
            longopt = arg + 1;
            arg += strlen(arg);
        }
        if (strstart(longopt, "help", NULL) || (arg[0] == 'h' && arg[1] == '\0')) {
            help();
        } else if (!strcmp(arg, "e") || strstart(longopt, "eval", NULL)) {
            if (optind + 1 >= argc) {
                fprintf(stderr, "qjs: missing expression for -e\n");
                exit(2);
            }
            expr = argv[optind + 1];
            optind++;
        } else if (!strcmp(arg, "I") || strstart(longopt, "include", NULL)) {
            if (optind + 1 >= argc) {
                fprintf(stderr, "qjs: missing filename for -I\n");
                exit(2);
            }
            if (include_count >= (int)(sizeof(include_list)/sizeof(*include_list))) {
                fprintf(stderr, "qjs: too many included files\n");
                exit(2);
            }
            include_list[include_count++] = argv[optind + 1];
            optind++;
        } else if (!strcmp(arg, "i") || strstart(longopt, "interactive", NULL)) {
            interactive++;
        } else if (!strcmp(arg, "m") || strstart(longopt, "module", NULL)) {
            module = 1;
        } else if (strstart(longopt, "script", NULL)) {
            module = 0;
        } else if (strstart(longopt, "strict", NULL)) {
            strict_mode = 1;
        } else if (!strcmp(arg, "d") || strstart(longopt, "dump", NULL)) {
            dump_memory++;
        } else if (!strcmp(arg, "T") || strstart(longopt, "trace", NULL)) {
            trace_memory++;
        } else if (strstart(longopt, "std", NULL)) {
            load_std = 1;
        } else if (strstart(longopt, "no-unhandled-rejection", NULL)) {
            dump_unhandled_promise_rejection = 0;
        } else if (!strcmp(arg, "q") || strstart(longopt, "quit", NULL)) {
            empty_run++;
        } else if (!strcmp(arg, "s")) {
            /* strip: ignored */
        } else if (strstart(longopt, "strip-source", NULL)) {
            /* strip source: ignored */
        } else if (strstart(longopt, "memory-limit", NULL)) {
            if (optind + 1 >= argc) {
                fprintf(stderr, "qjs: missing memory limit\n");
                exit(2);
            }
            memory_limit = parse_memory_size(argv[optind + 1]);
            optind++;
        } else if (strstart(longopt, "stack-size", NULL)) {
            if (optind + 1 >= argc) {
                fprintf(stderr, "qjs: missing stack size\n");
                exit(2);
            }
            stack_size = parse_memory_size(argv[optind + 1]);
            optind++;
        } else {
            fprintf(stderr, "qjs: unknown option '%s'\n", argv[optind]);
            help();
        }
        optind++;
    }

    js_trace_malloc_init(&trace_data);

    if (trace_memory) {
        rt = JS_NewRuntime2(&trace_mf, &trace_data);
    } else {
        rt = JS_NewRuntime();
    }
    if (!rt) {
        fprintf(stderr, "qjs: cannot allocate JS runtime\n");
        exit(2);
    }
    if (memory_limit != 0)
        JS_SetMemoryLimit(rt, memory_limit);
    if (stack_size != 0)
        JS_SetMaxStackSize(rt, stack_size);
    js_std_set_worker_new_context_func(JS_NewCustomContext);
    js_std_init_handlers(rt);
    ctx = JS_NewCustomContext(rt);
    if (!ctx) {
        fprintf(stderr, "qjs: cannot allocate JS context\n");
        exit(2);
    }

    /* loader for ES6 modules */
    JS_SetModuleLoaderFunc(rt, NULL, js_module_loader, NULL);

    if (!dump_unhandled_promise_rejection) {
        JS_SetHostPromiseRejectionTracker(rt, NULL, NULL);
    } else {
        JS_SetHostPromiseRejectionTracker(rt, js_std_promise_rejection_tracker,
                                          NULL);
    }

    if (!empty_run) {
        js_std_add_helpers(ctx, argc - optind, argv + optind);

        if (load_std) {
            const char *str = "import * as std from 'std';\n"
                "import * as os from 'os';\n"
                "globalThis.std = std;\n"
                "globalThis.os = os;\n";
            eval_buf(ctx, str, strlen(str), "<input>", JS_EVAL_TYPE_MODULE);
        }

        for(i = 0; i < include_count; i++) {
            if (eval_file(ctx, include_list[i], module))
                goto fail;
        }

        if (expr) {
            int eval_flags = JS_EVAL_TYPE_GLOBAL;
            if (strict_mode)
                eval_flags |= JS_EVAL_FLAG_STRICT;
            if (eval_buf(ctx, expr, strlen(expr), "<cmdline>", eval_flags))
                goto fail;
        } else if (optind >= argc) {
            interactive = 1;
        } else {
            const char *filename;
            filename = argv[optind];
            if (eval_file(ctx, filename, module))
                goto fail;
        }

        if (interactive) {
            js_std_eval_binary(ctx, qjsc_repl, qjsc_repl_size, 0);
        }
        js_std_loop(ctx);
    }

    if (dump_memory) {
        JSMemoryUsage stats;
        JS_ComputeMemoryUsage(rt, &stats);
        JS_DumpMemoryUsage(stdout, &stats, rt);
    }
    js_std_free_handlers(rt);
    JS_FreeContext(ctx);
    JS_FreeRuntime(rt);
    return 0;
fail:
    js_std_free_handlers(rt);
    JS_FreeContext(ctx);
    JS_FreeRuntime(rt);
    return 1;
}
