#include <stdlib.h>
#include <stdio.h>
#include <stdarg.h>
#include <string.h>
#include <sys/types.h>
#include <regex.h>
#include "cutils.h"

void pstrcpy(char *buf,int buf_size,const char *str){
    int c;char *q=buf;
    if(buf_size<=0)return;
    for(;;){c=*str++;if(c==0||q>=buf+buf_size-1)break;*q++=c;}
    *q='\0';
}
char *pstrcat(char *buf,int buf_size,const char *s){
    int len=strlen(buf);
    if(len<buf_size)pstrcpy(buf+len,buf_size-len,s);
    return buf;
}
int strstart(const char *str,const char *val,const char **ptr){
    const char *p=str,*q=val;
    while(*q!='\0'){if(*p!=*q)return 0;p++;q++;}
    if(ptr)*ptr=p;
    return 1;
}
int has_suffix(const char *str,const char *suffix){
    size_t len=strlen(str),slen=strlen(suffix);
    return(len>=slen&&!memcmp(str+len-slen,suffix,slen));
}
int unicode_to_utf8(uint8_t *buf,unsigned int c){
    uint8_t *q=buf;
    if(c<0x80)*q++=c;
    else if(c<0x800){*q++=(c>>6)|0xc0;*q++=(c&0x3f)|0x80;}
    else if(c<0x10000){*q++=(c>>12)|0xe0;*q++=((c>>6)&0x3f)|0x80;*q++=(c&0x3f)|0x80;}
    else{*q++=(c>>18)|0xf0;*q++=((c>>12)&0x3f)|0x80;*q++=((c>>6)&0x3f)|0x80;*q++=(c&0x3f)|0x80;}
    return q-buf;
}
int unicode_from_utf8(const uint8_t *p,int max_len,const uint8_t **pp){
    int l,c,b,i;
    c=*p++;
    if(c<0x80)l=0;
    else if(c<0xc0)return -1;
    else if(c<0xe0){l=1;c&=0x1f;}
    else if(c<0xf0){l=2;c&=0xf;}
    else if(c<0xf8){l=3;c&=0x7;}
    else return -1;
    if(l>(max_len-1))return -1;
    for(i=0;i<l;i++){b=*p++;if(b<0x80||b>=0xc0)return -1;c=(c<<6)|(b&0x3f);}
    if(pp)*pp=p;
    return c;
}
static void *dbuf_default_realloc(void *opaque,void *ptr,size_t size){(void)opaque;return realloc(ptr,size);}
void dbuf_init2(DynBuf *s,void *opaque,DynBufReallocFunc *realloc_func){
    memset(s,0,sizeof(*s));
    s->realloc_func=realloc_func?realloc_func:dbuf_default_realloc;
    s->opaque=opaque;
}
void dbuf_init(DynBuf *s){dbuf_init2(s,NULL,NULL);}
int dbuf_realloc(DynBuf *s,size_t new_size){
    size_t size;uint8_t *new_buf;
    if(new_size>s->allocated_size){
        if(s->error)return -1;
        size=s->allocated_size*3/2;
        if(size>new_size)new_size=size;
        if(new_size<64)new_size=64;
        new_buf=s->realloc_func(s->opaque,s->buf,new_size);
        if(!new_buf){s->error=TRUE;return -1;}
        s->buf=new_buf;s->allocated_size=new_size;
    }
    return 0;
}
int dbuf_put(DynBuf *s,const uint8_t *data,size_t len){
    if(unlikely((s->size+len)>s->allocated_size)){if(dbuf_realloc(s,s->size+len))return -1;}
    memcpy(s->buf+s->size,data,len);s->size+=len;return 0;
}
int dbuf_putc(DynBuf *s,uint8_t c){return dbuf_put(s,&c,1);}
int dbuf_putstr(DynBuf *s,const char *str){return dbuf_put(s,(const uint8_t *)str,strlen(str));}
int dbuf_printf(DynBuf *s,const char *fmt,...){
    va_list ap;char buf[128];int len;
    va_start(ap,fmt);len=vsnprintf(buf,sizeof(buf),fmt,ap);va_end(ap);
    if(len<(int)sizeof(buf))return dbuf_put(s,(uint8_t *)buf,len);
    char *buf2=malloc(len+1);if(!buf2){s->error=TRUE;return -1;}
    va_start(ap,fmt);vsnprintf(buf2,len+1,fmt,ap);va_end(ap);
    int r=dbuf_put(s,(uint8_t *)buf2,len);free(buf2);return r;
}
void dbuf_free(DynBuf *s){free(s->buf);memset(s,0,sizeof(*s));}

