/* Regexp engine using POSIX regex */
#define MAX_CAPTURES 50

int lre_get_capture_count(const uint8_t *bc_buf){return bc_buf[2]|(bc_buf[3]<<8);}
int lre_get_flags(const uint8_t *bc_buf){return bc_buf[0]|(bc_buf[1]<<8);}
