    uint32_t off=bc_buf[4]|(bc_buf[5]<<8)|(bc_buf[6]<<16)|(bc_buf[7]<<24);
    return off?(const char*)(bc_buf+off):NULL;
}

/* JS->POSIX regex conversion - simplified */
static char *js_re_to_posix(const char *js_pat,int len,int flags,int *pcap,char *group_names,int gnsize){
    DynBuf out;
    dbuf_init(&out);
    int cap=1;
    int i=0;
    while(i<len){
        unsigned char c=(unsigned char)js_pat[i];
        if(c=='\\'){
            i++;
            if(i>=len)break;
            c=(unsigned char)js_pat[i];
            switch(c){
            case 'd':dbuf_putstr(&out,"[0-9]");break;
            case 'D':dbuf_putstr(&out,"[^0-9]");break;
            case 'w':dbuf_putstr(&out,"[a-zA-Z0-9_]");break;
            case 'W':dbuf_putstr(&out,"[^a-zA-Z0-9_]");break;
            case 's':dbuf_putstr(&out,"[ \\t\\n\\r\\f\\v]");break;
            case 'S':dbuf_putstr(&out,"[^ \\t\\n\\r\\f\\v]");break;
            case 'n':dbuf_putstr(&out,"\\n");break;
            case 'r':dbuf_putstr(&out,"\\r");break;
            case 't':dbuf_putstr(&out,"\\t");break;
            case 'b':dbuf_putstr(&out,"\\b");break;
            case 'B':dbuf_putstr(&out,"\\B");break;
            case 'f':dbuf_putstr(&out,"\\f");break;
            case 'v':dbuf_putstr(&out,"\\v");break;
            case 'p':case 'P':
                i++;
                if(i<len&&js_pat[i]=='{'){
                    while(i<len&&js_pat[i]!='}')i++;
                }
                dbuf_putc(&out,'.');
                break;
            default:
                if(c=='.'||c=='*'||c=='+'||c=='?'||c=='('||c==')'||c=='['||c==']'||
                   c=='{'||c=='}'||c=='^'||c=='$'||c=='|'||c=='\\')
                    dbuf_putc(&out,'\\');
                dbuf_putc(&out,c);
                break;
            }
        } else if(c=='('){
            if(i+2<len&&js_pat[i+1]=='?'&&js_pat[i+2]==':'){
                dbuf_putstr(&out,"(?:");i+=2;
            } else if(i+2<len&&js_pat[i+1]=='?'&&js_pat[i+2]=='='){
                dbuf_putstr(&out,"(?=");i+=2;
            } else if(i+2<len&&js_pat[i+1]=='?'&&js_pat[i+2]=='!'){
                dbuf_putstr(&out,"(?!");i+=2;
            } else if(i+3<len&&js_pat[i+1]=='?'&&js_pat[i+2]=='<'&&
                      (js_pat[i+3]=='='||js_pat[i+3]=='!')){
                dbuf_putc(&out,'(');dbuf_putc(&out,'?');
                dbuf_putc(&out,'<');dbuf_putc(&out,js_pat[i+3]);
                cap++;i+=3;
            } else if(i+2<len&&js_pat[i+1]=='?'&&js_pat[i+2]=='<'){
                /* named group */
                i+=3;
                int name_start=i;
                while(i<len&&js_pat[i]!='>')i++;
                /* Store name in group_names */
                cap++;
                dbuf_putc(&out,'(');
            } else {
                dbuf_putc(&out,'(');
                cap++;
            }
        } else if(c=='.'&&(flags&LRE_FLAG_DOTALL)){
            dbuf_putstr(&out,"[\\s\\S]");
        } else {
            dbuf_putc(&out,c);
        }
        i++;
    }
    dbuf_putc(&out,0);
    *pcap=cap;
    return (char*)out.buf;
}

uint8_t *lre_compile(int *plen,char *error_msg,int error_msg_size,const char *buf,size_t buf_len,int re_flags,void *opaque){
    (void)opaque;
    int cap=1;
    char gnbuf[4096]="";
    char *posix_pat=js_re_to_posix(buf,buf_len,re_flags,&cap,gnbuf,sizeof(gnbuf));
    if(!posix_pat){snprintf(error_msg,error_msg_size,"out of memory");return NULL;}

    /* Validate */
    regex_t preg;
    int cflags=REG_EXTENDED;
    if(re_flags&LRE_FLAG_IGNORECASE)cflags|=REG_ICASE;
    if(re_flags&LRE_FLAG_MULTILINE)cflags|=REG_NEWLINE;
    int r=regcomp(&preg,posix_pat,cflags);
    if(r!=0){
        char errbuf[256];
        regerror(r,&preg,errbuf,sizeof(errbuf));
        snprintf(error_msg,error_msg_size,"Invalid regexp: %s",errbuf);
        free(posix_pat);return NULL;
    }
    regfree(&preg);

    /* Build bytecode: [flags:2][cap:2][gnames_off:4][pat_len:4][pattern...] */
    size_t pat_len=strlen(posix_pat);
    /* Also store original pattern for non-POSIX features */
    size_t total=2+2+4+4+pat_len+1+4+buf_len+1;
    uint8_t *bc=malloc(total);
    if(!bc){free(posix_pat);snprintf(error_msg,error_msg_size,"oom");return NULL;}
    size_t pos=0;
    bc[pos++]=re_flags&0xff;bc[pos++]=(re_flags>>8)&0xff;
    bc[pos++]=cap&0xff;bc[pos++]=(cap>>8)&0xff;
    bc[pos++]=0;bc[pos++]=0;bc[pos++]=0;bc[pos++]=0; /* gnames_off=0 */
    bc[pos++]=pat_len&0xff;bc[pos++]=(pat_len>>8)&0xff;bc[pos++]=(pat_len>>16)&0xff;bc[pos++]=(pat_len>>24)&0xff;
    memcpy(bc+pos,posix_pat,pat_len+1);pos+=pat_len+1;
    bc[pos++]=buf_len&0xff;bc[pos++]=(buf_len>>8)&0xff;bc[pos++]=(buf_len>>16)&0xff;bc[pos++]=(buf_len>>24)&0xff;
    memcpy(bc+pos,buf,buf_len);pos+=buf_len;bc[pos++]=0;
    free(posix_pat);
    *plen=pos;
    return bc;
}

int lre_exec(uint8_t **capture,const uint8_t *bc_buf,const uint8_t *cbuf,int cindex,int clen,int cbuf_type,void *opaque){
    (void)opaque;(void)clen;(void)cbuf_type;
    int re_flags=bc_buf[0]|(bc_buf[1]<<8);
    int cap_count=bc_buf[2]|(bc_buf[3]<<8);
    uint32_t pat_len=bc_buf[8]|(bc_buf[9]<<8)|(bc_buf[10]<<16)|(bc_buf[11]<<24);
    const char *posix_pat=(const char*)(bc_buf+12);

    regex_t preg;
    int cflags=REG_EXTENDED;
    if(re_flags&LRE_FLAG_IGNORECASE)cflags|=REG_ICASE;
    if(re_flags&LRE_FLAG_MULTILINE)cflags|=REG_NEWLINE;
    if(regcomp(&preg,posix_pat,cflags)!=0)return -1;

    const char *str=(const char*)cbuf;
    const char *p=str+cindex;
    int nm=cap_count+1;if(nm>MAX_CAPTURES)nm=MAX_CAPTURES;
    regmatch_t matches[MAX_CAPTURES];
    memset(matches,-1,sizeof(matches[0])*nm);
    int eflags=cindex>0?REG_NOTBOL:0;
    int r=regexec(&preg,p,nm,matches,eflags);
    regfree(&preg);
    if(r!=0)return 0;
    for(int i=0;i<cap_count&&i<nm;i++){
        if(matches[i].rm_so>=0){
            capture[2*i]=(uint8_t*)(p+matches[i].rm_so);
            capture[2*i+1]=(uint8_t*)(p+matches[i].rm_eo);
        } else {
            capture[2*i]=NULL;capture[2*i+1]=NULL;
        }
    }
    return 1;
}
