/*
 * QuickJS stand alone interpreter
 * Copyright (c) 2017-2021 Fabrice Bellard
 * Copyright (c) 2017-2021 Charlie Gordon
 */
#include <stdlib.h>
#include <stdio.h>
#include <stdarg.h>
#include <inttypes.h>
#include <string.h>
#include <assert.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <time.h>
#if defined(__linux__)
#include <malloc.h>
#endif
#include "cutils.h"
#include "quickjs-libc.h"
extern const uint8_t qjsc_repl[];
extern const uint32_t qjsc_repl_size;

static int eval_buf(JSContext *ctx,const void *buf,int buf_len,const char *filename,int eval_flags){
    JSValue val;int ret;
    if((eval_flags&JS_EVAL_TYPE_MASK)==JS_EVAL_TYPE_MODULE){
        val=JS_Eval(ctx,buf,buf_len,filename,eval_flags|JS_EVAL_FLAG_COMPILE_ONLY);
        if(!JS_IsException(val)){
            js_module_set_import_meta(ctx,val,1,1);
            val=JS_EvalFunction(ctx,val);
        }
    } else {
        val=JS_Eval(ctx,buf,buf_len,filename,eval_flags);
    }
    if(JS_IsException(val)){js_std_dump_error(ctx);ret=-1;}
    else ret=0;
    JS_FreeValue(ctx,val);
    return ret;
}

static int eval_file(JSContext *ctx,const char *filename,int module){
    uint8_t *buf;int ret,eval_flags;size_t buf_len;
    buf=js_load_file(ctx,&buf_len,filename);
    if(!buf){fprintf(stderr,"%s: %s\n",filename,strerror(errno));exit(1);}
    if(module<0)module=(has_suffix(filename,".mjs")||JS_DetectModule((const char*)buf,buf_len));
    eval_flags=module?JS_EVAL_TYPE_MODULE:JS_EVAL_TYPE_GLOBAL;
    ret=eval_buf(ctx,buf,buf_len,filename,eval_flags);
    js_free(ctx,buf);
    return ret;
}

static JSContext *JS_NewCustomContext(JSRuntime *rt){
    JSContext *ctx=JS_NewContext(rt);
    if(!ctx)return NULL;
    JS_AddIntrinsicBigInt(ctx);
    return ctx;
}

static uint64_t parse_memory_size(const char *str){
    char *p;uint64_t v=strtoull(str,&p,10);
    if(*p){char c=*p;if(c=='k'||c=='K')v*=1024;else if(c=='m'||c=='M')v*=1024*1024;else if(c=='g'||c=='G')v*=(uint64_t)1024*1024*1024;}
    return v;
}

static void help(void){
    printf("QuickJS version " CONFIG_VERSION "\n"
           "usage: qjs [options] [file [args]]\n"
           "-h  --help         list options\n"
           "-e  --eval EXPR    evaluate EXPR\n"
           "-i  --interactive  go to interactive mode\n"
           "-m  --module       load as ES6 module (default=autodetect)\n"
           "    --script       load as ES6 script (default=autodetect)\n"
           "    --strict       force strict mode\n"
           "-I  --include file include an additional file\n"
           "    --std          make 'std' and 'os' available to the loaded script\n"
           "-T  --trace        trace memory allocation\n"
           "-d  --dump         dump the memory usage stats\n"
           "    --memory-limit n  limit the memory usage to 'n' bytes (SI suffixes allowed)\n"
           "    --stack-size n    limit the stack size to 'n' bytes (SI suffixes allowed)\n"
           "    --no-unhandled-rejection  ignore unhandled promise rejections\n"
           "-s                    strip all the debug info\n"
           "    --strip-source    strip the source code\n"
           "-q  --quit         just instantiate the interpreter and quit\n");
    exit(1);
}

static void *js_trace_malloc(JSMallocState *s,size_t size){
    void *p=malloc(size);
    if(p){s->malloc_count++;s->malloc_size+=size;}
    return p;
}
static void js_trace_free(JSMallocState *s,void *ptr){(void)s;free(ptr);}
static void *js_trace_realloc(JSMallocState *s,void *ptr,size_t size){(void)s;return realloc(ptr,size);}
