_HOLE = object()  # Represents array hole

class JSFunction(JSObject):
    def __init__(self, fn, name='', length=0, proto=None):
        super().__init__(proto)
        self._class = 'Function'
        self._call = fn
        self._name = name
        self._length = length
        # All functions have a prototype property (except arrows)
        self._is_arrow = False
        self._is_generator = False
        self._is_async = False
        self._home_object = None  # for methods

class JSRegExp(JSObject):
    def __init__(self, pattern, flags, proto=None):
        super().__init__(proto)
        self._class = 'RegExp'
        self._pattern = pattern
        self._flags = flags
        self._last_index = 0
        try:
            py_flags = 0
            if 'i' in flags: py_flags |= re.IGNORECASE
            if 'm' in flags: py_flags |= re.MULTILINE
            if 's' in flags: py_flags |= re.DOTALL
            # Convert JS pattern to Python
            self._py_re = re.compile(js_regex_to_python(pattern), py_flags)
        except Exception as e:
            raise JSError(f"Invalid regular expression: /{pattern}/{flags}: {e}", 'SyntaxError')

class JSError(Exception):
    def __init__(self, message, error_type='Error', stack=None):
        self.message = message
        self.error_type = error_type
        self.js_stack = stack or []
        super().__init__(message)

class JSThrow(Exception):
    def __init__(self, value):
        self.value = value
        super().__init__(str(value))

class JSReturn(Exception):
    def __init__(self, value):
        self.value = value

class JSBreak(Exception):
    def __init__(self, label=None):
        self.label = label

class JSContinue(Exception):
    def __init__(self, label=None):
        self.label = label

# ===== Number formatting (matching QuickJS) =====

def num_to_string(n):
    """Convert a number to string, matching JavaScript's Number.prototype.toString()"""
    if isinstance(n, bool): return 'true' if n else 'false'
    if math.isnan(n): return 'NaN'
    if math.isinf(n): return 'Infinity' if n > 0 else '-Infinity'
    # Check if it's -0
    if n == 0:
        if math.copysign(1, n) < 0: return '0'  # -0 becomes '0' in string context
        return '0'
    # Integer check
    if n == int(n) and abs(n) < 1e21:
        return str(int(n))
    # Use Python's repr for shortest representation
    s = repr(n)
    # Python uses 'e+XX' notation, JS uses 'e+X' for single digit
    # But Python's repr should give shortest round-trip representation
    # Convert Python scientific notation to JS format
    if 'e' in s:
        m, e = s.split('e')
        e = int(e)
        s = f"{m}e+{e}" if e >= 0 else f"{m}e{e}"
        # Remove trailing zeros before e
        if '.' in m:
            m = m.rstrip('0').rstrip('.')
            s = f"{m}e+{e}" if e >= 0 else f"{m}e{e}"
    return s

def js_num_to_str(n):
    """JS number to string, including -0"""
    if isinstance(n, bool): return 'true' if n else 'false'
    if math.isnan(n): return 'NaN'
    if math.isinf(n): return 'Infinity' if n > 0 else '-Infinity'
    if n == 0:
        if math.copysign(1, n) < 0: return '0'
        return '0'
    if n == int(n) and -1e21 < n < 1e21:
        i = int(n)
        if i == n: return str(i)
    # Use Python formatting to get shortest round-trip
    # Python's repr gives 17 sig digits maximum
    # We want the shortest representation that round-trips
    s = format(n, '.17g')
    # But we want shortest, so try fewer digits
    for prec in range(1, 18):
        candidate = format(n, f'.{prec}g')
        try:
            if float(candidate) == n:
                s = candidate
                break
        except: pass
    # Convert to JS format
    if 'e' in s:
        m, exp = s.split('e')
        exp_int = int(exp)
        if '.' in m:
            m = m.rstrip('0')
            if m.endswith('.'): m = m[:-1]
        s = f"{m}e+{exp_int}" if exp_int >= 0 else f"{m}e{exp_int}"
    return s

def inspect_num(n):
    """Display a number value in inspect mode (for console.log of objects)"""
    if math.isnan(n): return 'NaN'
    if math.isinf(n): return 'Infinity' if n > 0 else '-Infinity'
    if n == 0 and math.copysign(1, n) < 0: return '-0'
    return js_num_to_str(n)

# ===== Inspect (console.log output format) =====

def inspect_value(v, depth=0, seen=None, in_object=False):
    """Convert a value to string for console.log output (QuickJS format)"""
    if seen is None: seen = set()

    if isinstance(v, bool): return 'true' if v else 'false'
    if v is null: return 'null'
    if v is undefined: return 'undefined'
    if isinstance(v, (int, float)) and not isinstance(v, bool):
        return inspect_num(float(v))
    if isinstance(v, str):
        if in_object:
            return json.dumps(v)  # quoted
        return v  # unquoted for top-level
    if isinstance(v, JSBigInt):
        return f'{v.value}n'
    if isinstance(v, JSSymbol):
        return str(v)

    if isinstance(v, JSObject):
        oid = id(v)
        if oid in seen:
            # Check depth for [Object]/[Array]
            if isinstance(v, JSArray):
                return '[Array]'
            return '[circular 0]'  # simplified circular reference

        # Check depth limit
        if depth >= 2:
            if isinstance(v, JSArray): return '[Array]'
            return '[Object]'

        seen2 = seen | {oid}

        # Error objects
        if v._class == 'Error' or (isinstance(v._proto, JSObject) and _is_error_like(v)):
            return _inspect_error(v, depth, seen2)

        # Function
        if v._class == 'Function' or v._call is not None:
            fname = v._name or ''
            return f'[Function {fname}]' if fname else '[Function (anonymous)]'

        # RegExp
        if v._class == 'RegExp':
            return f'/{v._pattern}/{v._flags}'

        # Date
        if v._class == 'Date' and hasattr(v, '_date_ms'):
            import datetime
            try:
                dt = datetime.datetime.utcfromtimestamp(v._date_ms / 1000)
                return dt.strftime('%Y-%m-%dT%H:%M:%S.') + f'{v._date_ms % 1000:03d}Z'
            except: return 'Invalid Date'

        # Generator
        if v._class == 'Generator':
            return 'Generator {  }'

        # Promise
        if v._class == 'Promise':
            return 'Promise {  }'

        # Map
        if v._class == 'Map' and hasattr(v, '_map_data'):
            items = v._map_data
            if not items: return 'Map(0) {}'
            parts = []
            for k, val in items:
                kstr = inspect_value(k, depth+1, seen2, True)
                vstr = inspect_value(val, depth+1, seen2, True)
                parts.append(f'{kstr} => {vstr}')
            return f'Map({len(items)}) ' + '{ ' + ', '.join(parts) + ' }'

        # Set
        if v._class == 'Set' and hasattr(v, '_set_data'):
            items = v._set_data
            if not items: return 'Set(0) {}'
            parts = [inspect_value(item, depth+1, seen2, True) for item in items]
            return f'Set({len(items)}) ' + '{ ' + ', '.join(parts) + ' }'

        # WeakMap
        if v._class == 'WeakMap': return 'WeakMap {  }'
        # WeakSet
        if v._class == 'WeakSet': return 'WeakSet {  }'
        # WeakRef
        if v._class == 'WeakRef': return 'WeakRef {  }'

        # ArrayBuffer
        if v._class == 'ArrayBuffer': return 'ArrayBuffer {  }'
        if v._class == 'DataView': return 'DataView {  }'

        # TypedArrays
        if v._class in ('Uint8Array', 'Int8Array', 'Uint16Array', 'Int16Array',
                       'Uint32Array', 'Int32Array', 'Float32Array', 'Float64Array',
                       'BigInt64Array', 'BigUint64Array', 'Uint8ClampedArray') and hasattr(v, '_buffer'):
            n = len(v._buffer) // v._element_size
            items = []
            for i in range(n):
                items.append(inspect_value(v._typed_get(i), depth+1, seen2, True))
            if not items: return f'{v._class}(0) []'
            return f'{v._class}({n}) [ ' + ', '.join(items) + ' ]'

        # Proxy - show as Object
        if v._class == 'Proxy':
            return 'Object {  }'

        # Array
        if isinstance(v, JSArray):
            return _inspect_array(v, depth, seen2)

        # Regular object
        return _inspect_object(v, depth, seen2)

    return str(v)

def _is_error_like(obj):
    """Check if object is an Error instance"""
    if not isinstance(obj, JSObject): return False
    p = obj._proto
    while p is not None:
        if p._class == 'Error': return True
        p = p._proto
    return obj._class == 'Error'

def _inspect_error(v, depth, seen):
    """Format error for console.log"""
    name = _get_js_prop(v, 'name')
    if name is undefined or not isinstance(name, str): name = 'Error'
    msg = _get_js_prop(v, 'message')
    if msg is undefined or not isinstance(msg, str): msg = ''
    stack = _get_js_prop(v, 'stack')

    # Check if there are own properties beyond name, message, stack
    extra_props = {}
    for k, pv in v._props.items():
        if isinstance(k, str) and k not in ('name', 'message', 'stack') and pv.get('enumerable', True):
            extra_props[k] = pv.get('value', undefined)

    if msg:
        result = f'{name}: {msg}'
    else:
        result = name

    if isinstance(stack, str):
        result = stack

    if extra_props:
        prop_parts = []
        for k, val in extra_props.items():
            prop_parts.append(f'{k}: {inspect_value(val, depth+1, seen, True)}')
        result += ' { ' + ', '.join(prop_parts) + ' }'

    return result

def _inspect_array(v, depth, seen):
    """Format array for console.log"""
    items = []
    has_sparse = False

    # Check for sparse array
    if len(v._items) < v._length:
        has_sparse = True

    if has_sparse or any(x is _HOLE for x in v._items):
        # Sparse display: show "index: value"
        parts = []
        for i in range(v._length):
            if i < len(v._items) and v._items[i] is not _HOLE:
                val = v._items[i]
                parts.append(f'{i}: {inspect_value(val, depth+1, seen, True)}')
        # Also non-integer keys
        for k, prop in v._props.items():
            if isinstance(k, str) and not k.isdigit():
                if prop.get('enumerable', True):
                    parts.append(f'{_key_str(k)}: {inspect_value(prop.get("value", undefined), depth+1, seen, True)}')
        if not parts: return '[  ]'
        return '[ ' + ', '.join(parts) + ' ]'

    parts = []
    for i in range(len(v._items)):
        if i < v._length:
            item = v._items[i]
            if item is _HOLE:
                parts.append('<1 empty item>')
            else:
                parts.append(inspect_value(item, depth+1, seen, True))

    # Non-integer keys
    for k, prop in v._props.items():
        if isinstance(k, str) and not k.isdigit():
            if prop.get('enumerable', True):
                parts.append(f'{_key_str(k)}: {inspect_value(prop.get("value", undefined), depth+1, seen, True)}')

    if not parts: return '[  ]'
    return '[ ' + ', '.join(parts) + ' ]'

def _key_str(k):
    """Format a key for inspect output"""
    if isinstance(k, JSSymbol):
        desc = k.description or ''
        return desc
    if isinstance(k, str):
        # Check if it's a valid identifier
        if re.match(r'^[a-zA-Z_$][a-zA-Z0-9_$]*$', k) or re.match(r'^\d+$', k):
            return k
        return json.dumps(k)
    return str(k)

def _inspect_object(v, depth, seen):
    """Format object for console.log"""
    parts = []

    # Get class name for display
    tag = None
    if _sym_toStringTag in v._props:
        prop = v._props[_sym_toStringTag]
        if isinstance(prop.get('value'), str):
            tag = prop['value']

    for k, prop in v._props.items():
        if isinstance(k, JSSymbol):
            if prop.get('enumerable', True):
                desc = k.description or ''
                val = prop.get('value', undefined)
                if val is undefined and 'get' in prop:
                    parts.append(f'{desc}: [Getter]' if prop['set'] is undefined else f'{desc}: [Getter/Setter]')
                else:
                    parts.append(f'{desc}: {inspect_value(val, depth+1, seen, True)}')
            continue
        if not isinstance(k, str): continue
        if not prop.get('enumerable', True): continue

        if 'get' in prop:
            has_set = prop.get('set') is not undefined
            if has_set:
                parts.append(f'{_key_str(k)}: [Getter/Setter]')
            else:
                parts.append(f'{_key_str(k)}: [Getter]')
        else:
            val = prop.get('value', undefined)
            parts.append(f'{_key_str(k)}: {inspect_value(val, depth+1, seen, True)}')

    if not parts: return '{  }'
    return '{ ' + ', '.join(parts) + ' }'

def _get_js_prop(obj, key):
    """Get property from JS object"""
    if isinstance(obj, JSObject):
        return obj._get(key)
    return undefined

# ===== Type conversion =====

def to_primitive(v, hint='default'):
    if v is null or v is undefined: return v
    if isinstance(v, bool): return v
    if isinstance(v, (int, float)): return v
    if isinstance(v, str): return v
    if isinstance(v, JSBigInt): return v
    if isinstance(v, JSSymbol): return v
    if isinstance(v, JSObject):
        # Check for Symbol.toPrimitive
        tp = v._get(_sym_toPrimitive)
        if tp is not undefined and callable_check(tp):
            result = js_call(tp, v, [hint])
            if not isinstance(result, JSObject): return result
            raise JSError("Cannot convert object to primitive value", 'TypeError')

        if hint == 'string':
            # Try toString first
            ts = v._get('toString')
            if callable_check(ts):
                result = js_call(ts, v, [])
                if not isinstance(result, JSObject): return result
            vo = v._get('valueOf')
            if callable_check(vo):
                result = js_call(vo, v, [])
                if not isinstance(result, JSObject): return result
        else:
            # Try valueOf first (number or default)
            vo = v._get('valueOf')
            if callable_check(vo):
                result = js_call(vo, v, [])
                if not isinstance(result, JSObject): return result
            ts = v._get('toString')
            if callable_check(ts):
                result = js_call(ts, v, [])
                if not isinstance(result, JSObject): return result
        raise JSError("Cannot convert object to primitive value", 'TypeError')
    return v

def to_number(v):
    if isinstance(v, bool): return 1.0 if v else 0.0
    if v is null: return 0.0
    if v is undefined: return float('nan')
    if isinstance(v, (int, float)) and not isinstance(v, bool): return float(v)
    if isinstance(v, JSBigInt): raise JSError("Cannot convert a BigInt value to a number", 'TypeError')
    if isinstance(v, str):
        s = v.strip()
        if s == '': return 0.0
        if s == 'Infinity' or s == '+Infinity': return float('inf')
        if s == '-Infinity': return float('-inf')
        try:
            if s.startswith('0x') or s.startswith('0X'):
                return float(int(s, 16))
            if s.startswith('0o') or s.startswith('0O'):
                return float(int(s, 8))
            if s.startswith('0b') or s.startswith('0B'):
                return float(int(s, 2))
            return float(s)
        except: return float('nan')
    if isinstance(v, JSObject):
        prim = to_primitive(v, 'number')
        return to_number(prim)
    return float('nan')

def to_integer(v):
    n = to_number(v)
    if math.isnan(n): return 0
    if math.isinf(n): return n
    return float(int(n))

def to_int32(v):
    n = to_number(v)
    if math.isnan(n) or math.isinf(n) or n == 0: return 0
    i = int(n) & 0xFFFFFFFF
    if i >= 0x80000000: i -= 0x100000000
    return i

def to_uint32(v):
    n = to_number(v)
    if math.isnan(n) or math.isinf(n) or n == 0: return 0
    return int(n) & 0xFFFFFFFF

def to_string(v):
    if isinstance(v, bool): return 'true' if v else 'false'
    if v is null: return 'null'
    if v is undefined: return 'undefined'
    if isinstance(v, str): return v
    if isinstance(v, (int, float)) and not isinstance(v, bool):
        return js_num_to_str(float(v))
    if isinstance(v, JSBigInt): return str(v.value)
    if isinstance(v, JSSymbol): raise JSError("Cannot convert a Symbol value to a string", 'TypeError')
    if isinstance(v, JSObject):
        prim = to_primitive(v, 'string')
        return to_string(prim)
    return str(v)

def to_boolean(v):
    if isinstance(v, bool): return v
    if v is null or v is undefined: return False
    if isinstance(v, (int, float)) and not isinstance(v, bool):
        return v != 0 and not math.isnan(v)
    if isinstance(v, str): return len(v) > 0
    if isinstance(v, JSBigInt): return v.value != 0
    if isinstance(v, JSObject): return True
    return bool(v)

def to_object(v, ctx=None):
    if v is null: raise JSError("Cannot convert null to object", 'TypeError')
    if v is undefined: raise JSError("Cannot convert undefined to object", 'TypeError')
    if isinstance(v, JSObject): return v
    # Wrap primitives
    if isinstance(v, bool):
        obj = JSObject(g_boolean_proto)
        obj._class = 'Boolean'
        obj._primitive_value = v
        return obj
    if isinstance(v, (int, float)):
        obj = JSObject(g_number_proto)
        obj._class = 'Number'
        obj._primitive_value = float(v)
        return obj
    if isinstance(v, str):
        obj = JSObject(g_string_proto)
        obj._class = 'String'
        obj._primitive_value = v
        return obj
    if isinstance(v, JSSymbol):
        obj = JSObject(g_symbol_proto)
        obj._class = 'Symbol'
        obj._primitive_value = v
        return obj
    if isinstance(v, JSBigInt):
        obj = JSObject(g_bigint_proto)
        obj._class = 'BigInt'
        obj._primitive_value = v
        return obj
    return v

def callable_check(v):
    return isinstance(v, JSObject) and (v._call is not None)

def is_constructor(v):
    return isinstance(v, JSObject) and (v._construct is not None or (v._call is not None and not getattr(v, '_is_arrow', False)))

# ===== JS call/construct =====

def js_call(func, this, args, new_target=None):
    if not isinstance(func, JSObject) or func._call is None:
        name = func._name if isinstance(func, JSObject) and func._name else str(func)
        raise JSError(f"'{name}' is not a function", 'TypeError')
    try:
        result = func._call(this, args, new_target)
        if result is None: return undefined
        return result
    except JSReturn as e:
        return e.value
    except JSError as e:
        raise JSThrow(make_error(e.error_type, e.message, e.js_stack))
    except JSThrow:
        raise

def js_construct(func, args, new_target=None):
    if new_target is None: new_target = func
    if not isinstance(func, JSObject):
        raise JSError(f"not a constructor", 'TypeError')
    if func._construct is not None:
        return func._construct(args, new_target)
    elif func._call is not None:
        # Default construct: create new object with func.prototype
        proto_val = func._get('prototype')
        if not isinstance(proto_val, JSObject):
            proto_val = g_object_proto
        obj = JSObject(proto_val)
        result = func._call(obj, args, new_target)
        if isinstance(result, JSObject): return result
        return obj
    else:
        raise JSError(f"'{func._name or ''}' is not a constructor", 'TypeError')

# ===== Equality =====

def js_equal(a, b):
    """Abstract equality (==)"""
    ta = type(a)
    tb = type(b)

    # Same type
    if ta == tb or (isinstance(a, (int, float)) and isinstance(b, (int, float)) and not isinstance(a, bool) and not isinstance(b, bool)):
        return js_strict_equal(a, b)
    if isinstance(a, bool) and isinstance(b, bool): return a == b

    # null == undefined
    if (a is null and b is undefined) or (a is undefined and b is null): return True
    if a is null or b is null: return False
    if a is undefined or b is undefined: return False

    # number == string
    if isinstance(a, (int, float)) and not isinstance(a, bool) and isinstance(b, str):
        return js_strict_equal(a, to_number(b))
    if isinstance(b, (int, float)) and not isinstance(b, bool) and isinstance(a, str):
        return js_strict_equal(to_number(a), b)

    # bool == X: convert bool to number
    if isinstance(a, bool):
        return js_equal(1 if a else 0, b)
    if isinstance(b, bool):
        return js_equal(a, 1 if b else 0)

    # object == primitive: toprimitive
    if isinstance(a, JSObject) and isinstance(b, (str, int, float, JSBigInt)) and not isinstance(b, bool):
        return js_equal(to_primitive(a), b)
    if isinstance(b, JSObject) and isinstance(a, (str, int, float, JSBigInt)) and not isinstance(a, bool):
        return js_equal(a, to_primitive(b))

    # BigInt == string/number
    if isinstance(a, JSBigInt) and isinstance(b, str):
        try: return a.value == int(b)
        except: return False
    if isinstance(b, JSBigInt) and isinstance(a, str):
        try: return b.value == int(a)
        except: return False
    if isinstance(a, JSBigInt) and isinstance(b, (int, float)) and not isinstance(b, bool):
        if math.isnan(b) or math.isinf(b): return False
        return a.value == b
    if isinstance(b, JSBigInt) and isinstance(a, (int, float)) and not isinstance(a, bool):
        if math.isnan(a) or math.isinf(a): return False
        return b.value == a

    return False

def js_strict_equal(a, b):
    """Strict equality (===)"""
    if type(a) != type(b):
        # Allow int/float comparison
        if isinstance(a, (int, float)) and not isinstance(a, bool) and isinstance(b, (int, float)) and not isinstance(b, bool):
            if math.isnan(a) or math.isnan(b): return False
            return float(a) == float(b)
        return False
    if a is null and b is null: return True
    if a is undefined and b is undefined: return True
    if isinstance(a, bool): return a == b
    if isinstance(a, (int, float)) and not isinstance(a, bool):
        if math.isnan(a) or math.isnan(b): return False
        return float(a) == float(b)
    if isinstance(a, str): return a == b
    if isinstance(a, JSSymbol): return a is b
    if isinstance(a, JSBigInt): return a.value == b.value
    if isinstance(a, JSObject): return a is b
    return a == b

def js_less_than(a, b, reverse=False):
    """< comparison"""
    if reverse:
        a, b = b, a

    px = to_primitive(a, 'number')
    py = to_primitive(b, 'number')

    if isinstance(px, str) and isinstance(py, str):
        return px < py

    if isinstance(px, JSBigInt) and isinstance(py, JSBigInt):
        return px.value < py.value
    if isinstance(px, JSBigInt) and isinstance(py, (int, float)):
        if math.isnan(py): return undefined
        return px.value < py
    if isinstance(py, JSBigInt) and isinstance(px, (int, float)):
        if math.isnan(px): return undefined
        return px < py.value
    if isinstance(px, JSBigInt) and isinstance(py, str):
        try: return px.value < int(py)
        except: return undefined
    if isinstance(py, JSBigInt) and isinstance(px, str):
        try: return int(px) < py.value
        except: return undefined

    nx = to_number(px)
    ny = to_number(py)
    if math.isnan(nx) or math.isnan(ny): return undefined
    if math.isinf(nx) and nx > 0: return False
    if math.isinf(ny) and ny > 0: return True
    if math.isinf(nx) and nx < 0: return True
    if math.isinf(ny) and ny < 0: return False
    return nx < ny

# ===== JS regex to Python regex =====

def js_regex_to_python(pattern):
    """Convert JS regex pattern to Python regex pattern"""
    # Handle some common differences
    result = []
    i = 0
    while i < len(pattern):
        c = pattern[i]
        if c == '\\':
            if i + 1 < len(pattern):
                nc = pattern[i+1]
                if nc == 'k':
                    # Named back reference \k<name>
                    if i + 2 < len(pattern) and pattern[i+2] == '<':
                        j = i + 3
                        while j < len(pattern) and pattern[j] != '>':
                            j += 1
                        name = pattern[i+3:j]
                        result.append(f'(?P={name})')
                        i = j + 1
                        continue
                elif nc == 'p' or nc == 'P':
                    # Unicode property - skip with .
                    result.append('.')
                    i += 2
                    if i < len(pattern) and pattern[i] == '{':
                        while i < len(pattern) and pattern[i] != '}':
                            i += 1
                    continue
                elif nc == 'c':
                    # Control character \cX
                    if i + 2 < len(pattern):
                        cc = pattern[i+2]
                        result.append(chr(ord(cc) % 32))
                        i += 3
                        continue
                result.append(c)
                result.append(nc)
                i += 2
                continue
        elif c == '(':
            if i + 2 < len(pattern) and pattern[i+1] == '?' and pattern[i+2] == '<':
                # Named group (?<name>...) or lookbehind (?<=...) (?<!...)
                if i + 3 < len(pattern) and pattern[i+3] in '=!':
                    # Lookbehind - Python supports these
                    result.append(c)
                else:
                    # Named group - convert to Python named group
                    j = i + 3
                    while j < len(pattern) and pattern[j] != '>':
                        j += 1
                    name = pattern[i+3:j]
                    result.append(f'(?P<{name}>')
                    i = j + 1
                    continue
        result.append(c)
        i += 1
    return ''.join(result)

# ===== Global variables (prototypes etc.) =====

g_object_proto = None
g_function_proto = None
g_array_proto = None
g_string_proto = None
g_number_proto = None
g_boolean_proto = None
