def js_regex_to_python(pattern):
    """Convert JS regex pattern to Python regex pattern"""
    # Handle some common differences
    result = []
    i = 0
    while i < len(pattern):
        c = pattern[i]
        if c == '\\':
            if i + 1 < len(pattern):
                nc = pattern[i+1]
                if nc == 'k':
                    # Named back reference \k<name>
                    if i + 2 < len(pattern) and pattern[i+2] == '<':
                        j = i + 3
                        while j < len(pattern) and pattern[j] != '>':
                            j += 1
                        name = pattern[i+3:j]
                        result.append(f'(?P={name})')
                        i = j + 1
                        continue
                elif nc == 'p' or nc == 'P':
                    # Unicode property - skip with .
                    result.append('.')
                    i += 2
                    if i < len(pattern) and pattern[i] == '{':
                        while i < len(pattern) and pattern[i] != '}':
                            i += 1
                    continue
                elif nc == 'c':
                    # Control character \cX
                    if i + 2 < len(pattern):
                        cc = pattern[i+2]
                        result.append(chr(ord(cc) % 32))
                        i += 3
                        continue
                result.append(c)
                result.append(nc)
                i += 2
                continue
        elif c == '(':
            if i + 2 < len(pattern) and pattern[i+1] == '?' and pattern[i+2] == '<':
                # Named group (?<name>...) or lookbehind (?<=...) (?<!...)
                if i + 3 < len(pattern) and pattern[i+3] in '=!':
                    # Lookbehind - Python supports these
                    result.append(c)
                else:
                    # Named group - convert to Python named group
                    j = i + 3
                    while j < len(pattern) and pattern[j] != '>':
                        j += 1
                    name = pattern[i+3:j]
                    result.append(f'(?P<{name}>')
                    i = j + 1
                    continue
        result.append(c)
        i += 1
    return ''.join(result)

# ===== Global variables (prototypes etc.) =====

g_object_proto = None
g_function_proto = None
g_array_proto = None
g_string_proto = None
g_number_proto = None
g_boolean_proto = None
g_symbol_proto = None
