# ===== Scope / Environment =====

class Scope:
    def __init__(self, parent=None, is_block=False):
        self.vars = {}
        self.parent = parent
        self.is_block = is_block
        self.this_val = None  # None means inherit from parent
        self._is_strict = False
        self._module_exports = None  # for module scope

    def get(self, name):
        if name in self.vars:
            v = self.vars[name]
            if v is _UNINITIALIZED:
                raise JSError(f"Cannot access '{name}' before initialization", 'ReferenceError')
            return v
        if self.parent:
            return self.parent.get(name)
        # Check global object
        if g_global:
            v = g_global._get(name)
            if v is not undefined: return v
        raise JSError(f"'{name}' is not defined", 'ReferenceError')

    def set(self, name, value, strict=False):
        scope = self
        while scope:
            if name in scope.vars:
                scope.vars[name] = value
                return
            scope = scope.parent
        # Set on global
        if g_global:
            if strict:
                raise JSError(f"'{name}' is not defined", 'ReferenceError')
            g_global._set(name, value)
        elif strict:
            raise JSError(f"'{name}' is not defined", 'ReferenceError')

    def define_var(self, name, value=undefined):
        self.vars[name] = value

    def define_let(self, name, value=_UNINITIALIZED):
        self.vars[name] = value

    def get_this(self):
        scope = self
        while scope:
            if scope.this_val is not None:
                return scope.this_val
            scope = scope.parent
        return g_global or undefined

    def is_strict(self):
        scope = self
        while scope:
            if scope._is_strict: return True
            scope = scope.parent
        return False

_UNINITIALIZED = object()

