class Node:
    def __init__(self, type, **kwargs):
        self.type = type
        self.line = kwargs.pop('line', 0)
        self.col = kwargs.pop('col', 0)
        for k, v in kwargs.items():
            setattr(self, k, v)

    def __repr__(self):
