KEYWORDS = {
    'break', 'case', 'catch', 'class', 'const', 'continue', 'debugger',
    'default', 'delete', 'do', 'else', 'export', 'extends', 'finally',
    'for', 'function', 'if', 'import', 'in', 'instanceof', 'let', 'new',
    'return', 'static', 'super', 'switch', 'this', 'throw', 'try',
    'typeof', 'var', 'void', 'while', 'with', 'yield', 'null', 'true',
    'false', 'async', 'await', 'from', 'as', 'of', 'get', 'set',
    'target', 'meta',
}

class Lexer:
    def __init__(self, source, filename='<unknown>'):
        self.source = source
        self.filename = filename
        self.pos = 0
        self.line = 1
        self.col = 1
        self.tokens = []
        self.tok_idx = 0
        self._tokenize()
        self.tok_idx = 0

    def _tokenize(self):
        src = self.source
        n = len(src)
        pos = 0
        line = 1
        col = 1
        tokens = self.tokens

        def advance(count=1):
            nonlocal pos, col
            for _ in range(count):
                if pos < n and src[pos] == '\n':
                    pass
                col += 1
                pos += 1

        def newline():
            nonlocal pos, line, col
            pos += 1
            line += 1
            col = 1

        def add(type, value, ln=None, cl=None):
            tokens.append(Token(type, value, ln or line, cl or col))

        while pos < n:
            start_pos = pos
            start_line = line
            start_col = col
            c = src[pos]

            # Whitespace
            if c in ' \t\r\x0C\x0B':
                pos += 1; col += 1
                continue

            if c == '\n':
                newline()
                continue

            # Unicode line/paragraph separator
            if c == '\xc2' and pos+1 < n and src[pos+1] == '\xa0':
                pos += 2; col += 2
                continue

            # Comments
            if c == '/' and pos+1 < n:
                if src[pos+1] == '/':
                    pos += 2; col += 2
                    while pos < n and src[pos] != '\n':
                        pos += 1; col += 1
                    continue
                if src[pos+1] == '*':
                    pos += 2; col += 2
                    while pos < n:
                        if src[pos] == '\n':
                            line += 1; col = 1; pos += 1
                        elif src[pos] == '*' and pos+1 < n and src[pos+1] == '/':
                            pos += 2; col += 2; break
                        else:
                            pos += 1; col += 1
                    continue

            # String literals
            if c in '"\'`':
                quote = c
                pos += 1; col += 1
                parts = []
                is_template = quote == '`'
                while pos < n:
                    ch = src[pos]
                    if ch == quote and not is_template:
                        pos += 1; col += 1
                        break
                    if ch == '`' and is_template:
                        pos += 1; col += 1
                        break
                    if ch == '$' and is_template and pos+1 < n and src[pos+1] == '{':
                        # Template expression
                        add('TEMPLATE_PART', ''.join(parts), start_line, start_col)
                        parts = []
                        pos += 2; col += 2
                        # Tokenize until matching }
                        depth = 1
                        expr_tokens = []
                        expr_start = pos
                        # We'll use recursive lexer approach
                        while pos < n and depth > 0:
                            ec = src[pos]
                            if ec == '{': depth += 1
                            elif ec == '}':
                                depth -= 1
                                if depth == 0:
                                    pos += 1; col += 1
                                    break
                            pos += 1; col += 1
                        # Parse the expression tokens later
                        add('TEMPLATE_EXPR', src[expr_start:pos-1], start_line, start_col)
                        start_line = line; start_col = col
                        continue
                    if ch == '\\' and pos+1 < n:
                        pos += 1; col += 1
                        esc = src[pos]
                        if esc == 'n': parts.append('\n')
                        elif esc == 'r': parts.append('\r')
                        elif esc == 't': parts.append('\t')
                        elif esc == 'b': parts.append('\b')
                        elif esc == 'f': parts.append('\f')
                        elif esc == 'v': parts.append('\v')
                        elif esc == '0': parts.append('\0')
                        elif esc == '\\': parts.append('\\')
                        elif esc == '\'': parts.append('\'')
                        elif esc == '"': parts.append('"')
                        elif esc == '`': parts.append('`')
                        elif esc == '\n': line += 1; col = 1
                        elif esc == 'u':
                            pos += 1; col += 1
                            if pos < n and src[pos] == '{':
                                j = pos + 1
                                while j < n and src[j] != '}': j += 1
                                cp = int(src[pos+1:j], 16)
                                parts.append(chr(cp))
                                pos = j; col += j - pos + 1
                            else:
                                hex_str = src[pos:pos+4]
                                cp = int(hex_str, 16) if len(hex_str) == 4 else 0
                                parts.append(chr(cp))
                                pos += 3; col += 3
                        elif esc == 'x':
                            hex_str = src[pos+1:pos+3]
                            try: cp = int(hex_str, 16)
                            except: cp = 0
                            parts.append(chr(cp))
                            pos += 2; col += 2
                        else:
                            parts.append(esc)
                        pos += 1; col += 1
                        continue
                    if ch == '\n':
                        parts.append('\n')
                        line += 1; col = 1
                    else:
                        parts.append(ch)
                        col += 1
                    pos += 1

                val = ''.join(parts)
                if is_template:
                    add('TEMPLATE_END', val, start_line, start_col)
                else:
                    add('STRING', val, start_line, start_col)
                continue

            # Numbers
            if c.isdigit() or (c == '.' and pos+1 < n and src[pos+1].isdigit()):
                num_start = pos
                is_bigint = False
                if c == '0' and pos+1 < n:
                    nc = src[pos+1]
                    if nc in 'xX':
                        pos += 2; col += 2
                        while pos < n and src[pos] in '0123456789abcdefABCDEF_':
                            pos += 1; col += 1
                        val = src[num_start:pos].replace('_', '')
                        if pos < n and src[pos] == 'n':
                            is_bigint = True; pos += 1; col += 1
                        if is_bigint: add('BIGINT', int(val, 16), start_line, start_col)
                        else: add('NUMBER', float(int(val, 16)), start_line, start_col)
                        continue
                    if nc in 'oO':
                        pos += 2; col += 2
                        while pos < n and src[pos] in '01234567_':
                            pos += 1; col += 1
                        val = src[num_start:pos].replace('_', '')
                        if pos < n and src[pos] == 'n':
                            is_bigint = True; pos += 1; col += 1
                        if is_bigint: add('BIGINT', int(val, 8), start_line, start_col)
                        else: add('NUMBER', float(int(val, 8)), start_line, start_col)
                        continue
                    if nc in 'bB':
                        pos += 2; col += 2
                        while pos < n and src[pos] in '01_':
                            pos += 1; col += 1
                        val = src[num_start:pos].replace('_', '')
                        if pos < n and src[pos] == 'n':
                            is_bigint = True; pos += 1; col += 1
                        if is_bigint: add('BIGINT', int(val, 2), start_line, start_col)
                        else: add('NUMBER', float(int(val, 2)), start_line, start_col)
                        continue

                while pos < n and (src[pos].isdigit() or src[pos] == '_'):
                    pos += 1; col += 1
                if pos < n and src[pos] == '.':
                    pos += 1; col += 1
                    while pos < n and (src[pos].isdigit() or src[pos] == '_'):
                        pos += 1; col += 1
                if pos < n and src[pos] in 'eE':
                    pos += 1; col += 1
                    if pos < n and src[pos] in '+-':
                        pos += 1; col += 1
                    while pos < n and src[pos].isdigit():
                        pos += 1; col += 1

                val_str = src[num_start:pos].replace('_', '')

                if pos < n and src[pos] == 'n':
                    is_bigint = True; pos += 1; col += 1
                    add('BIGINT', int(val_str), start_line, start_col)
                else:
                    try: num_val = float(val_str)
                    except: num_val = 0.0
                    add('NUMBER', num_val, start_line, start_col)
                continue

            # Identifiers and keywords
            if c.isalpha() or c == '_' or c == '$' or ord(c) > 127:
                ident_start = pos
                while pos < n and (src[pos].isalnum() or src[pos] in '_$' or ord(src[pos]) > 127):
                    pos += 1; col += 1
                ident = src[ident_start:pos]
                if ident in KEYWORDS:
                    add('KEYWORD:'+ident, ident, start_line, start_col)
                elif ident == 'undefined':
                    add('KEYWORD:undefined', ident, start_line, start_col)
                else:
                    add('IDENT', ident, start_line, start_col)
                continue

            # Operators and punctuation
            if pos+2 < n:
                tri = src[pos:pos+3]
                if tri == '...':
                    add('...', tri, start_line, start_col); pos += 3; col += 3; continue
                if tri == '===':
                    add('===', tri, start_line, start_col); pos += 3; col += 3; continue
                if tri == '!==':
                    add('!==', tri, start_line, start_col); pos += 3; col += 3; continue
                if tri == '**=':
                    add('**=', tri, start_line, start_col); pos += 3; col += 3; continue
                if tri == '&&=':
                    add('&&=', tri, start_line, start_col); pos += 3; col += 3; continue
                if tri == '||=':
                    add('||=', tri, start_line, start_col); pos += 3; col += 3; continue
                if tri == '??=':
                    add('??=', tri, start_line, start_col); pos += 3; col += 3; continue
                if tri == '>>>':
                    if pos+3 < n and src[pos+3] == '=':
                        add('>>>=', src[pos:pos+4], start_line, start_col); pos += 4; col += 4; continue
                    add('>>>', tri, start_line, start_col); pos += 3; col += 3; continue
                if tri == '<<=':
                    add('<<=', tri, start_line, start_col); pos += 3; col += 3; continue
                if tri == '>>=':
                    add('>>=', tri, start_line, start_col); pos += 3; col += 3; continue

            if pos+1 < n:
                dbl = src[pos:pos+2]
                if dbl in ('==', '!=', '<=', '>=', '**', '&&', '||', '??', '++', '--',
                          '->', '=>', '?.', '+=', '-=', '*=', '/=', '%=', '&=', '|=', '^=',
                          '<<', '>>', '#!'):
                    add(dbl, dbl, start_line, start_col); pos += 2; col += 2; continue
                if dbl == '//':
                    while pos < n and src[pos] != '\n': pos += 1; col += 1
                    continue

            # Single char
            if c in '{}[]().,;:?~!+-*/%&|^<>=@#\\':
                add(c, c, start_line, start_col); pos += 1; col += 1; continue

            # Unknown
            pos += 1; col += 1

        add('EOF', None, line, col)

    def peek(self, offset=0):
        idx = self.tok_idx + offset
        if idx >= len(self.tokens): return self.tokens[-1]
        return self.tokens[idx]

    def next(self):
        tok = self.tokens[self.tok_idx]
        if self.tok_idx < len(self.tokens) - 1:
            self.tok_idx += 1
        return tok

    def consume(self, expected_type=None):
        tok = self.next()
        if expected_type and tok.type != expected_type:
            raise SyntaxError(f"Expected {expected_type!r} but got {tok.type!r} at line {tok.line}")
        return tok

    def match(self, *types):
        tok = self.peek()
        if tok.type in types:
            return self.next()
        return None

    def expect(self, type):
        tok = self.peek()
        if tok.type != type:
            raise SyntaxError(f"Expected {type!r} got {tok.type!r} ({tok.value!r}) at line {tok.line}:{tok.col}")
        return self.next()

    def has_newline_before(self):
        """Check if there's a newline before the current token"""
        if self.tok_idx == 0: return False
        prev = self.tokens[self.tok_idx - 1]
        curr = self.tokens[self.tok_idx]
        return curr.line > prev.line

    def is_kw(self, *kws):
        tok = self.peek()
        return tok.type in [f'KEYWORD:{k}' for k in kws]

    def match_kw(self, *kws):
        tok = self.peek()
        for kw in kws:
            if tok.type == f'KEYWORD:{kw}':
                return self.next()
        return None

