        return tok

    def consume(self, expected_type=None):
        tok = self.next()
        if expected_type and tok.type != expected_type:
            raise SyntaxError(f"Expected {expected_type!r} but got {tok.type!r} at line {tok.line}")
        return tok

    def match(self, *types):
        tok = self.peek()
        if tok.type in types:
            return self.next()
        return None

    def expect(self, type):
        tok = self.peek()
        if tok.type != type:
            raise SyntaxError(f"Expected {type!r} got {tok.type!r} ({tok.value!r}) at line {tok.line}:{tok.col}")
        return self.next()

