def make_error(error_type, message, js_stack=None):
    """Create a JS error object"""
    proto = g_error_protos.get(error_type, g_error_proto)
    obj = JSObject(proto)
    obj._class = 'Error'
    if message:
        obj._props['message'] = {'value': message, 'writable': True, 'enumerable': False, 'configurable': True}
    obj._props['name'] = {'value': error_type, 'writable': True, 'enumerable': False, 'configurable': True}
    # Generate stack string
    stack_lines = []
    if js_stack:
        for frame in reversed(js_stack):
            func_name = frame.get('func', '<anonymous>')
            fname = frame.get('file', '<unknown>')
            line = frame.get('line', 0)
            col = frame.get('col', 0)
            stack_lines.append(f"    at {func_name} ({fname}:{line}:{col})")
    if stack_lines:
        if message:
            stack_str = f"{error_type}: {message}\n" + "\n".join(stack_lines) + "\n"
        else:
