class _Undefined:
    _inst = None
    def __new__(cls):
        if cls._inst is None: cls._inst = super().__new__(cls)
        return cls._inst
    def __repr__(self): return 'undefined'
    def __bool__(self): return False
    def __str__(self): return 'undefined'

class _Null:
    _inst = None
    def __new__(cls):
        if cls._inst is None: cls._inst = super().__new__(cls)
        return cls._inst
    def __repr__(self): return 'null'
    def __bool__(self): return False
    def __str__(self): return 'null'

undefined = _Undefined()
null = _Null()
_HOLE = object()  # array hole
_UNINIT = object()  # temporal dead zone

class JSSymbol:
    _cnt = 0
    _reg = {}
    def __init__(self, desc=None, key=None):
        JSSymbol._cnt += 1
        self._id = JSSymbol._cnt
        self.description = desc
        self._key = key
    def __repr__(self):
        return f'Symbol({self.description})' if self.description is not None else 'Symbol()'
    def __str__(self): return repr(self)
    def __hash__(self): return self._id
    def __eq__(self, o): return self is o

