def _make_error_with_stack(etype, msg, frames):
    obj = _make_error(etype, msg)
    if frames:
        parts = [f'{etype}: {msg}' if msg else etype]
        for frame in frames:
            fn = frame.get('func', '<anonymous>')
            file_ = frame.get('file', '<unknown>')
            line = frame.get('line', 0)
            col = frame.get('col', 0)
            parts.append(f'    at {fn} ({file_}:{line}:{col})')
        parts.append('')
        obj._props['stack'] = {'value': '\n'.join(parts), 'writable': True, 'enumerable': False, 'configurable': True}
    return obj

