#!/usr/bin/env python3
"""
QuickJS-compatible JavaScript interpreter.
Implements ES2023+ JavaScript with QuickJS-compatible output format.
"""

import sys, os, math, json, re, time, struct, functools, traceback as tb_module
import subprocess, signal, threading, socket
from typing import Any, Dict, List, Optional, Tuple, Union

# ===== Number formatting (matches JavaScript exactly) =====

def num_to_js_str(n):
    """Convert number to string matching JavaScript's Number.prototype.toString()"""
    if math.isnan(n): return 'NaN'
    if math.isinf(n): return 'Infinity' if n > 0 else '-Infinity'
    if n == 0: return '0'
    negative = n < 0
    if negative: n = -n
    if n == int(n) and n < 1e21:
        result = str(int(n))
        return ('-' + result) if negative else result
    # Get shortest round-trip representation
    s = None
    for prec in range(1, 22):
        candidate = format(n, f'.{prec}g')
        try:
            if float(candidate) == n:
                s = candidate; break
        except: pass
    if s is None: s = repr(n)
    # Convert to JS format
    if 'e' in s:
        m, e = s.split('e')
        exp = int(e)
        if '.' in m: int_part, frac_part = m.split('.')
        else: int_part, frac_part = m, ''
        if exp >= -6 and exp < 21:
            all_digits = (int_part + frac_part).lstrip('0') or '0'
            actual_pos = len(int_part) + exp
            if actual_pos <= 0:
                result = '0.' + '0' * (-actual_pos) + all_digits
            elif actual_pos >= len(all_digits):
                result = all_digits + '0' * (actual_pos - len(all_digits))
            else:
                result = all_digits[:actual_pos] + '.' + all_digits[actual_pos:]
            if '.' in result: result = result.rstrip('0').rstrip('.')
        else:
            digits = (int_part.lstrip('0') + frac_part).rstrip('0') or '0'
            mantissa = digits[0] + ('.' + digits[1:] if len(digits) > 1 else '')
            result = f"{mantissa}e+{exp}" if exp >= 0 else f"{mantissa}e{exp}"
    else:
        result = s
        if '.' in result: result = result.rstrip('0').rstrip('.')
    return ('-' + result) if negative else result

def inspect_num(n):
    """Number for inspect output (shows -0)"""
    if math.isnan(n): return 'NaN'
    if math.isinf(n): return 'Infinity' if n > 0 else '-Infinity'
    if n == 0 and math.copysign(1, n) < 0: return '-0'
    return num_to_js_str(n)

