            items = [_inspect(x, depth+1, seen, True) for x in v._ta_items]
            return f'{cl}({n}) [ ' + ', '.join(items) + ' ]'
        return f'{cl}(0) []'

    # Array
    if isinstance(v, JSArray): return _inspect_arr(v, depth, seen)

    # Regular object - check for custom class prefix
    return _inspect_plain_obj(v, depth, seen)

