                parts.append(f'{desc}: [Getter/Setter]' if has_set else f'{desc}: [Getter]')
            else:
                val = prop.get('value', undefined)
                parts.append(f'{desc}: {_inspect(val, depth+1, seen, True)}')
            continue
        if not isinstance(key, str): continue
        kstr = _fmt_key(key)
        if 'get' in prop:
            has_set = prop.get('set') is not undefined and prop.get('set') is not None
            parts.append(f'{kstr}: [Getter/Setter]' if has_set else f'{kstr}: [Getter]')
        else:
            val = prop.get('value', undefined)
            parts.append(f'{kstr}: {_inspect(val, depth+1, seen, True)}')
    if not parts: return '{  }'
    return '{ ' + ', '.join(parts) + ' }'

def _inspect_arr(v, depth, seen):
    # Check for sparse array
    is_sparse = any(x is _HOLE for x in v._items[:v._length])
