        if receiver is None: receiver = self
        prop = self._props.get(key)
        if prop is not None:
            if 'get' in prop:
                g = prop['get']
                if g is undefined or g is None: return undefined
                return _js_call(g, receiver, [])
            return prop.get('value', undefined)
        if self._proto is not None:
            return self._proto._get(key, receiver)
        return undefined

    def _set(self, key, value, receiver=None, strict=False):
        if receiver is None: receiver = self
        obj = self
        while obj is not None:
            prop = obj._props.get(key)
            if prop is not None:
                if 'set' in prop:
                    s = prop['set']
                    if s is undefined or s is None:
                        if strict: raise JSError(f"Cannot set property '{key}'", 'TypeError')
                        return True
                    _js_call(s, receiver, [value])
                    return True
                if not prop.get('writable', True):
                    if strict: raise JSError(f"Cannot assign to read only property '{key}'", 'TypeError')
                    return True
                break
            obj = obj._proto
        if isinstance(receiver, JSObject):
            if not receiver._extensible and key not in receiver._props:
                if strict: raise JSError(f"Cannot add property '{key}', not extensible", 'TypeError')
                return True
            if key in receiver._props:
                prop = receiver._props[key]
                if not prop.get('writable', True):
                    if strict: raise JSError(f"Cannot assign to read only property '{key}'", 'TypeError')
                    return True
                if 'value' in prop:
                    prop['value'] = value
                    return True
            receiver._props[key] = {'value': value, 'writable': True, 'enumerable': True, 'configurable': True}
        return True

    def _has_own(self, key):
        return key in self._props

    def _has(self, key):
        obj = self
        while obj is not None:
            if key in obj._props: return True
            obj = obj._proto
        return False

    def _delete(self, key, strict=False):
        if key in self._props:
            prop = self._props[key]
            if not prop.get('configurable', True):
                if strict: raise JSError(f"Cannot delete property '{key}'", 'TypeError')
                return False
            del self._props[key]
            return True
        return True

    def _enum_keys(self):
        result = []
        seen = set()
        obj = self
        while obj is not None:
            for k in obj._props:
                if k not in seen and isinstance(k, str):
                    seen.add(k)
                    if obj._props[k].get('enumerable', True):
                        result.append(k)
            obj = obj._proto
        return result

    def _own_enum_keys(self):
        return [k for k in self._props if isinstance(k, str) and self._props[k].get('enumerable', True)]

    def _own_keys_all(self):
        return list(self._props.keys())

    def _define_prop(self, key, desc, strict=False):
        existing = self._props.get(key)
        if existing is None:
            if not self._extensible:
                if strict: raise JSError(f"Cannot define property '{key}'", 'TypeError')
                return False
            if 'get' in desc or 'set' in desc:
                new_prop = {'get': desc.get('get', undefined), 'set': desc.get('set', undefined),
                           'enumerable': desc.get('enumerable', False), 'configurable': desc.get('configurable', False)}
            else:
                new_prop = {'value': desc.get('value', undefined), 'writable': desc.get('writable', False),
                           'enumerable': desc.get('enumerable', False), 'configurable': desc.get('configurable', False)}
            self._props[key] = new_prop
            return True
        # Modify existing
        if not existing.get('configurable', True):
            # Can only change value if writable
            if 'value' in desc and 'value' in existing:
                if existing.get('writable', False):
                    existing['value'] = desc['value']
                    return True
            if strict: raise JSError(f"Cannot redefine property '{key}'", 'TypeError')
            return False
        for k in ('value', 'writable', 'enumerable', 'configurable', 'get', 'set'):
            if k in desc:
                existing[k] = desc[k]
        return True

class JSArray(JSObject):
    __slots__ = JSObject.__slots__ + ['_items', '_length']

    def __init__(self, proto=None):
        super().__init__(proto)
        self._class = 'Array'
        self._items = []
        self._length = 0

    def _get(self, key, receiver=None):
        if receiver is None: receiver = self
        if key == 'length': return self._length
        if isinstance(key, str):
            try:
                idx = int(key)
                if idx >= 0 and str(idx) == key:
                    if idx < len(self._items):
                        v = self._items[idx]
                        return undefined if v is _HOLE else v
                    return undefined
            except (ValueError, OverflowError): pass
        if isinstance(key, (int, float)) and not isinstance(key, bool):
            idx = int(key)
            if idx == key and idx >= 0:
                if idx < len(self._items):
                    v = self._items[idx]
                    return undefined if v is _HOLE else v
                return undefined
        return super()._get(key, receiver)

    def _set(self, key, value, receiver=None, strict=False):
        if receiver is None: receiver = self
        if key == 'length':
            new_len = _to_uint32(value)
            if new_len < self._length:
                if new_len < len(self._items):
                    self._items = self._items[:new_len]
            self._length = new_len
            return True
        if isinstance(key, str):
            try:
                idx = int(key)
                if idx >= 0 and str(idx) == key:
                    self._arr_set(idx, value)
                    return True
            except (ValueError, OverflowError): pass
        if isinstance(key, (int, float)) and not isinstance(key, bool):
            idx = int(key)
            if idx == key and idx >= 0:
                self._arr_set(idx, value)
                return True
        return super()._set(key, value, receiver, strict)

    def _arr_set(self, idx, value):
        if idx >= len(self._items):
            self._items.extend([_HOLE] * (idx - len(self._items) + 1))
        self._items[idx] = value
        if idx >= self._length:
            self._length = idx + 1

    def _has_own(self, key):
        if key == 'length': return True
        if isinstance(key, str):
            try:
                idx = int(key)
                if idx >= 0 and str(idx) == key:
                    return idx < len(self._items) and self._items[idx] is not _HOLE
            except (ValueError, OverflowError): pass
        return super()._has_own(key)

    def _own_enum_keys(self):
        result = []
        for i in range(len(self._items)):
            if i < self._length and self._items[i] is not _HOLE:
                result.append(str(i))
        result.extend(super()._own_enum_keys())
        return result

    def _own_keys_all(self):
        result = [str(i) for i in range(len(self._items)) 
                  if i < self._length and self._items[i] is not _HOLE]
        result.extend([k for k in super()._own_keys_all() 
                       if not (isinstance(k, str) and k.isdigit())])
        if self._props:
            seen = set(result)
            for k in self._props:
                if k not in seen: result.append(k)
        return result

# ===== Type conversion =====

def _is_num(v): return isinstance(v, (int, float)) and not isinstance(v, bool)

def _to_primitive(v, hint='default'):
    if v is null or v is undefined: return v
    if isinstance(v, (bool, int, float, str, JSBigInt, JSSymbol)): return v
    if isinstance(v, JSObject):
        tp = None
        for k, prop in v._props.items():
            if k is _sym_toPrimitive:
                tp = prop.get('value')
                break
        if tp is None and v._proto is not None:
            obj2 = v._proto
            while obj2 is not None:
                tp = obj2._props.get(_sym_toPrimitive, {}).get('value')
                if tp is not None: break
                obj2 = obj2._proto
        if tp is not None and _callable(tp):
            r = _js_call(tp, v, [hint])
            if not isinstance(r, JSObject): return r
            raise JSThrow(_make_error('TypeError', 'Cannot convert object to primitive value'))
        if hint == 'string':
            ts = v._get('toString')
            if _callable(ts):
                r = _js_call(ts, v, [])
                if not isinstance(r, JSObject): return r
            vo = v._get('valueOf')
            if _callable(vo):
                r = _js_call(vo, v, [])
                if not isinstance(r, JSObject): return r
        else:
            vo = v._get('valueOf')
            if _callable(vo):
                r = _js_call(vo, v, [])
                if not isinstance(r, JSObject): return r
            ts = v._get('toString')
            if _callable(ts):
                r = _js_call(ts, v, [])
                if not isinstance(r, JSObject): return r
        raise JSThrow(_make_error('TypeError', 'Cannot convert object to primitive value'))
    return v

def _to_number(v):
    if isinstance(v, bool): return 1.0 if v else 0.0
    if v is null: return 0.0
    if v is undefined: return float('nan')
    if _is_num(v): return float(v)
    if isinstance(v, JSBigInt): raise JSThrow(_make_error('TypeError', 'Cannot convert a BigInt value to a number'))
    if isinstance(v, str):
        s = v.strip()
        if s == '': return 0.0
        if s in ('Infinity', '+Infinity'): return float('inf')
        if s == '-Infinity': return float('-inf')
        try:
            if s.startswith('0x') or s.startswith('0X'): return float(int(s, 16))
            if s.startswith('0o') or s.startswith('0O'): return float(int(s, 8))
            if s.startswith('0b') or s.startswith('0B'): return float(int(s, 2))
            return float(s)
        except: return float('nan')
    if isinstance(v, JSObject):
        p = _to_primitive(v, 'number')
        return _to_number(p)
    return float('nan')

def _to_integer_or_inf(v):
    n = _to_number(v)
    if math.isnan(n): return 0
    if math.isinf(n): return n
    return float(int(n))

def _to_int32(v):
    n = _to_number(v)
    if math.isnan(n) or math.isinf(n) or n == 0: return 0
    i = int(n) & 0xFFFFFFFF
    if i >= 0x80000000: i -= 0x100000000
    return i

def _to_uint32(v):
    n = _to_number(v)
    if math.isnan(n) or math.isinf(n) or n == 0: return 0
    return int(n) & 0xFFFFFFFF

def _to_uint16(v):
    n = _to_number(v)
    if math.isnan(n) or math.isinf(n) or n == 0: return 0
    return int(n) & 0xFFFF

def _to_string(v):
    if isinstance(v, bool): return 'true' if v else 'false'
    if v is null: return 'null'
    if v is undefined: return 'undefined'
    if isinstance(v, str): return v
    if _is_num(v): return num_to_js_str(float(v))
    if isinstance(v, JSBigInt): return str(v.value)
    if isinstance(v, JSSymbol): raise JSThrow(_make_error('TypeError', 'Cannot convert a Symbol value to a string'))
    if isinstance(v, JSObject):
        p = _to_primitive(v, 'string')
        return _to_string(p)
    return str(v)

def _to_boolean(v):
    if isinstance(v, bool): return v
    if v is null or v is undefined: return False
    if _is_num(v): return v != 0 and not math.isnan(v)
    if isinstance(v, str): return len(v) > 0
    if isinstance(v, JSBigInt): return v.value != 0
    if isinstance(v, JSObject): return True
    return bool(v)

def _to_object(v):
    if v is null: raise JSThrow(_make_error('TypeError', 'Cannot convert null to object'))
    if v is undefined: raise JSThrow(_make_error('TypeError', 'Cannot convert undefined to object'))
    if isinstance(v, JSObject): return v
    if isinstance(v, bool):
        obj = JSObject(g_boolean_proto)
        obj._class = 'Boolean'
        obj._primitive_value = v
        return obj
    if _is_num(v):
        obj = JSObject(g_number_proto)
        obj._class = 'Number'
        obj._primitive_value = float(v)
        return obj
    if isinstance(v, str):
        obj = JSObject(g_string_proto)
        obj._class = 'String'
        obj._primitive_value = v
        return obj
    if isinstance(v, JSSymbol):
        obj = JSObject(g_symbol_proto)
        obj._class = 'Symbol'
        obj._primitive_value = v
        return obj
    if isinstance(v, JSBigInt):
        obj = JSObject(g_bigint_proto)
        obj._class = 'BigInt'
        obj._primitive_value = v
        return obj
    return v

def _callable(v): return isinstance(v, JSObject) and v._call is not None

def _is_constructor(v): 
    if not isinstance(v, JSObject): return False
    if v._construct is not None: return True
    if v._call is not None and not v._is_arrow and not v._is_generator: return True
    return False

# ===== Equality =====

def _js_eq(a, b):
    """Abstract equality =="""
    ta = type(a); tb = type(b)
    if (a is null and b is undefined) or (a is undefined and b is null): return True
    if a is null or b is null: return False
    if a is undefined or b is undefined: return False
    if isinstance(a, bool) and isinstance(b, bool): return a == b
    if _is_num(a) and _is_num(b):
        fa, fb = float(a), float(b)
        if math.isnan(fa) or math.isnan(fb): return False
        return fa == fb
    if isinstance(a, str) and isinstance(b, str): return a == b
    if isinstance(a, JSSymbol) and isinstance(b, JSSymbol): return a is b
    if isinstance(a, JSBigInt) and isinstance(b, JSBigInt): return a.value == b.value
    if isinstance(a, JSObject) and isinstance(b, JSObject): return a is b
    # Coercions
    if isinstance(a, bool): return _js_eq(1.0 if a else 0.0, b)
    if isinstance(b, bool): return _js_eq(a, 1.0 if b else 0.0)
    if _is_num(a) and isinstance(b, str): return _js_eq(a, _to_number(b))
    if isinstance(a, str) and _is_num(b): return _js_eq(_to_number(a), b)
    if isinstance(a, JSBigInt) and isinstance(b, str):
        try: return a.value == int(b)
        except: return False
    if isinstance(b, JSBigInt) and isinstance(a, str):
        try: return int(a) == b.value
        except: return False
    if isinstance(a, JSBigInt) and _is_num(b):
        if math.isnan(b) or math.isinf(b): return False
        return a.value == b
    if _is_num(a) and isinstance(b, JSBigInt):
        if math.isnan(a) or math.isinf(a): return False
        return a == b.value
    if isinstance(a, JSObject) and isinstance(b, (str, int, float, JSBigInt)) and not isinstance(b, bool):
        return _js_eq(_to_primitive(a), b)
    if isinstance(b, JSObject) and isinstance(a, (str, int, float, JSBigInt)) and not isinstance(a, bool):
        return _js_eq(a, _to_primitive(b))
    return False

def _js_strict_eq(a, b):
    """Strict equality ==="""
    if a is null and b is null: return True
    if a is undefined and b is undefined: return True
    if isinstance(a, bool) and isinstance(b, bool): return a == b
    if _is_num(a) and _is_num(b):
        fa, fb = float(a), float(b)
        if math.isnan(fa) or math.isnan(fb): return False
        return fa == fb
    if isinstance(a, str) and isinstance(b, str): return a == b
    if isinstance(a, JSSymbol) and isinstance(b, JSSymbol): return a is b
    if isinstance(a, JSBigInt) and isinstance(b, JSBigInt): return a.value == b.value
    if isinstance(a, JSObject) and isinstance(b, JSObject): return a is b
    return False

def _js_less(a, b):
    """< comparison, returns True/False or undefined"""
    px = _to_primitive(a, 'number')
    py = _to_primitive(b, 'number')
    if isinstance(px, str) and isinstance(py, str): return px < py
    if isinstance(px, JSBigInt) and isinstance(py, JSBigInt): return px.value < py.value
    if isinstance(px, JSBigInt) and _is_num(py):
        if math.isnan(py): return undefined
        return float(px.value) < py
    if _is_num(px) and isinstance(py, JSBigInt):
        if math.isnan(px): return undefined
        return px < float(py.value)
    nx, ny = _to_number(px), _to_number(py)
    if math.isnan(nx) or math.isnan(ny): return undefined
    return nx < ny

# ===== Inspect (console.log format) =====

def _inspect(v, depth=0, seen=None, in_obj=False):
    if seen is None: seen = {}
    if isinstance(v, bool): return 'true' if v else 'false'
    if v is null: return 'null'
    if v is undefined: return 'undefined'
    if _is_num(v): return inspect_num(float(v))
    if isinstance(v, str):
        if in_obj: return json.dumps(v)
        return v
    if isinstance(v, JSBigInt): return f'{v.value}n'
    if isinstance(v, JSSymbol): return repr(v)
    if isinstance(v, JSObject):
        oid = id(v)
        if oid in seen:
            if isinstance(v, JSArray): return '[Array]'
            return '[circular 0]'
        if depth >= 2:
            if isinstance(v, JSArray): return '[Array]'
            return '[Object]'
        seen2 = {**seen, oid: True}
        return _inspect_obj(v, depth, seen2)
    return repr(v)

def _inspect_obj(v, depth, seen):
    cl = v._class

    # Function
    if v._call is not None:
        name = v._name or ''
        if name: return f'[Function {name}]'
        return '[Function (anonymous)]'

    # Check for error
    if _is_error(v): return _inspect_error(v, depth, seen)

    # RegExp
    if cl == 'RegExp' and hasattr(v, '_pattern'):
        return f'/{v._pattern}/{v._flags}'

    # Date
    if cl == 'Date' and hasattr(v, '_date_ms'):
        import datetime
        ms = v._date_ms
        if math.isnan(ms): return 'Invalid Date'
        try:
            s = int(ms // 1000)
            us = int((ms % 1000) * 1000)
            dt = datetime.datetime(1970, 1, 1) + datetime.timedelta(seconds=s, microseconds=us)
            return dt.strftime(f'%Y-%m-%dT%H:%M:%S.{int(ms%1000):03d}Z')
        except: return 'Invalid Date'

    # Generator
    if cl == 'Generator': return 'Generator {  }'

    # Promise
    if cl == 'Promise': return 'Promise {  }'

    # Map
    if cl == 'Map' and hasattr(v, '_map_data'):
        items = v._map_data
        if not items: return 'Map(0) {}'
        parts = [f'{_inspect(k, depth+1, seen, True)} => {_inspect(val, depth+1, seen, True)}' 
                 for k, val in items]
        return f'Map({len(items)}) ' + '{ ' + ', '.join(parts) + ' }'

    # Set
    if cl == 'Set' and hasattr(v, '_set_data'):
        items = v._set_data
        if not items: return 'Set(0) {}'
        return f'Set({len(items)}) ' + '{ ' + ', '.join(_inspect(x, depth+1, seen, True) for x in items) + ' }'

    if cl == 'WeakMap': return 'WeakMap {  }'
    if cl == 'WeakSet': return 'WeakSet {  }'
    if cl == 'WeakRef': return 'WeakRef {  }'
    if cl == 'ArrayBuffer' or cl == 'SharedArrayBuffer': return f'{cl} {{  }}'
    if cl == 'DataView': return 'DataView {  }'
    if cl == 'Proxy': return 'Object {  }'

    # TypedArrays
    if cl in ('Uint8Array','Int8Array','Uint16Array','Int16Array','Uint32Array','Int32Array',
              'Float32Array','Float64Array','BigInt64Array','BigUint64Array','Uint8ClampedArray'):
        if hasattr(v, '_ta_items'):
            n = len(v._ta_items)
            if n == 0: return f'{cl}(0) []'
            items = [_inspect(x, depth+1, seen, True) for x in v._ta_items]
            return f'{cl}({n}) [ ' + ', '.join(items) + ' ]'
        return f'{cl}(0) []'

    # Array
    if isinstance(v, JSArray): return _inspect_arr(v, depth, seen)

    # Regular object - check for custom class prefix
    return _inspect_plain_obj(v, depth, seen)

def _inspect_plain_obj(v, depth, seen):
    parts = []
    for key, prop in v._props.items():
        if not prop.get('enumerable', True): continue
        if isinstance(key, JSSymbol):
            desc = key.description or ''
            if 'get' in prop:
                has_set = prop.get('set') is not undefined and prop.get('set') is not None
                parts.append(f'{desc}: [Getter/Setter]' if has_set else f'{desc}: [Getter]')
            else:
                val = prop.get('value', undefined)
                parts.append(f'{desc}: {_inspect(val, depth+1, seen, True)}')
            continue
        if not isinstance(key, str): continue
        kstr = _fmt_key(key)
        if 'get' in prop:
            has_set = prop.get('set') is not undefined and prop.get('set') is not None
            parts.append(f'{kstr}: [Getter/Setter]' if has_set else f'{kstr}: [Getter]')
        else:
            val = prop.get('value', undefined)
            parts.append(f'{kstr}: {_inspect(val, depth+1, seen, True)}')
    if not parts: return '{  }'
    return '{ ' + ', '.join(parts) + ' }'

def _inspect_arr(v, depth, seen):
    # Check for sparse array
    is_sparse = any(x is _HOLE for x in v._items[:v._length])
    extra_props = [(k,p) for k,p in v._props.items() 
                   if isinstance(k,str) and not k.isdigit() and p.get('enumerable',True)]

    if is_sparse:
        parts = []
        for i in range(min(len(v._items), v._length)):
            if v._items[i] is not _HOLE:
                parts.append(f'{i}: {_inspect(v._items[i], depth+1, seen, True)}')
        for k, prop in extra_props:
            if 'get' in prop: parts.append(f'{_fmt_key(k)}: [Getter]')
            else: parts.append(f'{_fmt_key(k)}: {_inspect(prop.get("value", undefined), depth+1, seen, True)}')
        if not parts: return '[  ]'
        return '[ ' + ', '.join(parts) + ' ]'

    parts = []
    for i in range(v._length):
        if i < len(v._items):
            item = v._items[i]
            if item is _HOLE: parts.append(f'{i}: <hole>')
            else: parts.append(_inspect(item, depth+1, seen, True))
        else:
            break

    for k, prop in extra_props:
        if 'get' in prop: parts.append(f'{_fmt_key(k)}: [Getter]')
        else: parts.append(f'{_fmt_key(k)}: {_inspect(prop.get("value", undefined), depth+1, seen, True)}')

    if not parts: return '[  ]'
    return '[ ' + ', '.join(parts) + ' ]'

def _inspect_error(v, depth, seen):
    name_prop = v._props.get('name', {})
    name = name_prop.get('value', 'Error') if name_prop else 'Error'
    if not isinstance(name, str): name = 'Error'

    msg_prop = v._props.get('message', {})
    msg = msg_prop.get('value', '') if msg_prop else ''
    if not isinstance(msg, str): msg = ''

    stack_prop = v._props.get('stack', {})
    stack = stack_prop.get('value') if stack_prop else None

    if isinstance(stack, str):
        result = stack.rstrip('\n')
    elif msg:
        result = f'{name}: {msg}'
    else:
        result = name

    # Extra enumerable props
    extra = []
    for k, prop in v._props.items():
        if isinstance(k, str) and k not in ('name','message','stack') and prop.get('enumerable', True):
            val = prop.get('value', undefined)
            extra.append(f'{_fmt_key(k)}: {_inspect(val, depth+1, seen, True)}')

    if extra:
        result += ' { ' + ', '.join(extra) + ' }'
    return result

def _is_error(v):
    if not isinstance(v, JSObject): return False
    if v._class == 'Error': return True
    p = v._proto
    while p is not None:
        if p._class == 'Error': return True
        p = p._proto
    return False

def _fmt_key(k):
    if isinstance(k, JSSymbol): return k.description or ''
    if isinstance(k, str):
        if re.match(r'^[a-zA-Z_$][a-zA-Z0-9_$]*$', k) or re.match(r'^\d+$', k):
            return k
        return json.dumps(k)
    return str(k)

# ===== JS call/construct =====

_call_depth = 0
MAX_CALL_DEPTH = 500

def _js_call(func, this, args, new_target=None):
    global _call_depth
    if not isinstance(func, JSObject) or func._call is None:
        n = func._name if isinstance(func, JSObject) and func._name else ''
        raise JSThrow(_make_error('TypeError', f"{'not a function' if not n else repr(n) + ' is not a function'}"))
    _call_depth += 1
    if _call_depth > MAX_CALL_DEPTH:
        _call_depth -= 1
        raise JSThrow(_make_error('RangeError', 'Maximum call stack size exceeded'))
    try:
        result = func._call(this, args, new_target)
