    def _compute_newlines(self):
        self.nl_before = [False] * len(self.toks)
        nl = False
        for i, t in enumerate(self.toks):
            if t.t == 'NL':
                nl = True
            else:
                self.nl_before[i] = nl
                nl = False
        # Remove NL tokens
        self.toks = [t for t in self.toks if t.t != 'NL']
        self.nl_before = [self.nl_before[i] for i, t in enumerate(self.toks) if t.t != 'NL']

    def peek(self, off=0):
        i = self.pos + off
        if i >= len(self.toks): return self.toks[-1]
        return self.toks[i]

    def next(self):
        t = self.toks[self.pos]
        if self.pos < len(self.toks)-1: self.pos += 1
        return t

