# ===== Scope =====

class Scope:
    def __init__(self, parent=None):
        self.vars = {}
        self.parent = parent
        self.this_val = None
        self._strict = False
        self._module = False
        self._labels = {}
        self._func_scope = None  # nearest function scope

    def get(self, name):
        scope = self
        while scope is not None:
            if name in scope.vars:
                v = scope.vars[name]
                if v is _UNINIT:
                    raise JSThrow(_make_error('ReferenceError', f"Cannot access '{name}' before initialization"))
                return v
            scope = scope.parent
        if g_global is not None:
            v = g_global._get(name)
            if v is not undefined: return v
        raise JSThrow(_make_error('ReferenceError', f"'{name}' is not defined"))

    def set(self, name, value, strict=None):
        if strict is None: strict = self.is_strict()
        scope = self
        while scope is not None:
            if name in scope.vars:
                scope.vars[name] = value
                return
            scope = scope.parent
        if g_global is not None:
            if strict:
                raise JSThrow(_make_error('ReferenceError', f"'{name}' is not defined"))
            g_global._set(name, value)
        elif strict:
            raise JSThrow(_make_error('ReferenceError', f"'{name}' is not defined"))

    def has_own(self, name): return name in self.vars
    def def_var(self, name, v=undefined): self.vars[name] = v
    def def_let(self, name, v=_UNINIT): self.vars[name] = v
    def set_own(self, name, v): self.vars[name] = v

    def get_this(self):
        scope = self
        while scope is not None:
            if scope.this_val is not None: return scope.this_val
            scope = scope.parent
        return g_global or undefined

    def is_strict(self):
        scope = self
        while scope is not None:
            if scope._strict: return True
            scope = scope.parent
        return False

    def get_func_scope(self):
        scope = self
        while scope is not None:
            if scope._func_scope is self: return scope
            scope = scope.parent
        return None

# ===== Lexer =====

KEYWORDS_SET = {
    'break','case','catch','class','const','continue','debugger',
    'default','delete','do','else','export','extends','finally',
    'for','function','if','import','in','instanceof','let','new',
    'return','static','super','switch','this','throw','try',
    'typeof','var','void','while','with','yield','null','true','false',
    'async','await','from','as','of','get','set','target','meta',
    'undefined',
}

class Token:
    __slots__ = ['t','v','line','col']
    def __init__(self, t, v, line=0, col=0):
        self.t = t; self.v = v; self.line = line; self.col = col
    def __repr__(self): return f'Tok({self.t!r},{self.v!r})'

def tokenize(src, filename='<unknown>'):
    tokens = []
    n = len(src)
    pos = 0; line = 1; col = 1
    prev_line = 1

    def add(t, v, ln=None, cl=None):
        tokens.append(Token(t, v, ln if ln is not None else line, cl if cl is not None else col))

    def skip_line_comment():
        nonlocal pos, col
        while pos < n and src[pos] != '\n':
            pos += 1; col += 1

    def skip_block_comment():
        nonlocal pos, line, col
        pos += 2; col += 2
        while pos < n:
            if src[pos] == '\n': line += 1; col = 1; pos += 1
            elif src[pos] == '*' and pos+1 < n and src[pos+1] == '/':
                pos += 2; col += 2; return
            else: pos += 1; col += 1

    def read_string(q):
        nonlocal pos, line, col
        pos += 1; col += 1
        parts = []
        while pos < n:
            c = src[pos]
            if c == q:
                pos += 1; col += 1; break
            if c == '\\' and pos+1 < n:
                pos += 1; col += 1
                e = src[pos]
                if e == 'n': parts.append('\n')
                elif e == 'r': parts.append('\r')
                elif e == 't': parts.append('\t')
                elif e == 'b': parts.append('\b')
                elif e == 'f': parts.append('\f')
                elif e == 'v': parts.append('\v')
                elif e == '0' and (pos+1 >= n or not src[pos+1].isdigit()): parts.append('\0')
                elif e == '\\': parts.append('\\')
                elif e in ('"',"'",'`'): parts.append(e)
                elif e == '\n': line += 1; col = 1
                elif e == '\r':
                    line += 1; col = 1
                    if pos+1 < n and src[pos+1] == '\n': pos += 1
                elif e == 'u':
                    pos += 1; col += 1
                    if pos < n and src[pos] == '{':
                        j = pos+1
                        while j < n and src[j] != '}': j += 1
                        try: parts.append(chr(int(src[pos+1:j], 16)))
                        except: parts.append('\ufffd')
                        col += j - pos + 1; pos = j
                    elif pos+3 < n:
                        try: parts.append(chr(int(src[pos:pos+4], 16)))
                        except: parts.append('\ufffd')
                        col += 3; pos += 3
                    else: parts.append('\\u')
                elif e == 'x' and pos+2 < n:
                    try: parts.append(chr(int(src[pos+1:pos+3], 16)))
                    except: parts.append('\ufffd')
                    pos += 2; col += 2
                else: parts.append(e)
                pos += 1; col += 1; continue
            if c == '\n': line += 1; col = 1; parts.append('\n')
            else: parts.append(c); col += 1
            pos += 1
        return ''.join(parts)

    def read_template():
        nonlocal pos, line, col
        pos += 1; col += 1  # skip opening `
        return _read_template_part()

    def _read_template_part():
        nonlocal pos, line, col
        parts = []
        start_line, start_col = line, col
        while pos < n:
            c = src[pos]
            if c == '`':
                pos += 1; col += 1
                return ('TEMPLATE_FULL', ''.join(parts), start_line, start_col)
            if c == '$' and pos+1 < n and src[pos+1] == '{':
                pos += 2; col += 2
                return ('TEMPLATE_HEAD', ''.join(parts), start_line, start_col)
            if c == '\\' and pos+1 < n:
                pos += 1; col += 1
                e = src[pos]
                if e == 'n': parts.append('\n')
                elif e == 'r': parts.append('\r')
                elif e == 't': parts.append('\t')
                elif e == '\\': parts.append('\\')
                elif e == '`': parts.append('`')
                elif e == '$': parts.append('$')
                elif e == '\n': line += 1; col = 1
                elif e == 'u':
                    pos += 1; col += 1
                    if pos < n and src[pos] == '{':
                        j = pos+1
                        while j < n and src[j] != '}': j += 1
                        try: parts.append(chr(int(src[pos+1:j], 16)))
                        except: parts.append('\ufffd')
                        col += j-pos+1; pos = j
                    elif pos+3 < n:
                        try: parts.append(chr(int(src[pos:pos+4], 16)))
                        except: parts.append('\ufffd')
                        col += 3; pos += 3
                    else: parts.append('\\u')
                else: parts.append(e)
                pos += 1; col += 1; continue
            if c == '\n': line += 1; col = 1; parts.append('\n')
            else: parts.append(c); col += 1
            pos += 1
        return ('TEMPLATE_FULL', ''.join(parts), start_line, start_col)

    def read_number(start):
        nonlocal pos, col
        # Already at first digit or dot
        s = start
        base = 10
        if s == '0' and pos < n:
            nc = src[pos]
            if nc in 'xX':
                pos += 1; col += 1
                while pos < n and (src[pos] in '0123456789abcdefABCDEF_'): pos += 1; col += 1
                val_s = src[num_start:pos].replace('_', '')
                is_bigint = pos < n and src[pos] == 'n'
                if is_bigint: pos += 1; col += 1
                try:
                    if is_bigint: return ('BIGINT', int(val_s, 16))
                    return ('NUMBER', float(int(val_s, 16)))
                except: return ('NUMBER', float('nan'))
            if nc in 'oO':
                pos += 1; col += 1
                while pos < n and src[pos] in '01234567_': pos += 1; col += 1
                val_s = src[num_start:pos].replace('_', '')
                is_bigint = pos < n and src[pos] == 'n'
                if is_bigint: pos += 1; col += 1
                try:
                    if is_bigint: return ('BIGINT', int(val_s, 8))
                    return ('NUMBER', float(int(val_s, 8)))
                except: return ('NUMBER', float('nan'))
            if nc in 'bB':
                pos += 1; col += 1
                while pos < n and src[pos] in '01_': pos += 1; col += 1
                val_s = src[num_start:pos].replace('_', '')
                is_bigint = pos < n and src[pos] == 'n'
                if is_bigint: pos += 1; col += 1
                try:
                    if is_bigint: return ('BIGINT', int(val_s, 2))
                    return ('NUMBER', float(int(val_s, 2)))
                except: return ('NUMBER', float('nan'))

        while pos < n and (src[pos].isdigit() or src[pos] == '_'): pos += 1; col += 1
        if pos < n and src[pos] == '.':
            pos += 1; col += 1
            while pos < n and (src[pos].isdigit() or src[pos] == '_'): pos += 1; col += 1
        if pos < n and src[pos] in 'eE':
            pos += 1; col += 1
            if pos < n and src[pos] in '+-': pos += 1; col += 1
            while pos < n and src[pos].isdigit(): pos += 1; col += 1

        is_bigint = pos < n and src[pos] == 'n'
        if is_bigint: pos += 1; col += 1
        val_s = src[num_start:pos - (1 if is_bigint else 0)].replace('_', '')
        if is_bigint:
            try: return ('BIGINT', int(val_s))
            except: return ('NUMBER', 0)
        try: return ('NUMBER', float(val_s))
        except: return ('NUMBER', float('nan'))

    while pos < n:
        sl = line; sc = col
        c = src[pos]

        # Whitespace
        if c in ' \t\r\x0c\x0b':
            pos += 1; col += 1; continue
        if c == '\n':
            add('NL', '\n', line, col)
            pos += 1; line += 1; col = 1; continue
        # Unicode spaces/separators
        if c == '\u2028' or c == '\u2029':
            add('NL', c, line, col)
            pos += 1; line += 1; col = 1; continue

        # Comments
        if c == '/' and pos+1 < n:
            if src[pos+1] == '/': skip_line_comment(); continue
            if src[pos+1] == '*': skip_block_comment(); continue

        # Strings
        if c in '"\'':
            sl2, sc2 = line, col
            s = read_string(c)
            add('STR', s, sl2, sc2); continue

        # Template literals
        if c == '`':
            sl2, sc2 = line, col
            typ, val, tl, tc = _read_template_part()
            if typ == 'TEMPLATE_FULL':
                add('TMPL_FULL', val, tl, tc)
            else:
                add('TMPL_HEAD', val, tl, tc)
            continue

        # Numbers
        if c.isdigit() or (c == '.' and pos+1 < n and src[pos+1].isdigit()):
            num_start = pos
            s = c; pos += 1; col += 1
            typ, val = read_number(s)
            add(typ, val, sl, sc); continue

        # Identifiers/keywords
        if c.isalpha() or c in '_$' or ord(c) > 127:
            j = pos
            while j < n and (src[j].isalnum() or src[j] in '_$' or ord(src[j]) > 127):
                j += 1
            ident = src[pos:j]
            col += j - pos; pos = j
            if ident in KEYWORDS_SET:
                add('KW:'+ident, ident, sl, sc)
            else:
                add('ID', ident, sl, sc)
            continue

        # Operators (multi-char first)
        rem = src[pos:]
        matched = False
        for op in ['>>>=','<<=','>>=','**=','&&=','||=','??=',
                   '===','!==','...','**','&&','||','??','++','--',
                   '<=','>=','==','!=','=>','?.','+=','-=','*=','/=',
                   '%=','&=','|=','^=','<<','>>','>>>','#!']:
            if rem.startswith(op):
                add(op, op, sl, sc)
                pos += len(op); col += len(op); matched = True; break
        if matched: continue

        # Single char operators
        if c in '{}[]().,;:?~!+-*/%&|^<>=@#\\':
            add(c, c, sl, sc); pos += 1; col += 1; continue

        pos += 1; col += 1

    add('EOF', None, line, col)
    return tokens

class TokenStream:
    def __init__(self, tokens):
        self.toks = tokens
        self.pos = 0
        # Pre-process: mark tokens with newline-before flag
        self._compute_newlines()

    def _compute_newlines(self):
        self.nl_before = [False] * len(self.toks)
        nl = False
        for i, t in enumerate(self.toks):
            if t.t == 'NL':
                nl = True
            else:
                self.nl_before[i] = nl
                nl = False
        # Remove NL tokens
        self.toks = [t for t in self.toks if t.t != 'NL']
        self.nl_before = [self.nl_before[i] for i, t in enumerate(self.toks) if t.t != 'NL']

    def peek(self, off=0):
        i = self.pos + off
        if i >= len(self.toks): return self.toks[-1]
        return self.toks[i]

    def next(self):
        t = self.toks[self.pos]
        if self.pos < len(self.toks)-1: self.pos += 1
        return t

    def consume(self):
        return self.next()

    def expect(self, typ):
        t = self.peek()
        if t.t != typ:
            raise SyntaxError(f"Expected {typ!r} got {t.t!r} ({t.v!r}) at line {t.line}:{t.col}")
        return self.next()

    def match(self, *types):
        t = self.peek()
        if t.t in types: return self.next()
        return None

    def is_kw(self, *kws):
        t = self.peek()
        return t.t in ['KW:'+k for k in kws]

    def match_kw(self, *kws):
        t = self.peek()
        for k in kws:
            if t.t == 'KW:'+k: return self.next()
        return None

    def expect_kw(self, kw):
        t = self.peek()
        if t.t != 'KW:'+kw:
            raise SyntaxError(f"Expected keyword '{kw}' got {t.t!r} at line {t.line}:{t.col}")
        return self.next()

    def nl_before_current(self):
        return self.nl_before[self.pos] if self.pos < len(self.nl_before) else False

    def is_id(self, name=None):
        t = self.peek()
        if t.t == 'ID': return name is None or t.v == name
        if name and t.t == 'KW:'+name: return True
        return False

    def match_id(self, name=None):
        t = self.peek()
        if t.t == 'ID' and (name is None or t.v == name): return self.next()
        if name and t.t == 'KW:'+name: return self.next()
        return None

    def auto_semicolon(self):
        """Try to insert automatic semicolon"""
        t = self.peek()
        if t.t == ';': self.next(); return True
        if t.t == '}' or t.t == 'EOF': return True
        if self.nl_before_current(): return True
        return False

    def semi(self):
        """Consume semicolon or ASI"""
        t = self.peek()
        if t.t == ';': self.next(); return
        if t.t == '}' or t.t == 'EOF': return
        if self.nl_before_current(): return
        raise SyntaxError(f"Expected ';' got {t.t!r} ({t.v!r}) at line {t.line}:{t.col}")

