# ===== Parser =====
# Produces AST nodes

class Node:
    def __init__(self, t, **kw):
        self.t = t
        self.line = kw.pop('line', 0)
        self.col = kw.pop('col', 0)
        for k, v in kw.items(): setattr(self, k, v)
    def __repr__(self): return f'Node({self.t})'

def N(t, ln=0, cl=0, **kw): return Node(t, line=ln, col=cl, **kw)

class Parser:
    def __init__(self, src, filename='<unknown>', module=False, strict=False):
        self.src = src
        self.filename = filename
        self.is_module = module
        self.is_strict = strict or module
        tokens = tokenize(src, filename)
        self.ts = TokenStream(tokens)
        self._in_func = 0
        self._in_generator = 0
        self._in_async = 0
        self._in_class = 0
        self._labels = set()

    @property
    def ts_peek(self): return self.ts.peek()

    def loc(self):
        t = self.ts.peek()
        return t.line, t.col

    def parse(self):
        stmts = self.parse_stmts(top=True)
        return N('Program', stmts=stmts, is_module=self.is_module)

    def parse_stmts(self, top=False):
        stmts = []
        # Handle "use strict" directive
        if top and self.ts.peek().t == 'STR' and self.ts.peek().v == 'use strict':
            t = self.ts.next()
            self.ts.semi()
            self.is_strict = True
        while self.ts.peek().t not in ('EOF', '}'):
            s = self.parse_stmt()
            if s is not None: stmts.append(s)
        return stmts

    def parse_block(self):
        ln, cl = self.loc()
        self.ts.expect('{')
        stmts = self.parse_stmts()
        self.ts.expect('}')
        return N('Block', line=ln, col=cl, body=stmts)

    def parse_stmt(self):
        t = self.ts.peek()
        ln, cl = t.line, t.col

        if t.t == ';': self.ts.next(); return None
        if t.t == '{': return self.parse_block()

        # Keywords
        kw = t.t
        if kw == 'KW:var': return self.parse_var_decl('var')
        if kw == 'KW:let': return self.parse_var_decl('let')
        if kw == 'KW:const': return self.parse_var_decl('const')
        if kw == 'KW:function':
            return self.parse_func_decl(async_=False)
        if kw == 'KW:async':
            nxt = self.ts.peek(1)
            if nxt.t == 'KW:function' and not self.ts.nl_before_current():
                return self.parse_func_decl(async_=True)
        if kw == 'KW:class': return self.parse_class_decl()
        if kw == 'KW:return': return self.parse_return()
        if kw == 'KW:if': return self.parse_if()
        if kw == 'KW:while': return self.parse_while()
        if kw == 'KW:do': return self.parse_do_while()
        if kw == 'KW:for': return self.parse_for()
        if kw == 'KW:break': return self.parse_break()
        if kw == 'KW:continue': return self.parse_continue()
        if kw == 'KW:throw': return self.parse_throw()
        if kw == 'KW:try': return self.parse_try()
        if kw == 'KW:switch': return self.parse_switch()
        if kw == 'KW:import': return self.parse_import()
        if kw == 'KW:export': return self.parse_export()
        if kw == 'KW:with': return self.parse_with()
        if kw == 'KW:debugger':
            self.ts.next(); self.ts.semi()
            return N('Debugger', line=ln, col=cl)

        # Label or expression
        if t.t == 'ID':
            nxt = self.ts.peek(1)
            if nxt.t == ':':
                label = self.ts.next().v
                self.ts.next()  # skip ':'
                self._labels.add(label)
                body = self.parse_stmt()
                self._labels.discard(label)
                return N('Labeled', line=ln, col=cl, label=label, body=body)

        # Expression statement
        expr = self.parse_expr()
        self.ts.semi()
        return N('ExprStmt', line=ln, col=cl, expr=expr)

    def parse_var_decl(self, kind):
        ln, cl = self.loc()
        self.ts.next()  # consume 'var'/'let'/'const'
        decls = []
        while True:
            t = self.ts.peek()
            if t.t == 'ID' or t.t == '{' or t.t == '[':
                pattern = self.parse_binding_pattern()
                init = None
                if self.ts.match('='):
                    init = self.parse_assign_expr()
                decls.append(N('Decl', pattern=pattern, init=init))
            else:
                break
            if not self.ts.match(','): break
        self.ts.semi()
        return N('VarDecl', line=ln, col=cl, kind=kind, decls=decls)

    def parse_binding_pattern(self):
        t = self.ts.peek()
        if t.t == '{': return self.parse_obj_pattern()
        if t.t == '[': return self.parse_arr_pattern()
        t = self.ts.next()
        return N('Ident', name=t.v, line=t.line, col=t.col)

    def parse_obj_pattern(self):
        ln, cl = self.loc()
        self.ts.expect('{')
        props = []
        while self.ts.peek().t != '}':
            if self.ts.peek().t == '...':
                self.ts.next()
                rest = self.parse_binding_pattern()
                props.append(N('RestProp', pattern=rest))
                break
            key = self.parse_prop_name()
            if self.ts.match(':'):
                val = self.parse_binding_pattern()
                default = None
                if self.ts.match('='): default = self.parse_assign_expr()
                props.append(N('ObjPropPat', key=key, val=val, default=default))
            else:
                default = None
                if self.ts.match('='): default = self.parse_assign_expr()
                props.append(N('ObjShortPat', key=key, default=default))
            if not self.ts.match(','): break
        self.ts.expect('}')
        return N('ObjPat', line=ln, col=cl, props=props)

    def parse_arr_pattern(self):
        ln, cl = self.loc()
        self.ts.expect('[')
        items = []
        while self.ts.peek().t != ']':
            if self.ts.peek().t == ',':
                items.append(None)
                self.ts.next()
                continue
            if self.ts.peek().t == '...':
                self.ts.next()
                rest = self.parse_binding_pattern()
                items.append(N('RestElem', pattern=rest))
                if self.ts.peek().t == ',': self.ts.next()
                break
            pat = self.parse_binding_pattern()
            default = None
            if self.ts.match('='): default = self.parse_assign_expr()
            items.append(N('ArrPatItem', pattern=pat, default=default))
            if not self.ts.match(','): break
        self.ts.expect(']')
        return N('ArrPat', line=ln, col=cl, items=items)

    def parse_func_decl(self, async_=False):
        ln, cl = self.loc()
        if async_: self.ts.next()  # skip 'async'
        self.ts.next()  # skip 'function'
        is_gen = bool(self.ts.match('*'))
        name = None
        if self.ts.peek().t in ('ID',) or self.ts.peek().t.startswith('KW:'):
            name = self.ts.next().v
        func = self.parse_func_rest(name, is_gen, async_)
        func.line = ln; func.col = cl
        return N('FuncDecl', line=ln, col=cl, func=func)

    def parse_func_rest(self, name, is_gen=False, is_async=False):
        ln, cl = self.loc()
        self.ts.expect('(')
        params = self.parse_params()
        self.ts.expect(')')
        prev_gen, prev_async = self._in_generator, self._in_async
        self._in_func += 1
        self._in_generator = 1 if is_gen else 0
        self._in_async = 1 if is_async else 0
        body = self.parse_block()
        self._in_func -= 1
        self._in_generator = prev_gen
        self._in_async = prev_async
        return N('Func', line=ln, col=cl, name=name, params=params, body=body,
                 is_gen=is_gen, is_async=is_async)

    def parse_params(self):
        params = []
        while self.ts.peek().t != ')':
            if self.ts.peek().t == '...':
                self.ts.next()
                rest = self.parse_binding_pattern()
                params.append(N('RestParam', pattern=rest))
                break
            pat = self.parse_binding_pattern()
            default = None
            if self.ts.match('='): default = self.parse_assign_expr()
            params.append(N('Param', pattern=pat, default=default))
            if not self.ts.match(','): break
        return params

    def parse_class_decl(self):
        ln, cl = self.loc()
        self.ts.next()  # 'class'
        name = None
        if self.ts.peek().t == 'ID': name = self.ts.next().v
        superclass = None
        if self.ts.match_kw('extends'):
            superclass = self.parse_left_expr()
        self.ts.expect('{')
        methods = []
        self._in_class += 1
        while self.ts.peek().t != '}':
            if self.ts.peek().t == ';': self.ts.next(); continue
            m = self.parse_class_member()
            if m: methods.append(m)
        self._in_class -= 1
        self.ts.expect('}')
        return N('ClassDecl', line=ln, col=cl, name=name, superclass=superclass, methods=methods)

    def parse_class_member(self):
        ln, cl = self.loc()
        is_static = False
        is_private = False

        if self.ts.peek().t == 'KW:static':
            self.ts.next()
            is_static = True
            # static block
            if self.ts.peek().t == '{':
                block = self.parse_block()
                return N('StaticBlock', line=ln, col=cl, body=block)

        # Access modifiers
        kind = 'method'
        t = self.ts.peek()

        # Check for accessor keywords
        if t.t in ('KW:get', 'KW:set') or (t.t == 'ID' and t.v in ('get', 'set')):
            nxt = self.ts.peek(1)
            if nxt.t not in ('(', ';', '=', '}'):
                kind = t.v; self.ts.next()
                t = self.ts.peek()

        # Check for async
        is_async = False
        if t.t == 'KW:async' and self.ts.peek(1).t != '(':
            self.ts.next(); is_async = True; t = self.ts.peek()

        # Generator
        is_gen = False
        if t.t == '*': self.ts.next(); is_gen = True; t = self.ts.peek()

        # Private field
        if t.t == '#!':
            # This is a private hash prefix
            pass

        # Get key
        is_private = self.ts.peek().t == '#!'
        if is_private:
            self.ts.next()
            key = '#' + self.ts.next().v
            key_node = N('PrivKey', name=key)
        else:
            key_node = self.parse_prop_name()

        # Field definition (no parens)
        if self.ts.peek().t not in ('(', ):
            # Class field
            init = None
            if self.ts.match('='): init = self.parse_assign_expr()
            self.ts.semi()
            return N('ClassField', line=ln, col=cl, key=key_node, init=init, 
                    is_static=is_static, is_private=is_private)

        # Method
        self.ts.expect('(')
        params = self.parse_params()
        self.ts.expect(')')
        prev_gen, prev_async = self._in_generator, self._in_async
        self._in_func += 1
        self._in_generator = 1 if is_gen else 0
        self._in_async = 1 if is_async else 0
        body = self.parse_block()
        self._in_func -= 1
        self._in_generator = prev_gen
        self._in_async = prev_async
        func = N('Func', line=ln, col=cl, name=None, params=params, body=body,
                 is_gen=is_gen, is_async=is_async)
        return N('ClassMethod', line=ln, col=cl, key=key_node, func=func,
                kind=kind, is_static=is_static, is_private=is_private)

    def parse_return(self):
        ln, cl = self.loc()
        self.ts.next()  # 'return'
        val = None
        if not self.ts.auto_semicolon() and self.ts.peek().t != 'EOF':
            val = self.parse_expr()
            self.ts.semi()
        return N('Return', line=ln, col=cl, value=val)

    def parse_if(self):
        ln, cl = self.loc()
        self.ts.next()  # 'if'
        self.ts.expect('(')
        test = self.parse_expr()
        self.ts.expect(')')
        then = self.parse_stmt()
        else_ = None
        if self.ts.match_kw('else'):
            else_ = self.parse_stmt()
        return N('If', line=ln, col=cl, test=test, then=then, else_=else_)

    def parse_while(self):
        ln, cl = self.loc()
        self.ts.next()
        self.ts.expect('(')
        test = self.parse_expr()
        self.ts.expect(')')
        body = self.parse_stmt()
        return N('While', line=ln, col=cl, test=test, body=body)

    def parse_do_while(self):
        ln, cl = self.loc()
        self.ts.next()
        body = self.parse_stmt()
        self.ts.expect_kw('while')
        self.ts.expect('(')
        test = self.parse_expr()
        self.ts.expect(')')
        self.ts.semi()
        return N('DoWhile', line=ln, col=cl, test=test, body=body)

    def parse_for(self):
        ln, cl = self.loc()
        self.ts.next()  # 'for'
        is_await = bool(self.ts.match_kw('await'))
        self.ts.expect('(')

        # for-of or for-in or regular for
        init = None
        t = self.ts.peek()

        if t.t in ('KW:var', 'KW:let', 'KW:const'):
            kind = t.v[3:]; self.ts.next()
            pat = self.parse_binding_pattern()
            if self.ts.match_kw('of') or (self.ts.peek().t == 'KW:of'):
                if self.ts.peek().t == 'KW:of': self.ts.next()
                iter_ = self.parse_assign_expr()
                self.ts.expect(')')
                body = self.parse_stmt()
                return N('ForOf', line=ln, col=cl, is_await=is_await,
                        kind=kind, pat=pat, iter=iter_, body=body)
            if self.ts.match_kw('in'):
                iter_ = self.parse_expr()
                self.ts.expect(')')
                body = self.parse_stmt()
                return N('ForIn', line=ln, col=cl, kind=kind, pat=pat, iter=iter_, body=body)
            # Regular for with init
            init_decl = N('VarDecl', line=ln, kind=kind, decls=[])
            init_val = None
            if self.ts.match('='): init_val = self.parse_assign_expr()
            init_decl.decls.append(N('Decl', pattern=pat, init=init_val))
            while self.ts.match(','):
                p2 = self.parse_binding_pattern()
                v2 = None
                if self.ts.match('='): v2 = self.parse_assign_expr()
                init_decl.decls.append(N('Decl', pattern=p2, init=v2))
            init = init_decl
        elif t.t != ';':
            # Check for for-of/in with expression
            expr = self.parse_assign_expr()
            if self.ts.match_kw('of'):
                iter_ = self.parse_assign_expr()
                self.ts.expect(')')
                body = self.parse_stmt()
                return N('ForOf', line=ln, col=cl, is_await=is_await,
                        kind=None, pat=expr, iter=iter_, body=body)
            if self.ts.match_kw('in'):
                iter_ = self.parse_expr()
                self.ts.expect(')')
                body = self.parse_stmt()
                return N('ForIn', line=ln, col=cl, kind=None, pat=expr, iter=iter_, body=body)
            # Check for more exprs
            if self.ts.peek().t == ',':
                self.ts.next()
                rest = self.parse_expr_list()
                exprs = [expr] + rest
                init = N('SeqExpr', exprs=exprs)
            else:
                init = expr

        self.ts.expect(';')
        test = None
        if self.ts.peek().t != ';': test = self.parse_expr()
        self.ts.expect(';')
        update = None
        if self.ts.peek().t != ')': update = self.parse_expr()
        self.ts.expect(')')
        body = self.parse_stmt()
        return N('For', line=ln, col=cl, init=init, test=test, update=update, body=body)

    def parse_break(self):
        ln, cl = self.loc()
        self.ts.next()
        label = None
        if not self.ts.nl_before_current() and self.ts.peek().t == 'ID':
            label = self.ts.next().v
        self.ts.semi()
        return N('Break', line=ln, col=cl, label=label)

    def parse_continue(self):
        ln, cl = self.loc()
        self.ts.next()
        label = None
        if not self.ts.nl_before_current() and self.ts.peek().t == 'ID':
            label = self.ts.next().v
        self.ts.semi()
        return N('Continue', line=ln, col=cl, label=label)

    def parse_throw(self):
        ln, cl = self.loc()
        self.ts.next()
        if self.ts.nl_before_current():
            raise SyntaxError(f"Illegal newline after 'throw' at line {ln}")
        val = self.parse_expr()
        self.ts.semi()
        return N('Throw', line=ln, col=cl, value=val)

    def parse_try(self):
        ln, cl = self.loc()
        self.ts.next()
        body = self.parse_block()
        catch_ = None
        finally_ = None
        if self.ts.match_kw('catch'):
            catch_param = None
            if self.ts.match('('):
                catch_param = self.parse_binding_pattern()
                self.ts.expect(')')
            catch_body = self.parse_block()
            catch_ = N('Catch', param=catch_param, body=catch_body)
        if self.ts.match_kw('finally'):
            finally_ = self.parse_block()
        return N('Try', line=ln, col=cl, body=body, catch_=catch_, finally_=finally_)

    def parse_switch(self):
        ln, cl = self.loc()
        self.ts.next()
        self.ts.expect('(')
        disc = self.parse_expr()
        self.ts.expect(')')
        self.ts.expect('{')
        cases = []
        while self.ts.peek().t != '}':
            if self.ts.match_kw('case'):
                test = self.parse_expr()
                self.ts.expect(':')
                stmts = []
                while self.ts.peek().t not in ('}',) and not self.ts.is_kw('case', 'default'):
                    s = self.parse_stmt()
                    if s: stmts.append(s)
                cases.append(N('Case', test=test, body=stmts))
            elif self.ts.match_kw('default'):
                self.ts.expect(':')
                stmts = []
                while self.ts.peek().t not in ('}',) and not self.ts.is_kw('case', 'default'):
                    s = self.parse_stmt()
                    if s: stmts.append(s)
                cases.append(N('Default', body=stmts))
            else:
                break
        self.ts.expect('}')
        return N('Switch', line=ln, col=cl, disc=disc, cases=cases)

    def parse_import(self):
        ln, cl = self.loc()
        self.ts.next()  # 'import'

        # import() dynamic
        if self.ts.peek().t == '(':
            self.ts.next()
            src = self.parse_assign_expr()
            self.ts.expect(')')
            return N('ExprStmt', line=ln, col=cl, expr=N('ImportCall', line=ln, src=src))

        # import.meta
        if self.ts.peek().t == '.':
            self.ts.next()
            self.ts.next()  # 'meta'
            return N('ExprStmt', line=ln, col=cl, expr=N('ImportMeta', line=ln))

        # Static imports
        specifiers = []
        src = None

        if self.ts.peek().t == 'STR':
            src = self.ts.next().v
        else:
            # Default import
            if self.ts.peek().t == 'ID':
                name = self.ts.next().v
                specifiers.append(N('ImportDefault', name=name))

            if self.ts.match(',') or not specifiers:
                if self.ts.peek().t == '*':
                    self.ts.next()
                    self.ts.expect_kw('as')
                    name = self.ts.next().v
                    specifiers.append(N('ImportNS', name=name))
                elif self.ts.peek().t == '{':
                    self.ts.next()
                    while self.ts.peek().t != '}':
                        orig = self.ts.next().v
                        if self.ts.match_kw('as'):
                            local = self.ts.next().v
                        else:
                            local = orig
                        specifiers.append(N('ImportSpec', orig=orig, local=local))
                        if not self.ts.match(','): break
                    self.ts.expect('}')

            self.ts.expect_kw('from')
            src = self.ts.next().v

        self.ts.semi()
        return N('Import', line=ln, col=cl, specifiers=specifiers, src=src)

    def parse_export(self):
        ln, cl = self.loc()
        self.ts.next()  # 'export'

        if self.ts.match_kw('default'):
            if self.ts.is_kw('function'):
                decl = self.parse_func_decl()
                return N('ExportDefault', line=ln, decl=decl)
            if self.ts.is_kw('class'):
                decl = self.parse_class_decl()
                return N('ExportDefault', line=ln, decl=decl)
            if self.ts.is_kw('async'):
                nxt = self.ts.peek(1)
                if nxt.t == 'KW:function':
                    decl = self.parse_func_decl(async_=True)
                    return N('ExportDefault', line=ln, decl=decl)
            expr = self.parse_assign_expr()
            self.ts.semi()
            return N('ExportDefault', line=ln, expr=expr)

        if self.ts.match('*'):
            src = None
            if self.ts.match_kw('from'):
                src = self.ts.next().v
            self.ts.semi()
            return N('ExportAll', line=ln, src=src)

        if self.ts.peek().t == '{':
            self.ts.next()
            specs = []
            while self.ts.peek().t != '}':
                local = self.ts.next().v
                exported = local
                if self.ts.match_kw('as'): exported = self.ts.next().v
                specs.append(N('ExportSpec', local=local, exported=exported))
                if not self.ts.match(','): break
            self.ts.expect('}')
            src = None
            if self.ts.match_kw('from'): src = self.ts.next().v
            self.ts.semi()
            return N('ExportNamed', line=ln, specs=specs, src=src)

        if self.ts.is_kw('var', 'let', 'const'):
            decl = self.parse_var_decl(self.ts.peek().v)
            return N('ExportDecl', line=ln, decl=decl)
        if self.ts.is_kw('function'):
            decl = self.parse_func_decl()
            return N('ExportDecl', line=ln, decl=decl)
        if self.ts.is_kw('class'):
            decl = self.parse_class_decl()
            return N('ExportDecl', line=ln, decl=decl)
        if self.ts.is_kw('async'):
            decl = self.parse_func_decl(async_=True)
            return N('ExportDecl', line=ln, decl=decl)

        expr = self.parse_expr()
        self.ts.semi()
        return N('ExportDecl', line=ln, decl=N('ExprStmt', expr=expr))

    def parse_with(self):
        ln, cl = self.loc()
        self.ts.next()
        self.ts.expect('(')
        obj = self.parse_expr()
        self.ts.expect(')')
        body = self.parse_stmt()
        return N('With', line=ln, col=cl, obj=obj, body=body)

    # ===== Expressions =====

    def parse_expr(self):
        exprs = [self.parse_assign_expr()]
        while self.ts.match(','):
            exprs.append(self.parse_assign_expr())
        if len(exprs) == 1: return exprs[0]
        return N('SeqExpr', exprs=exprs)

    def parse_expr_list(self):
        result = [self.parse_assign_expr()]
        while self.ts.match(','):
            result.append(self.parse_assign_expr())
        return result

    def parse_assign_expr(self):
        ln, cl = self.loc()

        # Yield expression
        if self._in_generator and self.ts.is_kw('yield'):
            self.ts.next()
            delegate = bool(self.ts.match('*'))
            val = None
            if not self.ts.nl_before_current() and self.ts.peek().t not in (';', '}', ')', ']', ',', 'EOF'):
                val = self.parse_assign_expr()
            return N('Yield', line=ln, col=cl, value=val, delegate=delegate)

        # Async arrow functions
        if self.ts.is_kw('async') and not self.ts.nl_before_current():
            nxt = self.ts.peek(1)
            if nxt.t == '(':
                saved_pos = self.ts.pos
                self.ts.next()  # skip 'async'
                self.ts.next()  # skip '('
                # Try to parse arrow function params
                try:
                    saved = self.ts.pos
                    params = self.parse_params()
                    self.ts.expect(')')
                    if self.ts.peek().t == '=>':
                        self.ts.next()
                        body = self._parse_arrow_body(True, True)
                        return N('Arrow', line=ln, params=params, body=body, is_async=True)
                except: pass
                self.ts.pos = saved_pos
            elif nxt.t == 'ID':
                saved_pos = self.ts.pos
                self.ts.next()  # 'async'
                name = self.ts.next().v
                if self.ts.peek().t == '=>' and not self.ts.nl_before_current():
                    self.ts.next()
                    body = self._parse_arrow_body(True, True)
                    params = [N('Param', pattern=N('Ident', name=name), default=None)]
                    return N('Arrow', line=ln, params=params, body=body, is_async=True)
                self.ts.pos = saved_pos

        left = self.parse_cond_expr()

        # Arrow function with single param
        if left.t == 'Ident' and self.ts.peek().t == '=>' and not self.ts.nl_before_current():
            self.ts.next()
            params = [N('Param', pattern=left, default=None)]
            body = self._parse_arrow_body(False, False)
            return N('Arrow', line=ln, params=params, body=body, is_async=False)

        # Assignment operators
        ops = ('=','+=','-=','*=','/=','%=','**=','&=','|=','^=',
               '<<=','>>=','>>>=','&&=','||=','??=')
        t = self.ts.peek()
        if t.t in ops:
            op = t.t; self.ts.next()
            right = self.parse_assign_expr()
            return N('Assign', line=ln, col=cl, op=op, left=left, right=right)

        return left

    def _parse_arrow_body(self, is_async, is_async2):
        ln, cl = self.loc()
        self._in_func += 1
        prev_async = self._in_async
        self._in_async = 1 if is_async2 else 0
        if self.ts.peek().t == '{':
            body = self.parse_block()
        else:
            body = self.parse_assign_expr()
        self._in_func -= 1
        self._in_async = prev_async
        return body

    def parse_cond_expr(self):
        ln, cl = self.loc()
        test = self.parse_nullish()
        if self.ts.match('?'):
            then = self.parse_assign_expr()
            self.ts.expect(':')
            else_ = self.parse_assign_expr()
            return N('Cond', line=ln, col=cl, test=test, then=then, else_=else_)
        return test

    def parse_nullish(self):
        ln, cl = self.loc()
        left = self.parse_or()
        while self.ts.match('??'):
            right = self.parse_or()
            left = N('Bin', line=ln, col=cl, op='??', left=left, right=right)
        return left

    def parse_or(self):
        ln, cl = self.loc()
        left = self.parse_and()
        while self.ts.match('||'):
            right = self.parse_and()
            left = N('Bin', line=ln, col=cl, op='||', left=left, right=right)
        return left

    def parse_and(self):
        ln, cl = self.loc()
        left = self.parse_bitor()
        while self.ts.match('&&'):
            right = self.parse_bitor()
            left = N('Bin', line=ln, col=cl, op='&&', left=left, right=right)
        return left

    def parse_bitor(self):
        ln, cl = self.loc()
        left = self.parse_bitxor()
        while self.ts.peek().t == '|':
            self.ts.next()
            right = self.parse_bitxor()
            left = N('Bin', line=ln, col=cl, op='|', left=left, right=right)
        return left

    def parse_bitxor(self):
        ln, cl = self.loc()
        left = self.parse_bitand()
        while self.ts.peek().t == '^':
            self.ts.next()
            right = self.parse_bitand()
            left = N('Bin', line=ln, col=cl, op='^', left=left, right=right)
        return left

    def parse_bitand(self):
        ln, cl = self.loc()
        left = self.parse_equality()
        while self.ts.peek().t == '&':
            self.ts.next()
            right = self.parse_equality()
            left = N('Bin', line=ln, col=cl, op='&', left=left, right=right)
        return left

    def parse_equality(self):
        ln, cl = self.loc()
        left = self.parse_relational()
        while True:
            t = self.ts.peek()
            if t.t in ('==','!=','===','!=='):
                op = t.t; self.ts.next()
                right = self.parse_relational()
                left = N('Bin', line=ln, col=cl, op=op, left=left, right=right)
            else: break
        return left

    def parse_relational(self):
        ln, cl = self.loc()
        left = self.parse_shift()
        while True:
            t = self.ts.peek()
            if t.t in ('<','>','<=','>='):
                op = t.t; self.ts.next()
                right = self.parse_shift()
                left = N('Bin', line=ln, col=cl, op=op, left=left, right=right)
            elif t.t == 'KW:instanceof':
                self.ts.next()
                right = self.parse_shift()
                left = N('Bin', line=ln, col=cl, op='instanceof', left=left, right=right)
            elif t.t == 'KW:in':
                self.ts.next()
                right = self.parse_shift()
                left = N('Bin', line=ln, col=cl, op='in', left=left, right=right)
            else: break
        return left

    def parse_shift(self):
        ln, cl = self.loc()
        left = self.parse_additive()
        while True:
            t = self.ts.peek()
            if t.t in ('<<','>>','>>>'):
                op = t.t; self.ts.next()
                right = self.parse_additive()
                left = N('Bin', line=ln, col=cl, op=op, left=left, right=right)
            else: break
        return left

    def parse_additive(self):
        ln, cl = self.loc()
        left = self.parse_mult()
        while True:
            t = self.ts.peek()
            if t.t in ('+', '-'):
                op = t.t; self.ts.next()
                right = self.parse_mult()
                left = N('Bin', line=ln, col=cl, op=op, left=left, right=right)
            else: break
        return left

    def parse_mult(self):
        ln, cl = self.loc()
        left = self.parse_exponent()
        while True:
            t = self.ts.peek()
            if t.t in ('*', '/', '%'):
                op = t.t; self.ts.next()
                right = self.parse_exponent()
                left = N('Bin', line=ln, col=cl, op=op, left=left, right=right)
            else: break
        return left

    def parse_exponent(self):
        ln, cl = self.loc()
        left = self.parse_unary()
        if self.ts.match('**'):
            right = self.parse_exponent()  # right-assoc
            return N('Bin', line=ln, col=cl, op='**', left=left, right=right)
        return left

    def parse_unary(self):
        ln, cl = self.loc()
        t = self.ts.peek()
        if t.t in ('!', '~', '+', '-'):
            op = t.t; self.ts.next()
            arg = self.parse_unary()
            return N('Unary', line=ln, col=cl, op=op, arg=arg)
        if t.t == 'KW:typeof':
            self.ts.next()
            arg = self.parse_unary()
            return N('Typeof', line=ln, col=cl, arg=arg)
        if t.t == 'KW:void':
            self.ts.next()
            arg = self.parse_unary()
            return N('Void', line=ln, col=cl, arg=arg)
        if t.t == 'KW:delete':
            self.ts.next()
            arg = self.parse_unary()
            return N('Delete', line=ln, col=cl, arg=arg)
        if t.t == 'KW:await' and self._in_async:
            self.ts.next()
            arg = self.parse_unary()
            return N('Await', line=ln, col=cl, arg=arg)
        if t.t == '++':
            self.ts.next()
            arg = self.parse_unary()
            return N('Update', line=ln, col=cl, op='++', prefix=True, arg=arg)
        if t.t == '--':
            self.ts.next()
            arg = self.parse_unary()
            return N('Update', line=ln, col=cl, op='--', prefix=True, arg=arg)
        return self.parse_postfix()

    def parse_postfix(self):
        ln, cl = self.loc()
        expr = self.parse_call_expr()
        if not self.ts.nl_before_current():
            if self.ts.peek().t == '++':
                self.ts.next()
                return N('Update', line=ln, col=cl, op='++', prefix=False, arg=expr)
            if self.ts.peek().t == '--':
                self.ts.next()
                return N('Update', line=ln, col=cl, op='--', prefix=False, arg=expr)
        return expr

    def parse_call_expr(self):
        ln, cl = self.loc()

        if self.ts.is_kw('new'):
            nxt = self.ts.peek(1)
            if nxt.t != '.':
                return self.parse_new_expr()

        expr = self.parse_left_expr()

        while True:
            t = self.ts.peek()
            if t.t == '(' or (t.t == '?.' and self.ts.peek(1).t == '('):
                opt = t.t == '?.'
                if opt: self.ts.next()
                self.ts.next()  # '('
                args = self.parse_args()
                self.ts.expect(')')
                expr = N('Call', line=t.line, col=t.col, callee=expr, args=args, optional=opt)
            elif t.t == '[' or (t.t == '?.' and self.ts.peek(1).t == '['):
                opt = t.t == '?.'
                if opt: self.ts.next()
                self.ts.next()  # '['
                idx = self.parse_expr()
                self.ts.expect(']')
                expr = N('Index', line=t.line, col=t.col, obj=expr, idx=idx, optional=opt)
            elif t.t == '.':
                self.ts.next()
                name = self.ts.next().v
                expr = N('Member', line=t.line, col=t.col, obj=expr, name=name, optional=False)
            elif t.t == '?.':
                self.ts.next()
                if self.ts.peek().t in ('(', '['):
                    continue  # handled above next iteration
                name = self.ts.next().v
                expr = N('Member', line=t.line, col=t.col, obj=expr, name=name, optional=True)
            elif t.t == '`':
                # Tagged template
                parts, exprs = self.parse_template()
                expr = N('TaggedTemplate', line=t.line, col=t.col, tag=expr, parts=parts, exprs=exprs)
            else:
                break

        return expr

    def parse_new_expr(self):
        ln, cl = self.loc()
        self.ts.next()  # 'new'

        # new.target
        if self.ts.peek().t == '.':
            self.ts.next()
            self.ts.next()  # 'target'
            return N('NewTarget', line=ln, col=cl)

        callee = self.parse_left_expr_no_call()

        # Resolve further member accesses
        while True:
            t = self.ts.peek()
            if t.t == '.':
                self.ts.next()
                name = self.ts.next().v
                callee = N('Member', line=t.line, obj=callee, name=name, optional=False)
            elif t.t == '[':
                self.ts.next()
                idx = self.parse_expr()
                self.ts.expect(']')
                callee = N('Index', line=t.line, obj=callee, idx=idx, optional=False)
            else: break

        args = []
        if self.ts.peek().t == '(':
            self.ts.next()
            args = self.parse_args()
            self.ts.expect(')')

        return N('New', line=ln, col=cl, callee=callee, args=args)

    def parse_left_expr_no_call(self):
        """Parse left expression without call"""
        t = self.ts.peek()
        ln, cl = t.line, t.col

        if t.t == 'KW:new':
            nxt = self.ts.peek(1)
            if nxt.t == '.':
                self.ts.next(); self.ts.next(); self.ts.next()
                return N('NewTarget', line=ln)
            return self.parse_new_expr()

        return self.parse_primary()

    def parse_left_expr(self):
        t = self.ts.peek()
        ln, cl = t.line, t.col

        if t.t == 'KW:import':
            nxt = self.ts.peek(1)
            if nxt.t == '(':
                self.ts.next(); self.ts.next()
                src = self.parse_assign_expr()
                self.ts.expect(')')
                return N('ImportCall', line=ln, src=src)
            if nxt.t == '.':
                self.ts.next(); self.ts.next(); self.ts.next()  # import.meta
                return N('ImportMeta', line=ln)

        if t.t == 'KW:super':
            self.ts.next()
            nt = self.ts.peek()
            if nt.t == '(':
                self.ts.next()
                args = self.parse_args()
                self.ts.expect(')')
                return N('SuperCall', line=ln, args=args)
            if nt.t == '.':
                self.ts.next()
                name = self.ts.next().v
                return N('SuperMember', line=ln, name=name)
            if nt.t == '[':
                self.ts.next()
                idx = self.parse_expr()
                self.ts.expect(']')
                return N('SuperIndex', line=ln, idx=idx)
            return N('Super', line=ln)

        return self.parse_primary()

    def parse_args(self):
        args = []
        while self.ts.peek().t != ')':
            if self.ts.peek().t == '...':
                self.ts.next()
                arg = self.parse_assign_expr()
                args.append(N('Spread', arg=arg))
            else:
                args.append(self.parse_assign_expr())
            if not self.ts.match(','): break
        return args

    def parse_prop_name(self):
        t = self.ts.peek()
        if t.t in ('STR', 'NUMBER'):
            self.ts.next()
            return N('Lit', value=t.v)
        if t.t == '[':
            self.ts.next()
            e = self.parse_assign_expr()
            self.ts.expect(']')
            return N('Computed', expr=e)
        # Identifier or keyword as property name
        self.ts.next()
        return N('Ident', name=t.v)

    def parse_primary(self):
        t = self.ts.peek()
        ln, cl = t.line, t.col

        if t.t == 'KW:null': self.ts.next(); return N('Null', line=ln)
        if t.t == 'KW:true': self.ts.next(); return N('Bool', line=ln, value=True)
        if t.t == 'KW:false': self.ts.next(); return N('Bool', line=ln, value=False)
        if t.t == 'KW:undefined': self.ts.next(); return N('Undefined', line=ln)
        if t.t == 'KW:this': self.ts.next(); return N('This', line=ln)

        if t.t == 'NUMBER': self.ts.next(); return N('Num', line=ln, value=t.v)
        if t.t == 'BIGINT': self.ts.next(); return N('BigInt', line=ln, value=t.v)
        if t.t == 'STR': self.ts.next(); return N('Str', line=ln, value=t.v)

        if t.t == 'TMPL_FULL':
            self.ts.next()
            return N('Template', line=ln, parts=[t.v], exprs=[])

        if t.t == 'TMPL_HEAD':
            parts, exprs = self.parse_template_rest(t.v)
            self.ts.next()  # consume TMPL_HEAD
            return N('Template', line=ln, parts=parts, exprs=exprs)

        if t.t == 'ID':
            self.ts.next()
            return N('Ident', line=ln, col=cl, name=t.v)

        # Keywords that can be identifiers in some contexts
        if t.t.startswith('KW:') and t.t not in (
            'KW:null','KW:true','KW:false','KW:this','KW:new','KW:delete',
            'KW:typeof','KW:void','KW:return','KW:if','KW:else','KW:while',
            'KW:do','KW:for','KW:break','KW:continue','KW:switch','KW:case',
            'KW:default','KW:throw','KW:try','KW:catch','KW:finally',
            'KW:import','KW:export','KW:class','KW:extends','KW:super',
            'KW:function','KW:var','KW:let','KW:const','KW:in','KW:instanceof',
            'KW:with','KW:debugger'):
            # Can be used as identifier
            self.ts.next()
            return N('Ident', line=ln, col=cl, name=t.v)

        if t.t == '(':
            self.ts.next()
            if self.ts.peek().t == ')':
                # Arrow function with no params: () => ...
                self.ts.next()  # ')'
                if self.ts.peek().t == '=>':
                    self.ts.next()
                    body = self._parse_arrow_body(False, False)
                    return N('Arrow', line=ln, params=[], body=body, is_async=False)
                return N('Undefined', line=ln)  # shouldn't happen
            expr = self.parse_expr()
            self.ts.expect(')')
            # Check if this was arrow function params
            if self.ts.peek().t == '=>':
                self.ts.next()
                # Convert expr to params
                params = self._expr_to_params(expr)
                body = self._parse_arrow_body(False, False)
                return N('Arrow', line=ln, params=params, body=body, is_async=False)
            return N('Paren', line=ln, expr=expr)

        if t.t == '[':
            return self.parse_array_lit()

        if t.t == '{':
            return self.parse_obj_lit()

        if t.t == 'KW:function':
            return self.parse_func_expr()

        if t.t == 'KW:async' and not self.ts.nl_before_current():
            nxt = self.ts.peek(1)
            if nxt.t == 'KW:function':
                return self.parse_func_expr(async_=True)

        if t.t == 'KW:class':
            return self.parse_class_expr()

        if t.t == '/':
            # Regular expression
            return self.parse_regexp()

        if t.t == '#!':
            # Private field access
            self.ts.next()
            name = '#' + self.ts.next().v
            return N('PrivField', line=ln, name=name)

        raise SyntaxError(f"Unexpected token {t.t!r} ({t.v!r}) at line {t.line}:{t.col}")

    def _expr_to_params(self, expr):
        """Convert expression to parameter list for arrow functions"""
        if expr.t == 'SeqExpr':
            return [self._expr_to_param(e) for e in expr.exprs]
        return [self._expr_to_param(expr)]

    def _expr_to_param(self, expr):
        if expr.t == 'Ident':
            return N('Param', pattern=expr, default=None)
        if expr.t == 'Assign' and expr.op == '=':
            return N('Param', pattern=expr.left, default=expr.right)
        if expr.t == 'Spread':
            return N('RestParam', pattern=expr.arg)
        if expr.t == 'ObjLit' or expr.t == 'ArrLit':
            # Destructuring - convert
            return N('Param', pattern=self._lit_to_pattern(expr), default=None)
        return N('Param', pattern=expr, default=None)

    def _lit_to_pattern(self, expr):
        """Convert object/array literal to destructuring pattern"""
        if expr.t == 'ObjLit':
            props = []
            for p in expr.props:
                if p.t == 'Prop':
                    props.append(N('ObjPropPat', key=p.key, val=self._lit_to_pattern(p.value), default=None))
                elif p.t == 'Spread':
                    props.append(N('RestProp', pattern=p.arg))
                elif p.t == 'ShortProp':
                    props.append(N('ObjShortPat', key=p.key, default=None))
            return N('ObjPat', props=props)
        if expr.t == 'ArrLit':
            items = []
            for e in expr.items:
                if e is None: items.append(None)
                elif e.t == 'Spread': items.append(N('RestElem', pattern=e.arg))
                elif e.t == 'Assign': items.append(N('ArrPatItem', pattern=self._lit_to_pattern(e.left), default=e.right))
                else: items.append(N('ArrPatItem', pattern=self._lit_to_pattern(e), default=None))
            return N('ArrPat', items=items)
        return expr

    def parse_array_lit(self):
        ln, cl = self.loc()
        self.ts.expect('[')
        items = []
        while self.ts.peek().t != ']':
            if self.ts.peek().t == ',':
                items.append(None)
                self.ts.next()
                continue
            if self.ts.peek().t == '...':
                self.ts.next()
                items.append(N('Spread', arg=self.parse_assign_expr()))
            else:
                items.append(self.parse_assign_expr())
            if not self.ts.match(','): break
        self.ts.expect(']')
        return N('ArrLit', line=ln, col=cl, items=items)

    def parse_obj_lit(self):
        ln, cl = self.loc()
        self.ts.expect('{')
        props = []
        while self.ts.peek().t != '}':
            if self.ts.peek().t == '...':
                self.ts.next()
                props.append(N('Spread', arg=self.parse_assign_expr()))
                if not self.ts.match(','): break
                continue

            is_gen = False; is_async = False; kind = 'init'

            # Check for async
            if self.ts.peek().t == 'KW:async' and self.ts.peek(1).t not in (':', ',', '}', '('):
                self.ts.next(); is_async = True

            # Check for get/set
            if self.ts.peek().t in ('KW:get','KW:set') or (self.ts.peek().t == 'ID' and self.ts.peek().v in ('get','set')):
                nxt = self.ts.peek(1)
                if nxt.t not in ('(', ':', ',', '}', 'EOF'):
                    kind = self.ts.next().v

            # Generator
            if self.ts.peek().t == '*': self.ts.next(); is_gen = True

            key = self.parse_prop_name()

            if self.ts.peek().t == '(':
                # Method shorthand
                self.ts.next()
                params = self.parse_params()
                self.ts.expect(')')
                prev_gen, prev_async = self._in_generator, self._in_async
                self._in_func += 1
                self._in_generator = 1 if is_gen else 0
                self._in_async = 1 if is_async else 0
                body = self.parse_block()
                self._in_func -= 1
                self._in_generator = prev_gen
                self._in_async = prev_async
                func = N('Func', params=params, body=body, is_gen=is_gen, is_async=is_async)
                props.append(N('MethodProp', key=key, func=func, kind=kind))
            elif self.ts.match(':'):
                val = self.parse_assign_expr()
                props.append(N('Prop', key=key, value=val, kind=kind))
            else:
                # Shorthand
                props.append(N('ShortProp', key=key))

            if not self.ts.match(','): break
        self.ts.expect('}')
        return N('ObjLit', line=ln, col=cl, props=props)

    def parse_func_expr(self, async_=False):
        ln, cl = self.loc()
        if async_: self.ts.next()
        self.ts.next()  # 'function'
        is_gen = bool(self.ts.match('*'))
        name = None
        if self.ts.peek().t == 'ID' or (self.ts.peek().t.startswith('KW:') and 
           self.ts.peek().t not in ('KW:null','KW:true','KW:false')):
            name = self.ts.next().v
        func = self.parse_func_rest(name, is_gen, async_)
        func.line = ln
        return func

    def parse_class_expr(self):
        ln, cl = self.loc()
        self.ts.next()  # 'class'
        name = None
        if self.ts.peek().t == 'ID': name = self.ts.next().v
        superclass = None
        if self.ts.match_kw('extends'):
            superclass = self.parse_left_expr()
        self.ts.expect('{')
        methods = []
        self._in_class += 1
        while self.ts.peek().t != '}':
            if self.ts.peek().t == ';': self.ts.next(); continue
            m = self.parse_class_member()
            if m: methods.append(m)
        self._in_class -= 1
        self.ts.expect('}')
        return N('ClassExpr', line=ln, name=name, superclass=superclass, methods=methods)

    def parse_regexp(self):
        ln, cl = self.loc()
        # Re-lex as regexp from current position
        src = self.ts.toks[self.ts.pos - 1]  # the '/'
        # Actually we need to re-lex starting from the position of '/'
        # Get the raw source position and re-lex
        # This is complex - for now, consume as div operator
        self.ts.next()  # skip '/'
        # Try to read pattern manually from remaining tokens
        # This is a limitation of our approach
        pattern = ''
        flags = ''
        # Simple heuristic: collect until next /
        while self.ts.peek().t not in ('EOF', 'NL') and self.ts.peek().t != '/':
            pattern += str(self.ts.peek().v or self.ts.peek().t)
            self.ts.next()
        if self.ts.peek().t == '/':
            self.ts.next()
            if self.ts.peek().t == 'ID':
                flags = self.ts.next().v
        return N('Regexp', line=ln, pattern=pattern, flags=flags)

    def parse_template(self):
        """Parse template literal parts and expressions"""
        parts = []
        exprs = []
        t = self.ts.peek()
        if t.t == 'TMPL_FULL':
            self.ts.next()
            parts.append(t.v)
            return parts, exprs
        if t.t == 'TMPL_HEAD':
            parts.append(t.v)
            self.ts.next()
            while True:
                exprs.append(self.parse_expr())
                # After expression, expect TMPL_MIDDLE or TMPL_TAIL
                nt = self.ts.peek()
                if nt.t in ('TMPL_FULL', 'TMPL_HEAD'):
                    # Continuation
                    parts.append(nt.v)
                    if nt.t == 'TMPL_FULL': self.ts.next(); break
                    self.ts.next()
                else:
                    parts.append('')
                    break
        return parts, exprs

    def parse_template_rest(self, head_val):
        parts = [head_val]
        exprs = []
        # The TMPL_HEAD is already consumed (we peeked at it)
        # Actually we haven't consumed it yet
        # This is called before consuming the token
        # Consume TMPL_HEAD
        # ... complex template parsing
        return parts, exprs

