    if isinstance(b,bool): return _eq(a, 1.0 if b else 0.0)
    if _is_num(a) and isinstance(b,str): return _eq(a, _to_num(b))
    if isinstance(a,str) and _is_num(b): return _eq(_to_num(a), b)
    if isinstance(a,BigInt) and isinstance(b,str):
