    if cl=='Promise': return 'Promise {  }'
    if cl=='Map' and hasattr(v,'_map'):
        items=v._map
        if not items: return 'Map(0) {}'
        p=[f'{_inspect(k,depth+1,seen,True)} => {_inspect(u,depth+1,seen,True)}' for k,u in items]
        return f'Map({len(items)}) ' + '{ '+', '.join(p)+' }'
    if cl=='Set' and hasattr(v,'_set'):
        items=v._set
        if not items: return 'Set(0) {}'
        p=[_inspect(x,depth+1,seen,True) for x in items]
        return f'Set({len(items)}) ' + '{ '+', '.join(p)+' }'
    if cl in ('WeakMap','WeakSet','WeakRef'): return f'{cl} {{  }}'
    if cl in ('ArrayBuffer','SharedArrayBuffer','DataView'): return f'{cl} {{  }}'
    if cl=='Proxy': return 'Object {  }'
    if cl in ('Uint8Array','Int8Array','Uint16Array','Int16Array','Uint32Array','Int32Array',
