    if isinstance(v,bool): return 1.0 if v else 0.0
    if v is null: return 0.0
    if v is undefined: return float('nan')
    if _is_num(v): return float(v)
    if isinstance(v,BigInt): raise JSThrow(_mk_err('TypeError','Cannot convert BigInt to number'))
    if isinstance(v,str):
        s=v.strip()
        if not s: return 0.0
        if s in ('Infinity','+Infinity'): return float('inf')
        if s=='-Infinity': return float('-inf')
        try:
            if s.startswith(('0x','0X')): return float(int(s,16))
            if s.startswith(('0o','0O')): return float(int(s,8))
            if s.startswith(('0b','0B')): return float(int(s,2))
            return float(s)
        except: return float('nan')
    if _is_obj(v): return _to_num(_to_prim(v,'number'))
    return float('nan')

def _to_int32(v):
    n = _to_num(v)
    if math.isnan(n) or math.isinf(n) or n==0: return 0
    i = int(n) & 0xFFFFFFFF
    return i - 0x100000000 if i >= 0x80000000 else i

def _to_uint32(v):
    n = _to_num(v)
    if math.isnan(n) or math.isinf(n) or n==0: return 0
    return int(n) & 0xFFFFFFFF

def _to_uint16(v): return _to_uint32(v) & 0xFFFF

def _to_str(v):
    if isinstance(v,bool): return 'true' if v else 'false'
    if v is null: return 'null'
    if v is undefined: return 'undefined'
    if isinstance(v,str): return v
    if _is_num(v): return _js_num_str(float(v))
    if isinstance(v,BigInt): return str(v.v)
    if isinstance(v,Symbol): raise JSThrow(_mk_err('TypeError','Cannot convert Symbol to string'))
    if _is_obj(v): return _to_str(_to_prim(v,'string'))
    return str(v)

