    if isinstance(v,bool):
        o = JSObj(g_boolean_proto); o._cls = 'Boolean'; o._pval = v; return o
    if _is_num(v):
        o = JSObj(g_number_proto); o._cls = 'Number'; o._pval = float(v); return o
    if isinstance(v,str):
        o = JSObj(g_string_proto); o._cls = 'String'; o._pval = v; return o
    if isinstance(v,Symbol):
        o = JSObj(g_symbol_proto); o._cls = 'Symbol'; o._pval = v; return o
    if isinstance(v,BigInt):
