    px,py = _to_prim(a,'number'), _to_prim(b,'number')
    if isinstance(px,str) and isinstance(py,str): return px<py
    if isinstance(px,BigInt) and isinstance(py,BigInt): return px.v<py.v
    if isinstance(px,BigInt) and _is_num(py):
        if math.isnan(py): return undefined
        return float(px.v)<py
    if _is_num(px) and isinstance(py,BigInt):
        if math.isnan(px): return undefined
        return px<float(py.v)
    nx,ny=_to_num(px),_to_num(py)
    if math.isnan(nx) or math.isnan(ny): return undefined
    return nx<ny

