    return _inspect_plain(v,depth,seen)

def _inspect_plain(v, depth, seen):
    parts=[]
    for k,d in v._p.items():
        if not d.get('e',True): continue
        if isinstance(k,Symbol):
            desc=k.description or ''
            if 'get' in d:
                hs=d.get('set') is not undefined and d.get('set') is not None
                parts.append(f'{desc}: [Getter/Setter]' if hs else f'{desc}: [Getter]')
            else:
                parts.append(f'{desc}: {_inspect(d.get("v",undefined),depth+1,seen,True)}')
