        if not isinstance(k,str): continue
        ks=_fmtk(k)
        if 'get' in d:
            hs=d.get('set') is not undefined and d.get('set') is not None
            parts.append(f'{ks}: [Getter/Setter]' if hs else f'{ks}: [Getter]')
        else:
            parts.append(f'{ks}: {_inspect(d.get("v",undefined),depth+1,seen,True)}')
