    def __new__(cls):
        if not cls._i: cls._i = super().__new__(cls)
        return cls._i
    def __repr__(self): return 'null'
    def __bool__(self): return False

undefined = _Undef()
null = _Null()
_HOLE = object()

class Symbol:
    _cnt = 0; _reg = {}
    def __init__(self, d=None, k=None):
        Symbol._cnt += 1; self._id = Symbol._cnt; self.description = d; self._k = k
    def __repr__(self): return f'Symbol({self.description})' if self.description is not None else 'Symbol()'
    def __hash__(self): return self._id
    def __eq__(self, o): return self is o
    def __str__(self): return repr(self)

sym_iterator = Symbol('Symbol.iterator')
sym_asyncIterator = Symbol('Symbol.asyncIterator')
sym_hasInstance = Symbol('Symbol.hasInstance')
sym_toPrimitive = Symbol('Symbol.toPrimitive')
sym_toStringTag = Symbol('Symbol.toStringTag')
sym_species = Symbol('Symbol.species')
sym_isConcatSpreadable = Symbol('Symbol.isConcatSpreadable')
sym_unscopables = Symbol('Symbol.unscopables')

class BigInt:
    def __init__(self, v): self.v = int(v) if not isinstance(v, BigInt) else v.v
    def __repr__(self): return f'{self.v}n'
    def __str__(self): return repr(self)
    def __bool__(self): return bool(self.v)
    def __hash__(self): return hash(self.v)
    def __eq__(self, o):
        if isinstance(o, BigInt): return self.v == o.v
        if isinstance(o, (int,float)) and not isinstance(o, bool): return self.v == o
        return False
    def __lt__(self, o): return self.v < (o.v if isinstance(o,BigInt) else o)
    def __le__(self, o): return self.v <= (o.v if isinstance(o,BigInt) else o)
    def __gt__(self, o): return self.v > (o.v if isinstance(o,BigInt) else o)
    def __ge__(self, o): return self.v >= (o.v if isinstance(o,BigInt) else o)
    def __add__(self, o): return BigInt(self.v + (o.v if isinstance(o,BigInt) else _err('bigint')))
    def __sub__(self, o): return BigInt(self.v - (o.v if isinstance(o,BigInt) else _err('bigint')))
    def __mul__(self, o): return BigInt(self.v * (o.v if isinstance(o,BigInt) else _err('bigint')))
    def __floordiv__(self, o): 
        if isinstance(o,BigInt): return BigInt(int(self.v/o.v))
        _err('bigint')
    def __mod__(self, o): return BigInt(self.v % (o.v if isinstance(o,BigInt) else _err('bigint')))
    def __pow__(self, o): return BigInt(self.v ** (o.v if isinstance(o,BigInt) else _err('bigint')))
    def __neg__(self): return BigInt(-self.v)
    def __and__(self, o): return BigInt(self.v & (o.v if isinstance(o,BigInt) else _err('bigint')))
    def __or__(self, o): return BigInt(self.v | (o.v if isinstance(o,BigInt) else _err('bigint')))
    def __xor__(self, o): return BigInt(self.v ^ (o.v if isinstance(o,BigInt) else _err('bigint')))
    def __lshift__(self, o): return BigInt(self.v << (o.v if isinstance(o,BigInt) else _err('bigint')))
    def __rshift__(self, o): return BigInt(self.v >> (o.v if isinstance(o,BigInt) else _err('bigint')))
    def __invert__(self): return BigInt(~self.v)
    def __int__(self): return self.v
    def __float__(self): return float(self.v)
    def __abs__(self): return BigInt(abs(self.v))

def _err(t): raise JSThrow(_mk_err('TypeError', f'Cannot mix BigInt and other types'))

# ===== Exceptions =====
class JSThrow(Exception):
    def __init__(self, v): self.v = v; super().__init__(repr(v))
class JSReturn(Exception):
    def __init__(self, v): self.v = v
class JSBreak(Exception):
    def __init__(self, l=None): self.label = l
class JSContinue(Exception):
    def __init__(self, l=None): self.label = l

# ===== JSObject =====
class JSObj:
    def __init__(self, proto=None):
        self.__dict__['_p'] = {}  # props
        self.__dict__['_proto'] = proto
        self.__dict__['_ext'] = True
        self.__dict__['_cls'] = 'Object'
        self.__dict__['_call'] = None
        self.__dict__['_ctor'] = None
        self.__dict__['_name'] = ''
        self.__dict__['_len'] = 0
        self.__dict__['_is_arrow'] = False
        self.__dict__['_is_gen'] = False
        self.__dict__['_is_async'] = False
        self.__dict__['_pval'] = None  # primitive value wrapper
        self.__dict__['_opaque'] = None

    def _get_own(self, k):
        return self._p.get(k)

    def _get(self, k, recv=None):
        if recv is None: recv = self
        cur = self
        while cur is not None:
            d = cur._p.get(k)
            if d is not None:
                if 'get' in d:
                    g = d['get']
                    if g is None or g is undefined: return undefined
                    return _call(g, recv, [])
                return d.get('v', undefined)
            cur = cur._proto
        return undefined

    def _set(self, k, v, recv=None, strict=False):
        if recv is None: recv = self
        cur = self
        while cur is not None:
            d = cur._p.get(k)
            if d is not None:
                if 'set' in d:
                    s = d['set']
                    if s is None or s is undefined:
                        if strict: raise JSThrow(_mk_err('TypeError', f"Cannot set property '{k}'"))
                        return
                    _call(s, recv, [v]); return
                if not d.get('w', True):
                    if strict: raise JSThrow(_mk_err('TypeError', f"Cannot assign to read only property '{k}'"))
                    return
                break
            cur = cur._proto
        if isinstance(recv, JSObj):
            if not recv._ext and k not in recv._p:
                if strict: raise JSThrow(_mk_err('TypeError', f"Cannot add property '{k}'"))
                return
            if k in recv._p:
                d = recv._p[k]
                if not d.get('w', True):
                    if strict: raise JSThrow(_mk_err('TypeError', f"Cannot assign to read only"))
                    return
                if 'v' in d: d['v'] = v; return
            recv._p[k] = {'v': v, 'w': True, 'e': True, 'c': True}

    def _has(self, k):
        c = self
        while c is not None:
            if k in c._p: return True
            c = c._proto
        return False

    def _has_own(self, k): return k in self._p

    def _del(self, k, strict=False):
        if k not in self._p: return True
        if not self._p[k].get('c', True):
            if strict: raise JSThrow(_mk_err('TypeError', f"Cannot delete property '{k}'"))
            return False
        del self._p[k]; return True

    def _def(self, k, d, strict=False):
        ex = self._p.get(k)
        if ex is None:
            if not self._ext:
                if strict: raise JSThrow(_mk_err('TypeError', f"Cannot define '{k}'"))
                return False
            self._p[k] = d; return True
        if not ex.get('c', True):
            if 'v' in d and 'v' in ex and ex.get('w', False): ex['v'] = d['v']; return True
            if strict: raise JSThrow(_mk_err('TypeError', f"Cannot redefine '{k}'"))
            return False
        ex.update(d); return True

    def _enum_keys(self):
        r = []; seen = set()
        c = self
        while c is not None:
            for k in c._p:
                if isinstance(k, str) and k not in seen:
                    seen.add(k)
                    if c._p[k].get('e', True): r.append(k)
            c = c._proto
        return r

    def _own_enum_keys(self):
        return [k for k in self._p if isinstance(k, str) and self._p[k].get('e', True)]

class JSArr(JSObj):
    def __init__(self, proto=None):
        super().__init__(proto)
        self.__dict__['_cls'] = 'Array'
        self.__dict__['_items'] = []
        self.__dict__['_len'] = 0

    def _get(self, k, recv=None):
        if recv is None: recv = self
        if k == 'length': return self._len
        if isinstance(k, str):
            try:
                i = int(k)
                if i >= 0 and str(i) == k:
                    if i < len(self._items):
                        v = self._items[i]
                        return undefined if v is _HOLE else v
                    return undefined
            except (ValueError, OverflowError): pass
        return super()._get(k, recv)

    def _set(self, k, v, recv=None, strict=False):
        if recv is None: recv = self
        if k == 'length':
            nl = _to_uint32(v)
            if nl < len(self._items): self._items = self._items[:nl]
            self._len = nl; return
        if isinstance(k, str):
            try:
                i = int(k)
                if i >= 0 and str(i) == k: self._arr_set(i, v); return
            except (ValueError, OverflowError): pass
        super()._set(k, v, recv, strict)

    def _arr_set(self, i, v):
        if i >= len(self._items):
            self._items.extend([_HOLE]*(i-len(self._items)+1))
        self._items[i] = v
        if i >= self._len: self._len = i+1

    def _has_own(self, k):
        if k == 'length': return True
        if isinstance(k, str):
            try:
                i = int(k)
                if i >= 0 and str(i) == k:
                    return i < len(self._items) and self._items[i] is not _HOLE
            except (ValueError, OverflowError): pass
        return super()._has_own(k)

    def _own_enum_keys(self):
        r = [str(i) for i in range(len(self._items)) if i < self._len and self._items[i] is not _HOLE]
        r.extend(super()._own_enum_keys())
        return r

# ===== Type conversions =====
def _is_num(v): return isinstance(v, (int,float)) and not isinstance(v,bool)
def _is_obj(v): return isinstance(v, JSObj)
def _callable(v): return _is_obj(v) and v._call is not None

def _to_prim(v, hint='default'):
    if not _is_obj(v): return v
    tp = None
    c = v
    while c:
        if sym_toPrimitive in c._p: tp = c._p[sym_toPrimitive].get('v'); break
        c = c._proto
    if tp is not None and _callable(tp):
        r = _call(tp, v, [hint])
        if not _is_obj(r): return r
        raise JSThrow(_mk_err('TypeError','Cannot convert object to primitive'))
    if hint == 'string':
        for m in ('toString','valueOf'):
            fn = v._get(m)
            if _callable(fn):
                r = _call(fn, v, [])
                if not _is_obj(r): return r
    else:
        for m in ('valueOf','toString'):
            fn = v._get(m)
            if _callable(fn):
                r = _call(fn, v, [])
                if not _is_obj(r): return r
    raise JSThrow(_mk_err('TypeError','Cannot convert object to primitive'))

def _to_num(v):
    if isinstance(v,bool): return 1.0 if v else 0.0
    if v is null: return 0.0
    if v is undefined: return float('nan')
    if _is_num(v): return float(v)
    if isinstance(v,BigInt): raise JSThrow(_mk_err('TypeError','Cannot convert BigInt to number'))
    if isinstance(v,str):
        s=v.strip()
        if not s: return 0.0
        if s in ('Infinity','+Infinity'): return float('inf')
        if s=='-Infinity': return float('-inf')
        try:
            if s.startswith(('0x','0X')): return float(int(s,16))
            if s.startswith(('0o','0O')): return float(int(s,8))
            if s.startswith(('0b','0B')): return float(int(s,2))
            return float(s)
        except: return float('nan')
    if _is_obj(v): return _to_num(_to_prim(v,'number'))
    return float('nan')

def _to_int32(v):
    n = _to_num(v)
    if math.isnan(n) or math.isinf(n) or n==0: return 0
    i = int(n) & 0xFFFFFFFF
    return i - 0x100000000 if i >= 0x80000000 else i

def _to_uint32(v):
    n = _to_num(v)
    if math.isnan(n) or math.isinf(n) or n==0: return 0
    return int(n) & 0xFFFFFFFF

def _to_uint16(v): return _to_uint32(v) & 0xFFFF

def _to_str(v):
    if isinstance(v,bool): return 'true' if v else 'false'
    if v is null: return 'null'
    if v is undefined: return 'undefined'
    if isinstance(v,str): return v
    if _is_num(v): return _js_num_str(float(v))
    if isinstance(v,BigInt): return str(v.v)
    if isinstance(v,Symbol): raise JSThrow(_mk_err('TypeError','Cannot convert Symbol to string'))
    if _is_obj(v): return _to_str(_to_prim(v,'string'))
    return str(v)

def _to_bool(v):
    if isinstance(v,bool): return v
    if v is null or v is undefined: return False
    if _is_num(v): return v != 0 and not math.isnan(v)
    if isinstance(v,str): return len(v) > 0
    if isinstance(v,BigInt): return v.v != 0
    if _is_obj(v): return True
    return bool(v)

def _to_obj(v):
    if v is null: raise JSThrow(_mk_err('TypeError','Cannot convert null to object'))
    if v is undefined: raise JSThrow(_mk_err('TypeError','Cannot convert undefined to object'))
    if _is_obj(v): return v
    # Wrap
    if isinstance(v,bool):
        o = JSObj(g_boolean_proto); o._cls = 'Boolean'; o._pval = v; return o
    if _is_num(v):
        o = JSObj(g_number_proto); o._cls = 'Number'; o._pval = float(v); return o
    if isinstance(v,str):
        o = JSObj(g_string_proto); o._cls = 'String'; o._pval = v; return o
    if isinstance(v,Symbol):
        o = JSObj(g_symbol_proto); o._cls = 'Symbol'; o._pval = v; return o
    if isinstance(v,BigInt):
        o = JSObj(g_bigint_proto); o._cls = 'BigInt'; o._pval = v; return o
    return v

# ===== Equality =====
def _eq(a, b):
    if (a is null and b is undefined) or (a is undefined and b is null): return True
    if a is null or b is null or a is undefined or b is undefined: return False
    if isinstance(a,bool) and isinstance(b,bool): return a==b
    if _is_num(a) and _is_num(b): 
        fa,fb=float(a),float(b)
        if math.isnan(fa) or math.isnan(fb): return False
        return fa==fb
    if isinstance(a,str) and isinstance(b,str): return a==b
    if isinstance(a,Symbol) and isinstance(b,Symbol): return a is b
    if isinstance(a,BigInt) and isinstance(b,BigInt): return a.v==b.v
    if _is_obj(a) and _is_obj(b): return a is b
    if isinstance(a,bool): return _eq(1.0 if a else 0.0, b)
    if isinstance(b,bool): return _eq(a, 1.0 if b else 0.0)
    if _is_num(a) and isinstance(b,str): return _eq(a, _to_num(b))
    if isinstance(a,str) and _is_num(b): return _eq(_to_num(a), b)
    if isinstance(a,BigInt) and isinstance(b,str):
        try: return a.v==int(b)
        except: return False
    if isinstance(b,BigInt) and isinstance(a,str):
        try: return int(a)==b.v
        except: return False
    if isinstance(a,BigInt) and _is_num(b):
        if math.isnan(b) or math.isinf(b): return False
        return a.v==b
    if _is_num(a) and isinstance(b,BigInt):
        if math.isnan(a) or math.isinf(a): return False
        return a==b.v
    if _is_obj(a) and not _is_obj(b) and not isinstance(b,bool): return _eq(_to_prim(a),b)
    if _is_obj(b) and not _is_obj(a) and not isinstance(a,bool): return _eq(a,_to_prim(b))
    return False

def _seq(a, b):
    if a is null and b is null: return True
    if a is undefined and b is undefined: return True
    if isinstance(a,bool) and isinstance(b,bool): return a==b
    if _is_num(a) and _is_num(b):
        fa,fb=float(a),float(b)
        if math.isnan(fa) or math.isnan(fb): return False
        return fa==fb
    if isinstance(a,str) and isinstance(b,str): return a==b
    if isinstance(a,Symbol) and isinstance(b,Symbol): return a is b
    if isinstance(a,BigInt) and isinstance(b,BigInt): return a.v==b.v
    if _is_obj(a) and _is_obj(b): return a is b
    return False

def _lt(a, b):
    px,py = _to_prim(a,'number'), _to_prim(b,'number')
    if isinstance(px,str) and isinstance(py,str): return px<py
    if isinstance(px,BigInt) and isinstance(py,BigInt): return px.v<py.v
    if isinstance(px,BigInt) and _is_num(py):
        if math.isnan(py): return undefined
        return float(px.v)<py
    if _is_num(px) and isinstance(py,BigInt):
        if math.isnan(px): return undefined
        return px<float(py.v)
    nx,ny=_to_num(px),_to_num(py)
    if math.isnan(nx) or math.isnan(ny): return undefined
    return nx<ny

# ===== Inspect =====
def _inspect(v, depth=0, seen=None, in_obj=False):
    if seen is None: seen={}
    if isinstance(v,bool): return 'true' if v else 'false'
    if v is null: return 'null'
    if v is undefined: return 'undefined'
    if _is_num(v): return _inspect_num(float(v))
    if isinstance(v,str): return json.dumps(v) if in_obj else v
    if isinstance(v,BigInt): return f'{v.v}n'
    if isinstance(v,Symbol): return repr(v)
    if not _is_obj(v): return repr(v)
    oid=id(v)
    if oid in seen:
        return '[Array]' if isinstance(v,JSArr) else '[circular 0]'
    if depth>=2: return '[Array]' if isinstance(v,JSArr) else '[Object]'
    seen2={**seen,oid:1}
    return _inspect_obj(v, depth, seen2)

def _inspect_obj(v, depth, seen):
    cl = v._cls
    if v._call: nm=v._name or ''; return f'[Function {nm}]' if nm else '[Function (anonymous)]'
    if _is_err(v): return _inspect_err(v, depth, seen)
    if cl=='RegExp' and hasattr(v,'_pattern'): return f'/{v._pattern}/{v._flags}'
    if cl=='Date' and hasattr(v,'_ms'):
        import datetime
        ms=v._ms
        if math.isnan(ms): return 'Invalid Date'
        try:
            dt=datetime.datetime(1970,1,1)+datetime.timedelta(milliseconds=ms)
            return dt.strftime(f'%Y-%m-%dT%H:%M:%S.{int(ms%1000):03d}Z')
        except: return 'Invalid Date'
    if cl=='Generator': return 'Generator {  }'
    if cl=='Promise': return 'Promise {  }'
    if cl=='Map' and hasattr(v,'_map'):
        items=v._map
        if not items: return 'Map(0) {}'
        p=[f'{_inspect(k,depth+1,seen,True)} => {_inspect(u,depth+1,seen,True)}' for k,u in items]
        return f'Map({len(items)}) ' + '{ '+', '.join(p)+' }'
    if cl=='Set' and hasattr(v,'_set'):
        items=v._set
        if not items: return 'Set(0) {}'
        p=[_inspect(x,depth+1,seen,True) for x in items]
        return f'Set({len(items)}) ' + '{ '+', '.join(p)+' }'
    if cl in ('WeakMap','WeakSet','WeakRef'): return f'{cl} {{  }}'
    if cl in ('ArrayBuffer','SharedArrayBuffer','DataView'): return f'{cl} {{  }}'
    if cl=='Proxy': return 'Object {  }'
    if cl in ('Uint8Array','Int8Array','Uint16Array','Int16Array','Uint32Array','Int32Array',
              'Float32Array','Float64Array','BigInt64Array','BigUint64Array','Uint8ClampedArray'):
        if hasattr(v,'_items'):
            n=len(v._items)
            if n==0: return f'{cl}(0) []'
            p=[_inspect(x,depth+1,seen,True) for x in v._items]
            return f'{cl}({n}) [ '+', '.join(p)+' ]'
        return f'{cl}(0) []'
    if isinstance(v,JSArr): return _inspect_arr(v,depth,seen)
    return _inspect_plain(v,depth,seen)

def _inspect_plain(v, depth, seen):
    parts=[]
    for k,d in v._p.items():
        if not d.get('e',True): continue
        if isinstance(k,Symbol):
            desc=k.description or ''
            if 'get' in d:
                hs=d.get('set') is not undefined and d.get('set') is not None
                parts.append(f'{desc}: [Getter/Setter]' if hs else f'{desc}: [Getter]')
            else:
                parts.append(f'{desc}: {_inspect(d.get("v",undefined),depth+1,seen,True)}')
            continue
        if not isinstance(k,str): continue
        ks=_fmtk(k)
        if 'get' in d:
            hs=d.get('set') is not undefined and d.get('set') is not None
            parts.append(f'{ks}: [Getter/Setter]' if hs else f'{ks}: [Getter]')
        else:
            parts.append(f'{ks}: {_inspect(d.get("v",undefined),depth+1,seen,True)}')
    if not parts: return '{  }'
    return '{ '+', '.join(parts)+' }'

def _inspect_arr(v, depth, seen):
    sparse=any(x is _HOLE for x in v._items)
    extras=[(k,d) for k,d in v._p.items() if isinstance(k,str) and not k.isdigit() and d.get('e',True)]
    if sparse:
        parts=[]
        for i in range(min(len(v._items),v._len)):
            if v._items[i] is not _HOLE:
                parts.append(f'{i}: {_inspect(v._items[i],depth+1,seen,True)}')
        for k,d in extras:
            parts.append(f'{_fmtk(k)}: {_inspect(d.get("v",undefined),depth+1,seen,True)}')
        return ('[  ]' if not parts else '[ '+', '.join(parts)+' ]')
    parts=[_inspect(v._items[i] if i<len(v._items) else undefined,depth+1,seen,True) for i in range(v._len)]
    for k,d in extras:
        parts.append(f'{_fmtk(k)}: {_inspect(d.get("v",undefined),depth+1,seen,True)}')
    return '[  ]' if not parts else '[ '+', '.join(parts)+' ]'

def _inspect_err(v, depth, seen):
    nm = v._p.get('name',{}).get('v','Error')
    if not isinstance(nm,str): nm='Error'
    msg = v._p.get('message',{}).get('v','')
    if not isinstance(msg,str): msg=''
    stk = v._p.get('stack',{}).get('v')
    if isinstance(stk,str): r=stk.rstrip('\n')
    elif msg: r=f'{nm}: {msg}'
    else: r=nm
    extra=[]
    for k,d in v._p.items():
        if isinstance(k,str) and k not in ('name','message','stack') and d.get('e',True):
            extra.append(f'{_fmtk(k)}: {_inspect(d.get("v",undefined),depth+1,seen,True)}')
    if extra: r += ' { '+', '.join(extra)+' }'
    return r

def _is_err(v):
    if not _is_obj(v): return False
    if v._cls=='Error': return True
    p=v._proto
    while p:
        if p._cls=='Error': return True
        p=p._proto
    return False

def _fmtk(k):
    if isinstance(k,Symbol): return k.description or ''
    if isinstance(k,str):
        if re.match(r'^[a-zA-Z_$][a-zA-Z0-9_$]*$',k) or re.match(r'^\d+$',k): return k
        return json.dumps(k)
    return str(k)

# ===== Error helpers =====
def _mk_err(t, msg=''):
    proto = g_err_protos.get(t, g_err_proto)
    o = JSObj(proto); o._cls='Error'
    o._p['name'] = {'v':t,'w':True,'e':False,'c':True}
    if msg: o._p['message'] = {'v':msg,'w':True,'e':False,'c':True}
    return o

def _mk_err_stack(t, msg, frames):
    o = _mk_err(t, msg)
    if frames:
        parts=[f'{t}: {msg}' if msg else t]
        for f in frames:
            fn=f.get('f','<anonymous>'); fi=f.get('i','<unknown>'); ln=f.get('l',0); cl=f.get('c',0)
            parts.append(f'    at {fn} ({fi}:{ln}:{cl})')
        parts.append('')
        o._p['stack']={'v':'\n'.join(parts),'w':True,'e':False,'c':True}
    return o

# ===== Global state =====
g_object_proto = None
g_function_proto = None
