def _js_num_str(n):
    if math.isnan(n): return 'NaN'
    if math.isinf(n): return 'Infinity' if n > 0 else '-Infinity'
    if n == 0: return '0'
    neg = n < 0
    if neg: n = -n
    if n == int(n) and n < 1e21:
        r = str(int(n))
        return ('-'+r) if neg else r
    s = None
    for p in range(1,22):
        c = format(n, f'.{p}g')
        try:
            if float(c) == n: s = c; break
        except: pass
    if s is None: s = repr(n)
    if 'e' in s:
        m, e = s.split('e'); ei = int(e)
        ip, fp = m.split('.') if '.' in m else (m, '')
        if ei >= -6 and ei < 21:
            d = ip + fp
            ap = len(ip) + ei
            if ap <= 0: r = '0.' + '0'*(-ap) + d
            elif ap >= len(d): r = d + '0'*(ap - len(d))
            else: r = d[:ap] + '.' + d[ap:]
            if '.' in r: r = r.rstrip('0').rstrip('.')
        else:
