            mn = d[0] + ('.'+d[1:] if len(d)>1 else '')
            r = f"{mn}e+{ei}" if ei>=0 else f"{mn}e{ei}"
    else:
        r = s
        if '.' in r: r = r.rstrip('0').rstrip('.')
    return ('-'+r) if neg else r

