    if _is_num(v): return float(v)
    if isinstance(v,BigInt): raise JSThrow(_mk_err('TypeError','Cannot convert BigInt to number'))
    if isinstance(v,str):
        s=v.strip()
        if not s: return 0.0
        if s in ('Infinity','+Infinity'): return float('inf')
        if s=='-Infinity': return float('-inf')
        try:
            if s.startswith(('0x','0X')): return float(int(s,16))
            if s.startswith(('0o','0O')): return float(int(s,8))
            if s.startswith(('0b','0B')): return float(int(s,2))
            return float(s)
        except: return float('nan')
    if _is_obj(v): return _to_num(_to_prim(v,'number'))
    return float('nan')

