_call_depth = 0
MAX_DEPTH = 500

def _call(fn, this, args, new_target=None):
    global _call_depth
    if not _is_obj(fn) or fn._call is None:
        nm = fn._name if _is_obj(fn) and fn._name else ''
        raise JSThrow(_mk_err('TypeError', f"{'not a function' if not nm else repr(nm)+' is not a function'}"))
    _call_depth += 1
    if _call_depth > MAX_DEPTH:
        _call_depth -= 1
        raise JSThrow(_mk_err('RangeError','Maximum call stack size exceeded'))
    try:
        r = fn._call(this, args, new_target)
        return undefined if r is None else r
    except JSReturn as e:
        return e.value
    finally:
        _call_depth -= 1

def _construct(fn, args, nt=None):
    if not _is_obj(fn): raise JSThrow(_mk_err('TypeError','not a constructor'))
    if nt is None: nt = fn
    if fn._ctor:
        return fn._ctor(args, nt)
    if fn._call and not fn._is_arrow and not fn._is_gen:
        pv = fn._get('prototype')
        if not _is_obj(pv): pv = g_object_proto
        o = JSObj(pv)
        r = _call(fn, o, args, nt)
        return r if _is_obj(r) else o
    raise JSThrow(_mk_err('TypeError', f"'{fn._name or ''}' is not a constructor"))

# ===== Scope =====
class Scope:
    def __init__(self, parent=None, strict=False):
        self.vars = {}
        self.parent = parent
        self._strict = strict
        self.this_val = None

    def get(self, name):
        s = self
        while s:
            if name in s.vars:
                v = s.vars[name]
                if v is _UNINIT:
                    raise JSThrow(_mk_err('ReferenceError',f"Cannot access '{name}' before initialization"))
                return v
            s = s.parent
        if g_global:
            v = g_global._get(name)
            if v is not undefined: return v
        raise JSThrow(_mk_err('ReferenceError',f"'{name}' is not defined"))

    def set(self, name, val):
        s = self
        while s:
            if name in s.vars:
                s.vars[name] = val; return
            s = s.parent
        if self.strict():
            raise JSThrow(_mk_err('ReferenceError',f"'{name}' is not defined"))
        if g_global: g_global._set(name, val)

    def def_v(self, n, v=undefined): self.vars[n] = v
    def def_l(self, n, v=_UNINIT): self.vars[n] = v
    def has_own(self, n): return n in self.vars
    def strict(self):
        s = self
        while s:
            if s._strict: return True
            s = s.parent
        return False
    def get_this(self):
        s = self
        while s:
            if s.this_val is not None: return s.this_val
            s = s.parent
        return g_global or undefined

_UNINIT = object()

# ===== Built-in function helper =====
def _mkfn(fn, name='', length=0, proto=None):
    o = JSObj(g_function_proto or None)
    o._cls = 'Function'
    o._call = fn
    o._name = name
    o._len = length
    o._is_arrow = True  # no prototype property
    return o

def _mkctor(fn, ctor=None, name='', length=0):
    o = JSObj(g_function_proto or None)
    o._cls = 'Function'
    o._call = fn
    o._ctor = ctor or fn
    o._name = name
    o._len = length
    p = JSObj(g_object_proto)
    p._p['constructor'] = {'v':o,'w':True,'e':False,'c':True}
    o._p['prototype'] = {'v':p,'w':False,'e':False,'c':False}
    return o

def _setprop(o, k, v, w=True, e=True, c=True):
    o._p[k] = {'v':v,'w':w,'e':e,'c':c}

def _setget(o, k, get=None, set=None, e=False, c=True):
    d = {}
    if get is not None: d['get'] = get
    if set is not None: d['set'] = set
    d['e'] = e; d['c'] = c
    o._p[k] = d

