def _init_globals():
    global g_object_proto, g_function_proto, g_array_proto, g_string_proto
    global g_number_proto, g_boolean_proto, g_symbol_proto, g_bigint_proto
    global g_err_proto, g_err_protos, g_regexp_proto, g_promise_proto
