    global g_date_proto, g_ab_proto, g_ta_proto, g_dv_proto
    global g_global

    # Bootstrap prototypes
    g_object_proto = JSObj()
    g_function_proto = JSObj(g_object_proto)
    g_function_proto._cls = 'Function'

    def _make_proto(parent=None):
        p = JSObj(parent or g_object_proto)
        return p

    g_array_proto = _make_proto()
    g_array_proto._cls = 'Array'
