    g_bigint_proto._cls = 'BigInt'

    # Error protos
    g_err_proto = _make_proto()
    g_err_proto._cls = 'Error'
    _setprop(g_err_proto, 'name', 'Error', True, False, True)
    _setprop(g_err_proto, 'message', '', True, False, True)

    for ename in ('TypeError','RangeError','ReferenceError','SyntaxError','EvalError','URIError','InternalError','AggregateError'):
        p = _make_proto(g_err_proto)
        p._cls = 'Error'
        _setprop(p, 'name', ename, True, False, True)
        _setprop(p, 'message', '', True, False, True)
        g_err_protos[ename] = p

    g_regexp_proto = _make_proto()
    g_regexp_proto._cls = 'RegExp'
    g_promise_proto = _make_proto()
    g_promise_proto._cls = 'Promise'
    g_gen_proto = _make_proto()
    g_gen_proto._cls = 'Generator'
    g_iter_proto = _make_proto()
    g_map_proto = _make_proto()
    g_map_proto._cls = 'Map'
    g_set_proto = _make_proto()
    g_set_proto._cls = 'Set'
    g_weakmap_proto = _make_proto()
    g_weakmap_proto._cls = 'WeakMap'
    g_weakset_proto = _make_proto()
    g_weakset_proto._cls = 'WeakSet'
    g_weakref_proto = _make_proto()
    g_weakref_proto._cls = 'WeakRef'
    g_date_proto = _make_proto()
    g_date_proto._cls = 'Date'
    g_ab_proto = _make_proto()
    g_ab_proto._cls = 'ArrayBuffer'
    g_ta_proto = _make_proto()
    g_ta_proto._cls = 'TypedArray'
    g_dv_proto = _make_proto()
    g_dv_proto._cls = 'DataView'

    g_global = JSObj()
    g_global._cls = 'global'

    _setup_all()
    return g_global

def _fn(name='', length=0):
    """Decorator for builtin functions"""
    def dec(f):
        o = JSObj(g_function_proto)
        o._cls = 'Function'
        o._call = lambda this, args, nt=None: f(this, args)
        o._name = name or f.__name__.lstrip('_')
        o._len = length
        o._is_arrow = True
        return o
    return dec

