# ===== Object =====
def _setup_object():
    # Object constructor
    def obj_call(this, args, nt=None):
        if not args or args[0] is null or args[0] is undefined:
            return JSObj(g_object_proto)
        return _to_obj(args[0])

    obj_ctor = _make_fn(obj_call, 'Object', 1, False)
    obj_ctor._ctor = obj_call
    obj_ctor._p['prototype'] = {'v':g_object_proto,'w':False,'e':False,'c':False}
    g_object_proto._p['constructor'] = {'v':obj_ctor,'w':True,'e':False,'c':True}

    # Object static methods
    def obj_keys(this, args):
        o = _to_obj(args[0] if args else undefined)
        return _make_arr(o._own_enum_keys())
    def obj_values(this, args):
        o = _to_obj(args[0] if args else undefined)
        return _make_arr([o._get(k) for k in o._own_enum_keys()])
    def obj_entries(this, args):
        o = _to_obj(args[0] if args else undefined)
        return _make_arr([_make_arr([k, o._get(k)]) for k in o._own_enum_keys()])
    def obj_assign(this, args):
        if not args: return _mk_err('TypeError','Cannot convert undefined to object')
        target = _to_obj(args[0])
        for src in args[1:]:
            if src is null or src is undefined: continue
            s = _to_obj(src)
            for k in s._own_enum_keys():
                target._set(k, s._get(k))
        return target
    def obj_create(this, args):
        proto = args[0] if args else undefined
        if proto is null: p = None
        elif _is_obj(proto): p = proto
        else: raise JSThrow(_mk_err('TypeError','Object prototype must be an Object or null'))
        o = JSObj(p)
        if len(args) > 1 and args[1] is not undefined:
            _obj_define_props(o, args[1])
        return o
    def obj_freeze(this, args):
        o = args[0] if args else undefined
        if not _is_obj(o): return o
        o._ext = False
        for k in list(o._p.keys()):
            d = o._p[k]
            d['c'] = False
            if 'v' in d: d['w'] = False
        return o
    def obj_seal(this, args):
        o = args[0] if args else undefined
        if not _is_obj(o): return o
        o._ext = False
        for k in list(o._p.keys()): o._p[k]['c'] = False
        return o
    def obj_is_frozen(this, args):
        o = args[0] if args else undefined
        if not _is_obj(o): return True
        if o._ext: return False
        for d in o._p.values():
            if d.get('c',True) or ('v' in d and d.get('w',True)): return False
        return True
    def obj_is_sealed(this, args):
        o = args[0] if args else undefined
        if not _is_obj(o): return True
        if o._ext: return False
        for d in o._p.values():
            if d.get('c',True): return False
        return True
    def obj_is_extensible(this, args):
        o = args[0] if args else undefined
        return o._ext if _is_obj(o) else False
    def obj_prevent_ext(this, args):
        o = args[0] if args else undefined
        if _is_obj(o): o._ext = False
        return o
    def obj_get_proto(this, args):
        v = args[0] if args else undefined
        o = _to_obj(v)
        if o._proto is None: return null
        return o._proto
    def obj_set_proto(this, args):
        o = args[0] if args else undefined
        p = args[1] if len(args)>1 else undefined
        if not _is_obj(o): return o
        if p is null: o._proto = None
        elif _is_obj(p): o._proto = p
        else: raise JSThrow(_mk_err('TypeError','prototype must be object or null'))
        return o
    def obj_define_prop(this, args):
        o = _get_arg(args, 0)
        k = _to_str(_get_arg(args, 1))
        desc = _get_arg(args, 2)
        _obj_def_prop(o, k, desc)
        return o
    def obj_define_props(this, args):
        o = _get_arg(args, 0)
        props = _to_obj(_get_arg(args, 1))
