        return o
    def obj_freeze(this, args):
        o = args[0] if args else undefined
        if not _is_obj(o): return o
        o._ext = False
        for k in list(o._p.keys()):
            d = o._p[k]
            d['c'] = False
            if 'v' in d: d['w'] = False
        return o
    def obj_seal(this, args):
        o = args[0] if args else undefined
        if not _is_obj(o): return o
        o._ext = False
        for k in list(o._p.keys()): o._p[k]['c'] = False
        return o
    def obj_is_frozen(this, args):
        o = args[0] if args else undefined
        if not _is_obj(o): return True
        if o._ext: return False
        for d in o._p.values():
            if d.get('c',True) or ('v' in d and d.get('w',True)): return False
        return True
    def obj_is_sealed(this, args):
        o = args[0] if args else undefined
        if not _is_obj(o): return True
        if o._ext: return False
        for d in o._p.values():
            if d.get('c',True): return False
        return True
    def obj_is_extensible(this, args):
        o = args[0] if args else undefined
        return o._ext if _is_obj(o) else False
    def obj_prevent_ext(this, args):
        o = args[0] if args else undefined
        if _is_obj(o): o._ext = False
        return o
    def obj_get_proto(this, args):
        v = args[0] if args else undefined
        o = _to_obj(v)
        if o._proto is None: return null
        return o._proto
    def obj_set_proto(this, args):
        o = args[0] if args else undefined
        p = args[1] if len(args)>1 else undefined
        if not _is_obj(o): return o
        if p is null: o._proto = None
        elif _is_obj(p): o._proto = p
        else: raise JSThrow(_mk_err('TypeError','prototype must be object or null'))
