    def obj_define_prop(this, args):
        o = _get_arg(args, 0)
        k = _to_str(_get_arg(args, 1))
        desc = _get_arg(args, 2)
        _obj_def_prop(o, k, desc)
        return o
    def obj_define_props(this, args):
        o = _get_arg(args, 0)
        props = _to_obj(_get_arg(args, 1))
        _obj_define_props(o, props)
        return o
    def obj_get_own_desc(this, args):
        o = _to_obj(_get_arg(args, 0))
        k = _to_str(_get_arg(args, 1))
        d = o._p.get(k)
        if d is None: return undefined
        r = JSObj(g_object_proto)
        if 'get' in d:
            _setprop(r, 'get', d.get('get', undefined))
            _setprop(r, 'set', d.get('set', undefined))
        else:
            _setprop(r, 'value', d.get('v', undefined))
            _setprop(r, 'writable', bool(d.get('w', False)))
        _setprop(r, 'enumerable', bool(d.get('e', False)))
        _setprop(r, 'configurable', bool(d.get('c', False)))
        return r
    def obj_get_own_descs(this, args):
        o = _to_obj(_get_arg(args, 0))
        r = JSObj(g_object_proto)
        for k in o._own_keys_all():
            d = o._p.get(k)
            if d is None: continue
            desc = JSObj(g_object_proto)
            if 'get' in d:
                _setprop(desc, 'get', d.get('get', undefined))
                _setprop(desc, 'set', d.get('set', undefined))
            else:
                _setprop(desc, 'value', d.get('v', undefined))
                _setprop(desc, 'writable', bool(d.get('w', False)))
            _setprop(desc, 'enumerable', bool(d.get('e', False)))
            _setprop(desc, 'configurable', bool(d.get('c', False)))
            _setprop(r, k if isinstance(k, str) else str(k), desc)
        return r
    def obj_get_own_names(this, args):
        o = _to_obj(_get_arg(args, 0))
        return _make_arr([k for k in o._own_keys_all() if isinstance(k, str)])
    def obj_get_own_syms(this, args):
        o = _to_obj(_get_arg(args, 0))
        return _make_arr([k for k in o._own_keys_all() if isinstance(k, Symbol)])
    def obj_from_entries(this, args):
        it = _get_arg(args, 0)
        o = JSObj(g_object_proto)
        for item in _iter_to_list(it):
            if not isinstance(item, JSArr) or item._len < 2:
                if _is_obj(item):
                    k = _to_str(item._get('0') if _is_obj(item) else undefined)
                    v = item._get('1') if _is_obj(item) else undefined
                else: continue
            else:
                k = _to_str(item._items[0] if item._items else undefined)
                v = item._items[1] if len(item._items)>1 else undefined
            o._set(k, v)
        return o
    def obj_is(this, args):
        a,b = _get_arg(args,0), _get_arg(args,1)
