        k = _to_str(_get_arg(args,1))
        return o._has_own(k)
    def obj_group_by(this, args):
        items = _get_arg(args, 0)
        fn = _get_arg(args, 1)
        result = JSObj(g_object_proto)
        for x in _iter_to_list(items):
            key = _to_str(_call(fn, undefined, [x]))
            arr = result._get(key)
            if not isinstance(arr, JSArr):
                arr = JSArr(g_array_proto)
                result._set(key, arr)
            arr._arr_set(arr._len, x)
        return result
    def obj_spread(this, args):
        result = JSObj(g_object_proto)
        for a in args:
            if _is_obj(a):
                for k in a._own_enum_keys():
                    result._set(k, a._get(k))
        return result

    for name, fn, ln in [
        ('keys', obj_keys, 1), ('values', obj_values, 1), ('entries', obj_entries, 1),
        ('assign', obj_assign, 2), ('create', obj_create, 1), ('freeze', obj_freeze, 1),
        ('seal', obj_seal, 1), ('isFrozen', obj_is_frozen, 1), ('isSealed', obj_is_sealed, 1),
        ('isExtensible', obj_is_extensible, 1), ('preventExtensions', obj_prevent_ext, 1),
        ('getPrototypeOf', obj_get_proto, 1), ('setPrototypeOf', obj_set_proto, 2),
        ('defineProperty', obj_define_prop, 3), ('defineProperties', obj_define_props, 2),
        ('getOwnPropertyDescriptor', obj_get_own_desc, 2),
        ('getOwnPropertyDescriptors', obj_get_own_descs, 1),
        ('getOwnPropertyNames', obj_get_own_names, 1),
        ('getOwnPropertySymbols', obj_get_own_syms, 1),
        ('fromEntries', obj_from_entries, 1), ('is', obj_is, 2),
        ('hasOwn', obj_has_own, 2), ('groupBy', obj_group_by, 2),
    ]:
        _def_static(obj_ctor, name, fn, ln)

    # Object.prototype methods
    def obj_proto_has_own_prop(this, args):
        k = _to_str(_get_arg(args,0))
        return _to_obj(this)._has_own(k)
    def obj_proto_is_proto_of(this, args):
        v = _get_arg(args, 0)
        if not _is_obj(v): return False
        p = v._proto
        while p: 
            if p is this: return True
            p = p._proto
        return False
    def obj_proto_prop_is_enum(this, args):
        k = _to_str(_get_arg(args,0))
        o = _to_obj(this)
        d = o._p.get(k)
