    def obj_proto_tostring(this, args):
        if this is undefined: return '[object Undefined]'
        if this is null: return '[object Null]'
        o = _to_obj(this)
        # Check Symbol.toStringTag
        tag = None
        c = o
        while c:
            d = c._p.get(sym_toStringTag)
            if d and 'v' in d: tag = d['v']; break
            c = c._proto
        if isinstance(tag, str): return f'[object {tag}]'
        cls = o._cls
        m = {'Array':'Array','Function':'Function','RegExp':'RegExp','Date':'Date',
             'Error':'Error','Arguments':'Arguments','Generator':'Generator',
             'Promise':'Promise','Map':'Map','Set':'Set','ArrayBuffer':'ArrayBuffer',
             'SharedArrayBuffer':'SharedArrayBuffer',
             'Uint8Array':'Uint8Array','Int8Array':'Int8Array',
             'Uint16Array':'Uint16Array','Int16Array':'Int16Array',
             'Uint32Array':'Uint32Array','Int32Array':'Int32Array',
             'Float32Array':'Float32Array','Float64Array':'Float64Array'}
        return f'[object {m.get(cls,"Object")}]'
    def obj_proto_valueof(this, args): return _to_obj(this)
    def obj_proto_tolocalestring(this, args): return _to_str(_to_obj(this)._get('toString') and _call(_to_obj(this)._get('toString'), this, []) or this)

    for name, fn, ln in [
        ('hasOwnProperty', obj_proto_has_own_prop, 1),
        ('isPrototypeOf', obj_proto_is_proto_of, 1),
        ('propertyIsEnumerable', obj_proto_prop_is_enum, 1),
