def _obj_def_prop(o, k, desc):
    if not _is_obj(o): raise JSThrow(_mk_err('TypeError', 'Object.defineProperty: not an object'))
    if not _is_obj(desc): raise JSThrow(_mk_err('TypeError', 'descriptor must be an object'))
    has_get = desc._has_own('get')
    has_set = desc._has_own('set')
    has_val = desc._has_own('value')
    has_wri = desc._has_own('writable')
    if (has_get or has_set) and (has_val or has_wri):
        raise JSThrow(_mk_err('TypeError', 'Cannot both specify accessors and value/writable'))
    d = {}
    if has_get: d['get'] = desc._get('get')
    if has_set: d['set'] = desc._get('set')
    if has_val: d['v'] = desc._get('value')
    if has_wri: d['w'] = bool(desc._get('writable'))
    if desc._has_own('enumerable'): d['e'] = bool(desc._get('enumerable'))
    if desc._has_own('configurable'): d['c'] = bool(desc._get('configurable'))

    # Convert string-indexed k
    if isinstance(k, str):
        try:
            i = int(k)
            if str(i) == k and isinstance(o, JSArr):
                o._def(k, d)
                return
        except (ValueError, OverflowError): pass

    existing = o._p.get(k)
    if existing is None:
        if not o._ext: raise JSThrow(_mk_err('TypeError', f"Cannot define property '{k}' on non-extensible object"))
        new_d = {}
        if 'get' in d or 'set' in d:
            new_d['get'] = d.get('get', undefined)
            new_d['set'] = d.get('set', undefined)
        else:
            new_d['v'] = d.get('v', undefined)
            new_d['w'] = d.get('w', False)
        new_d['e'] = d.get('e', False)
        new_d['c'] = d.get('c', False)
        o._p[k] = new_d
    else:
        if not existing.get('c', False):
            # Configurable changes only
            if 'e' in d and d['e'] != existing.get('e',False): raise JSThrow(_mk_err('TypeError','Cannot redefine'))
            if 'get' in d or 'set' in d:
                # accessor desc on non-configurable
                if 'v' in existing: raise JSThrow(_mk_err('TypeError','Cannot redefine'))
            elif 'v' in d and 'v' in existing:
                if existing.get('w', False):
                    existing['v'] = d['v']
                    return
                if not _seq(existing['v'], d['v']): raise JSThrow(_mk_err('TypeError','Cannot redefine'))
        for kk in ('v','w','e','c','get','set'):
            if kk in d: existing[kk] = d[kk]

def _obj_define_props(o, props_obj):
    for k in props_obj._own_enum_keys():
        desc = props_obj._get(k)
        _obj_def_prop(o, k, desc)

def _js_is(a, b):
    if _is_num(a) and _is_num(b):
        fa, fb = float(a), float(b)
        if math.isnan(fa) and math.isnan(fb): return True
        if fa == 0 and fb == 0:
            return math.copysign(1,fa) == math.copysign(1,fb)
        return fa == fb
    return _seq(a, b)

def _get_arg(args, i, default=None):
    if i < len(args): return args[i]
    return undefined if default is None else default

def _make_arr(items):
    a = JSArr(g_array_proto)
    for i, x in enumerate(items):
        a._arr_set(i, x)
    return a

def _iter_to_list(v):
    """Convert iterable to Python list"""
    if isinstance(v, JSArr):
        return [v._items[i] if i < len(v._items) and v._items[i] is not _HOLE else undefined
                for i in range(v._len)]
    if _is_obj(v):
        it_fn = v._get(sym_iterator)
        if _callable(it_fn):
            it = _call(it_fn, v, [])
            return _iter_consume(it)
    if isinstance(v, (list, tuple)): return list(v)
    return []

def _iter_consume(it):
    result = []
    next_fn = it._get('next') if _is_obj(it) else None
    if not _callable(next_fn): return result
    for _ in range(100000):  # safety limit
        r = _call(next_fn, it, [])
        if not _is_obj(r): break
        done = r._get('done')
        if _to_bool(done): break
        result.append(r._get('value'))
    return result

def _own_keys_all(o):
    return list(o._p.keys())

# Add _own_keys_all to JSObj
JSObj._own_keys_all = _own_keys_all

