# ===== Function =====
def _setup_function():
    # Function prototype methods
    def fn_call(this, args):
        fn = _to_obj(this) if _is_obj(this) else None
        if not _is_obj(fn) or not fn._call:
            raise JSThrow(_mk_err('TypeError','Function.prototype.call called on non-function'))
        new_this = _get_arg(args, 0)
        fn_args = args[1:] if len(args) > 1 else []
        return _call(fn, new_this, fn_args)
    def fn_apply(this, args):
        fn = this
        if not _is_obj(fn) or not fn._call:
            raise JSThrow(_mk_err('TypeError','not a function'))
        new_this = _get_arg(args, 0)
        arr = _get_arg(args, 1)
        fn_args = _iter_to_list(arr) if arr is not undefined and arr is not null else []
        return _call(fn, new_this, fn_args)
    def fn_bind(this, args):
        fn = this
        if not _is_obj(fn) or not fn._call:
            raise JSThrow(_mk_err('TypeError','not a function'))
        bound_this = _get_arg(args, 0)
        bound_args = args[1:]
        def bound_call(new_this, call_args, nt=None):
            return _call(fn, bound_this, list(bound_args) + list(call_args))
        b = _make_fn(bound_call, 'bound ' + (fn._name or ''), max(0, fn._len - len(bound_args)))
        b._ctor = None
        return b
    def fn_tostring(this, args):
        if not _is_obj(this) or this._call is None:
            raise JSThrow(_mk_err('TypeError','not a function'))
        name = this._name or 'anonymous'
        return f'function {name}() {{ [native code] }}'

    _def_method(g_function_proto, 'call', fn_call, 1)
    _def_method(g_function_proto, 'apply', fn_apply, 2)
    _def_method(g_function_proto, 'bind', fn_bind, 1)
    _def_method(g_function_proto, 'toString', fn_tostring, 0)

    # length and name getters on Function.prototype
    def fn_length_get(this, args):
        return this._len if _is_obj(this) else 0
    def fn_name_get(this, args):
        return this._name if _is_obj(this) else ''
    _setget(g_function_proto, 'length', get=_make_fn(fn_length_get,'get length',0))
    _setget(g_function_proto, 'name', get=_make_fn(fn_name_get,'get name',0))

    # Function constructor
    def fn_ctor(this, args, nt=None):
        # Function('body') or Function('arg1','arg2',...,'body')
        if not args: body = ''
        elif len(args) == 1: body = _to_str(args[0])
        else:
            params = ', '.join(_to_str(a) for a in args[:-1])
            body = _to_str(args[-1])
            body = f'return (function({params}) {{ {body} }})'
        try:
            result = _eval_source(body, '<anonymous>', False, False)
        except Exception as e:
            raise JSThrow(_mk_err('SyntaxError', str(e)))
        if _callable(result): return result
        # Try to create function
        o = _make_fn(lambda t,a,nt=None: undefined, 'anonymous')
        return o

    fn_obj = _make_fn(fn_ctor, 'Function', 1, False)
    fn_obj._ctor = fn_ctor
    fn_obj._p['prototype'] = {'v':g_function_proto,'w':False,'e':False,'c':False}
    g_function_proto._p['constructor'] = {'v':fn_obj,'w':True,'e':False,'c':True}
    _setprop(g_global, 'Function', fn_obj)

# ===== Array =====
def _setup_array():
    def arr_is_arr(this, args):
        v = _get_arg(args, 0)
        return isinstance(v, JSArr)

    def arr_from(this, args):
        src = _get_arg(args, 0)
        map_fn = _get_arg(args, 1)
        items = _iter_to_list(src)
        if isinstance(src, str): items = list(src)
        if _callable(map_fn):
            items = [_call(map_fn, undefined, [x, i]) for i,x in enumerate(items)]
        return _make_arr(items)

    def arr_of(this, args):
        return _make_arr(list(args))

    def arr_from_dict(d, proto=None):
        a = JSArr(proto or g_array_proto)
        for i,v in enumerate(d): a._arr_set(i, v)
        return a

    # Array constructor
    def arr_ctor(this, args, nt=None):
        if len(args) == 1 and _is_num(args[0]):
            n = _to_uint32(args[0])
            if float(args[0]) != n:
                raise JSThrow(_mk_err('RangeError','Invalid array length'))
            a = JSArr(g_array_proto); a._len = n; return a
        return _make_arr(list(args))

    arr_obj = _make_fn(arr_ctor, 'Array', 1, False)
    arr_obj._ctor = arr_ctor
    arr_obj._p['prototype'] = {'v':g_array_proto,'w':False,'e':False,'c':False}
    g_array_proto._p['constructor'] = {'v':arr_obj,'w':True,'e':False,'c':True}
    _def_static(arr_obj, 'isArray', arr_is_arr, 1)
    _def_static(arr_obj, 'from', arr_from, 1)
    _def_static(arr_obj, 'of', arr_of, 0)

    def arr_groupby(this, args):
        items = _get_arg(args, 0)
        fn = _get_arg(args, 1)
        # Map.groupBy
        m = JSObj(g_map_proto); m._cls = 'Map'; m._map = []
        for x in _iter_to_list(items):
            key = _call(fn, undefined, [x])
            for pair in m._map:
                if _js_is(pair[0], key):
                    pair[1]._arr_set(pair[1]._len, x); break
            else:
                a = _make_arr([x]); m._map.append([key, a])
        return m

    # Array prototype methods
    def _get_arr_items(v):
        if isinstance(v, JSArr): return list(v._items[:v._len]) + [_HOLE]*(v._len - len(v._items))
        o = _to_obj(v)
        ln = _to_uint32(o._get('length'))
        return [o._get(str(i)) for i in range(ln)]

    def arr_push(this, args):
        a = _to_obj(this)
        if isinstance(a, JSArr):
            for x in args: a._arr_set(a._len, x)
            return a._len
        ln = _to_uint32(a._get('length'))
        for x in args: a._set(str(ln), x); ln += 1
        a._set('length', ln); return ln

    def arr_pop(this, args):
        a = _to_obj(this)
        if isinstance(a, JSArr):
            if a._len == 0: return undefined
            a._len -= 1
            if a._len < len(a._items):
                v = a._items[a._len]
                a._items[a._len] = _HOLE
                return undefined if v is _HOLE else v
            return undefined
        ln = _to_uint32(a._get('length'))
        if ln == 0: return undefined
        v = a._get(str(ln-1)); a._del(str(ln-1)); a._set('length', ln-1); return v

    def arr_shift(this, args):
        a = _to_obj(this)
        items = _get_arr_items(a)
        if not items: return undefined
        v = items[0]
        if isinstance(a, JSArr):
            a._items = ([_HOLE]+a._items[1:]) if a._items else []
            a._items = a._items[1:]
            a._len = max(0, a._len-1)
        else:
            for i in range(len(items)-1): a._set(str(i), items[i+1])
            a._del(str(len(items)-1)); a._set('length', len(items)-1)
        return undefined if v is _HOLE else v

    def arr_unshift(this, args):
        a = _to_obj(this)
        if isinstance(a, JSArr):
            new_items = list(args) + [x for x in a._items[:a._len]]
            a._items = new_items
            a._len = len(new_items)
            return a._len
        items = _get_arr_items(a)
        new_items = list(args) + items
        for i,v in enumerate(new_items): a._set(str(i), v)
        a._set('length', len(new_items)); return len(new_items)

    def arr_splice(this, args):
        a = _to_obj(this)
        items = _get_arr_items(a)
        n = len(items)
        start_raw = _to_int32(_get_arg(args, 0))
        start = max(0, n+start_raw) if start_raw < 0 else min(start_raw, n)
        del_count = n - start if len(args) < 2 else max(0, min(_to_uint32(args[1]), n-start))
        removed = _make_arr([x for x in items[start:start+del_count] if x is not _HOLE])
        new_items = items[:start] + list(args[2:]) + items[start+del_count:]
        if isinstance(a, JSArr):
            a._items = new_items; a._len = len(new_items)
        else:
            for i,v in enumerate(new_items): a._set(str(i), v)
            for i in range(len(new_items), n): a._del(str(i))
            a._set('length', len(new_items))
        return removed

    def arr_slice(this, args):
        a = _to_obj(this)
        items = _get_arr_items(a)
        n = len(items)
        s_raw = _to_int32(_get_arg(args, 0))
        e_raw = _to_int32(_get_arg(args, 1)) if len(args)>1 and args[1] is not undefined else n
        s = max(0,n+s_raw) if s_raw<0 else min(s_raw,n)
        e = max(0,n+e_raw) if e_raw<0 else min(e_raw,n)
        return _make_arr([x for x in items[s:e] if x is not _HOLE] if s<=e else [])

    def arr_concat(this, args):
        result = []
        for item in [this] + list(args):
            if isinstance(item, JSArr):
                # Check Symbol.isConcatSpreadable
                sp = item._get(sym_isConcatSpreadable)
                if sp is not undefined:
                    if _to_bool(sp):
                        result.extend(item._items[i] if i<len(item._items) else undefined for i in range(item._len))
                    else:
                        result.append(item)
                else:
                    result.extend(item._items[i] if i<len(item._items) and item._items[i] is not _HOLE else undefined for i in range(item._len))
            else:
                result.append(item)
        return _make_arr(result)

    def arr_join(this, args):
        a = _to_obj(this)
        items = _get_arr_items(a)
        sep = _to_str(_get_arg(args, 0)) if args and args[0] is not undefined else ','
        parts = []
        for x in items:
