        if isinstance(v,BigInt): return v
        if isinstance(v,str):
            s = v.strip()
            try: return BigInt(int(s,0) if s.startswith(('0x','0o','0b')) else int(s))
            except: raise JSThrow(_mk_err('SyntaxError',f'Cannot convert {v!r} to BigInt'))
        if isinstance(v,bool): return BigInt(1 if v else 0)
        raise JSThrow(_mk_err('TypeError',f'Cannot convert {_to_str(v)} to BigInt'))
    bigint_obj = _make_fn(bigint_fn,'BigInt',1)
    def bi_tostr(this, args):
