        if isinstance(this,BigInt): return this
        if _is_obj(this) and isinstance(this._pval,BigInt): return this._pval
        raise JSThrow(_mk_err('TypeError','not a BigInt'))
    def bi_as_intn(this, args):
        w = int(_to_num(_get_arg(args,0))); v = _get_arg(args,1)
        bv = v.v if isinstance(v,BigInt) else BigInt(int(_to_num(v))).v
        mask = (1<<w)-1
        bv = bv & mask
        if bv >= (1<<(w-1)): bv -= (1<<w)
        return BigInt(bv)
    def bi_as_uintn(this, args):
        w = int(_to_num(_get_arg(args,0))); v = _get_arg(args,1)
        bv = v.v if isinstance(v,BigInt) else BigInt(int(_to_num(v))).v
        return BigInt(bv & ((1<<w)-1))
