def _setup_json():
    json_obj = JSObj(g_object_proto)
    json_obj._cls = 'JSON'

    def json_parse(this, args):
        s = _to_str(_get_arg(args,0))
        try:
            data = json.loads(s)
            return _py_to_js(data)
        except json.JSONDecodeError as e:
            raise JSThrow(_mk_err('SyntaxError', str(e)))

    def _py_to_js(v):
        if v is None: return null
        if isinstance(v,bool): return v
        if isinstance(v,(int,float)): return float(v)
        if isinstance(v,str): return v
        if isinstance(v,list):
            a = JSArr(g_array_proto)
            for i,x in enumerate(v): a._arr_set(i, _py_to_js(x))
            return a
        if isinstance(v,dict):
            o = JSObj(g_object_proto)
            for k,val in v.items(): o._set(k, _py_to_js(val))
            return o
        return null

    def _js_to_py(v, replacer=None, space=None, seen=None):
        if seen is None: seen = set()
        if v is null or v is undefined: return None
        if isinstance(v,bool): return v
        if isinstance(v,str): return v
        if _is_num(v): return float(v)
        if isinstance(v,BigInt): raise JSThrow(_mk_err('TypeError','Do not know how to serialize a BigInt'))
        if isinstance(v,Symbol): return None  # undefined in JSON
        if _is_obj(v):
            oid = id(v)
            if oid in seen: raise JSThrow(_mk_err('TypeError','Converting circular structure to JSON'))
            seen = seen | {oid}
            to_json = v._get('toJSON')
            if _callable(to_json): v = _call(to_json, v, [])
            if v is undefined or v is null: return None
            if isinstance(v,JSArr):
                return [_js_to_py(v._items[i] if i<len(v._items) else undefined, replacer, space, seen) for i in range(v._len)]
            if _is_obj(v):
                keys = v._own_enum_keys()
                if replacer and isinstance(replacer, JSArr): keys = [k for k in keys if k in _iter_to_list(replacer)]
                result = {}
                for k in keys:
                    val = v._get(k)
                    if _callable(replacer): val = _call(replacer, v, [k, val])
                    if val is not undefined and not isinstance(val,Symbol) and not (callable(getattr(val,'_call',None))):
                        py_val = _js_to_py(val, replacer, space, seen)
                        if py_val is not None or True: result[k] = py_val  # include undefined-converted-to-None? Actually JSON.stringify omits undefined values
                        # Actually should not include None that came from undefined
                return {k:v for k,v in result.items() if v is not None or isinstance(v,bool)}
        return None

    def json_stringify(this, args):
        v = _get_arg(args,0)
        replacer = _get_arg(args,1)
        space_raw = _get_arg(args,2)

        if isinstance(space_raw, (int,float)) and not isinstance(space_raw,bool):
            space = ' ' * min(10, int(space_raw))
        elif isinstance(space_raw,str):
            space = space_raw[:10]
        else:
            space = None

        repl_fn = replacer if _callable(replacer) else None
        repl_arr = replacer if isinstance(replacer,JSArr) else None

        def stringify_val(v, key='', indent=0, seen=None):
            if seen is None: seen = set()
            if repl_fn: v = _call(repl_fn, this, [key, v])
            if v is undefined or isinstance(v,Symbol) or (_is_obj(v) and v._call is not None): return None
            if v is null: return 'null'
            if isinstance(v,bool): return 'true' if v else 'false'
            if _is_num(v):
                n = float(v)
                if math.isnan(n) or math.isinf(n): return 'null'
                return _js_num_str(n)
            if isinstance(v,BigInt): raise JSThrow(_mk_err('TypeError','Cannot serialize BigInt'))
            if isinstance(v,str): return json.dumps(v, ensure_ascii=False)
            if _is_obj(v):
                oid = id(v)
                if oid in seen: raise JSThrow(_mk_err('TypeError','Converting circular structure to JSON'))
                seen2 = seen | {oid}
                to_json = v._get('toJSON')
                if _callable(to_json): v = _call(to_json, v, [key]); return stringify_val(v, key, indent, seen)
                if isinstance(v, JSArr):
                    items = []
                    for i in range(v._len):
                        item = v._items[i] if i<len(v._items) else undefined
                        s = stringify_val(item, str(i), indent+1, seen2)
                        items.append('null' if s is None else s)
                    if not items: return '[]'
                    if space:
                        inner_indent = space*(indent+1)
                        outer_indent = space*indent
                        return '[\n'+inner_indent+(',\n'+inner_indent).join(items)+'\n'+outer_indent+']'
                    return '['+','.join(items)+']'
                else:
                    keys = v._own_enum_keys()
                    if repl_arr: keys = [k for k in keys if any(_seq(k, r) for r in _iter_to_list(repl_arr))]
                    parts = []
                    for k in keys:
                        val = v._get(k)
                        s = stringify_val(val, k, indent+1, seen2)
                        if s is not None: parts.append(json.dumps(k, ensure_ascii=False)+(':' if not space else ': ')+s)
                    if not parts: return '{}'
                    if space:
                        inner_indent = space*(indent+1)
                        outer_indent = space*indent
                        return '{\n'+inner_indent+(',\n'+inner_indent).join(parts)+'\n'+outer_indent+'}'
                    return '{'+','.join(parts)+'}'
            return None

        result = stringify_val(v)
        return undefined if result is None else result

    _def_method(json_obj,'parse',json_parse,2)
    _def_method(json_obj,'stringify',json_stringify,3)
    _setprop(g_global,'JSON',json_obj)

