    o._flags = flags
    o._last_index = 0
    return o

def _re_to_python(re_obj):
    """Convert JS regex to Python regex with flags"""
    pat = re_obj._pattern
    flags = re_obj._flags
    # Convert JS groups to Python groups
    # Handle named groups (?<name>...) -> (?P<name>...)
    def fix_named(m):
        if m.group(1) in ('=', '!', '<=',' <!'):
            return m.group(0)
        return '(?P<' + m.group(1) + '>'

    # Fix named groups
    py_pat = re.sub(r'\(\?<(?!(?:=|!))([a-zA-Z_][a-zA-Z0-9_]*)>', fix_named, pat)

    # Fix back references \k<name>
    py_pat = re.sub(r'\\k<([a-zA-Z_][a-zA-Z0-9_]*)>', r'(?P=\1)', py_pat)

    # Fix \p{} and \P{} - Unicode properties (simplified)
    py_pat = re.sub(r'\\[pP]\{[^}]+\}', '.', py_pat)

    # Fix lookbehind (?<=) and (?<!) - Python 3.7+ supports these

    try:
        py_flags = 0
        if 'i' in flags: py_flags |= re.IGNORECASE
        if 'm' in flags: py_flags |= re.MULTILINE
        if 's' in flags: py_flags |= re.DOTALL
        if 'u' in flags: py_flags |= re.UNICODE
        if 'v' in flags: py_flags |= re.VERBOSE  # simplified

        compiled = re.compile(py_pat, py_flags)
        return compiled
    except re.error:
        try:
            return re.compile(re.escape(pat))
        except:
            return re.compile('(?!x)x')  # never matches

def _setup_regexp():
    def re_ctor(this, args, nt=None):
        pat = _get_arg(args,0)
        flags_raw = _get_arg(args,1)
        if _is_obj(pat) and pat._cls == 'RegExp':
            p = pat._pattern
            f = _to_str(flags_raw) if flags_raw is not undefined else pat._flags
        else:
            p = _to_str(pat) if pat is not undefined else ''
            f = _to_str(flags_raw) if flags_raw is not undefined else ''
        return _create_regexp(p, f)

    re_obj = _make_fn(re_ctor,'RegExp',2,False)
    re_obj._ctor = re_ctor
    re_obj._p['prototype']={'v':g_regexp_proto,'w':False,'e':False,'c':False}
    g_regexp_proto._p['constructor']={'v':re_obj,'w':True,'e':False,'c':True}

    def re_test(this, args):
        if not _is_obj(this) or this._cls != 'RegExp': raise JSThrow(_mk_err('TypeError','not a RegExp'))
        s = _to_str(_get_arg(args,0))
        compiled = _re_to_python(this)
        if 'g' in this._flags or 'y' in this._flags:
            start = int(_to_num(this._get('lastIndex') or 0))
            m = compiled.search(s, start)
            if m: this._set('lastIndex',m.end()); return True
            this._set('lastIndex',0); return False
        return bool(compiled.search(s))

    def re_exec(this, args):
        if not _is_obj(this) or this._cls != 'RegExp': raise JSThrow(_mk_err('TypeError','not a RegExp'))
        s = _to_str(_get_arg(args,0))
        compiled = _re_to_python(this)
        flags = this._flags
        start = 0
        if 'g' in flags or 'y' in flags or 'd' in flags:
            li = this._get('lastIndex')
            start = int(_to_num(li)) if li is not undefined else 0
        m = compiled.search(s, max(0, start))
        if m is None:
            if 'g' in flags or 'y' in flags: this._set('lastIndex',0)
