    def _py_to_js(v):
        if v is None: return null
        if isinstance(v,bool): return v
        if isinstance(v,(int,float)): return float(v)
        if isinstance(v,str): return v
        if isinstance(v,list):
            a = JSArr(g_array_proto)
            for i,x in enumerate(v): a._arr_set(i, _py_to_js(x))
            return a
        if isinstance(v,dict):
            o = JSObj(g_object_proto)
            for k,val in v.items(): o._set(k, _py_to_js(val))
            return o
        return null

    def _js_to_py(v, replacer=None, space=None, seen=None):
        if seen is None: seen = set()
        if v is null or v is undefined: return None
        if isinstance(v,bool): return v
        if isinstance(v,str): return v
        if _is_num(v): return float(v)
        if isinstance(v,BigInt): raise JSThrow(_mk_err('TypeError','Do not know how to serialize a BigInt'))
        if isinstance(v,Symbol): return None  # undefined in JSON
        if _is_obj(v):
            oid = id(v)
            if oid in seen: raise JSThrow(_mk_err('TypeError','Converting circular structure to JSON'))
            seen = seen | {oid}
