def _setup_proxy():
    proxy_proto=JSObj(g_object_proto); proxy_proto._cls='Proxy'

    class JSProxy(JSObj):
        def __init__(self, target, handler):
            super().__init__(target._proto if _is_obj(target) else None)
            self.__dict__['_target'] = target
            self.__dict__['_handler'] = handler
            self.__dict__['_cls'] = 'Proxy'

        def _get(self, k, recv=None):
            if recv is None: recv = self
            h = self.__dict__['_handler']
            if _is_obj(h):
                get_trap = h._get('get')
                if _callable(get_trap):
                    return _call(get_trap, h, [self.__dict__['_target'], k if isinstance(k,str) else _to_str(k), recv])
            return self.__dict__['_target']._get(k, recv) if _is_obj(self.__dict__['_target']) else undefined

        def _set(self, k, v, recv=None, strict=False):
            if recv is None: recv = self
            h = self.__dict__['_handler']
            if _is_obj(h):
                set_trap = h._get('set')
                if _callable(set_trap):
                    r = _call(set_trap, h, [self.__dict__['_target'], k if isinstance(k,str) else _to_str(k), v, recv])
                    if strict and not _to_bool(r): raise JSThrow(_mk_err('TypeError','Proxy set trap returned false'))
                    return
            if _is_obj(self.__dict__['_target']): self.__dict__['_target']._set(k, v, recv, strict)

        def _has(self, k):
            h = self.__dict__['_handler']
            if _is_obj(h):
                has_trap = h._get('has')
                if _callable(has_trap):
                    return _to_bool(_call(has_trap, h, [self.__dict__['_target'], k if isinstance(k,str) else _to_str(k)]))
            return self.__dict__['_target']._has(k) if _is_obj(self.__dict__['_target']) else False

        def _enum_keys(self):
            return self.__dict__['_target']._enum_keys() if _is_obj(self.__dict__['_target']) else []

        def _own_enum_keys(self):
            return self.__dict__['_target']._own_enum_keys() if _is_obj(self.__dict__['_target']) else []

    def proxy_ctor(this, args, nt=None):
        target=_get_arg(args,0); handler=_get_arg(args,1)
        if not _is_obj(target): raise JSThrow(_mk_err('TypeError','Proxy target must be an object'))
        if not _is_obj(handler): raise JSThrow(_mk_err('TypeError','Proxy handler must be an object'))
        return JSProxy(target, handler)

    proxy_obj=_make_fn(proxy_ctor,'Proxy',2,False); proxy_obj._ctor=proxy_ctor
    _setprop(g_global,'Proxy',proxy_obj)

