def _setup_date():
    import datetime

    def _parse_date(s):
        # ISO 8601
        try: return datetime.datetime.fromisoformat(s.replace('Z','+00:00')).timestamp()*1000
        except: pass
        try: return datetime.datetime.strptime(s,'%Y-%m-%d').timestamp()*1000
        except: pass
        return float('nan')

    def date_ctor(this, args, nt=None):
        o=JSObj(g_date_proto); o._cls='Date'
        if not args:
            o.__dict__['_ms']=time.time()*1000
        elif len(args)==1:
            v=args[0]
            if isinstance(v,str): o.__dict__['_ms']=_parse_date(v)
            elif _is_obj(v) and v._cls=='Date': o.__dict__['_ms']=v.__dict__.get('_ms',float('nan'))
            else: o.__dict__['_ms']=float(_to_num(v))
        else:
            yr,mo,dy=int(_to_num(args[0])),int(_to_num(args[1])),int(_to_num(args[2])) if len(args)>2 else 1
            hr,mn,sc,ms=int(_to_num(args[3])) if len(args)>3 else 0,int(_to_num(args[4])) if len(args)>4 else 0,int(_to_num(args[5])) if len(args)>5 else 0,int(_to_num(args[6])) if len(args)>6 else 0
            try:
                dt=datetime.datetime(yr,mo+1,dy,hr,mn,sc)
                o.__dict__['_ms']=dt.timestamp()*1000+ms
            except: o.__dict__['_ms']=float('nan')
        return o

    date_obj=_make_fn(date_ctor,'Date',7,False); date_obj._ctor=date_ctor
    date_obj._p['prototype']={'v':g_date_proto,'w':False,'e':False,'c':False}
    def date_now(this,args): return time.time()*1000
    def date_parse(this,args): return _parse_date(_to_str(_get_arg(args,0)))
    _def_static(date_obj,'now',date_now,0)
    _def_static(date_obj,'parse',date_parse,1)

    def _get_dt(this):
        ms=this.__dict__.get('_ms',float('nan'))
        if math.isnan(ms): return None
        try: return datetime.datetime.utcfromtimestamp(ms/1000)
        except: return None
    def _get_local_dt(this):
        ms=this.__dict__.get('_ms',float('nan'))
        if math.isnan(ms): return None
        try: return datetime.datetime.fromtimestamp(ms/1000)
        except: return None

