def _setup_globals():
    # parseInt
    def parse_int(this, args):
        s = _to_str(_get_arg(args,0))
        radix = int(_to_num(_get_arg(args,1))) if len(args)>1 and args[1] is not undefined else 0
        s = s.strip()
        if not s: return float('nan')
        neg = s[0]=='-'; 
        if s[0] in '+-': s=s[1:]
        if radix==0:
            if s.startswith(('0x','0X')): radix=16; s=s[2:]
            elif s.startswith(('0o','0O')): radix=8; s=s[2:]
            elif s.startswith(('0b','0B')): radix=2; s=s[2:]
            else: radix=10
        elif radix==16 and s.startswith(('0x','0X')): s=s[2:]
        try:
            digits = '0123456789abcdefghijklmnopqrstuvwxyz'[:radix]
            valid = ''
            for c in s.lower():
                if c in digits: valid+=c
                else: break
            if not valid: return float('nan')
            n = int(valid, radix)
            return float(-n if neg else n)
        except: return float('nan')

    def parse_float(this, args):
        s = _to_str(_get_arg(args,0)).strip()
        if not s: return float('nan')
        try: return float(s)
        except:
            # Try partial parse
            for i in range(len(s),0,-1):
                try: return float(s[:i])
                except: pass
            return float('nan')

