            if s.startswith(('0x','0X')): radix=16; s=s[2:]
            elif s.startswith(('0o','0O')): radix=8; s=s[2:]
            elif s.startswith(('0b','0B')): radix=2; s=s[2:]
            else: radix=10
        elif radix==16 and s.startswith(('0x','0X')): s=s[2:]
        try:
            digits = '0123456789abcdefghijklmnopqrstuvwxyz'[:radix]
            valid = ''
            for c in s.lower():
                if c in digits: valid+=c
                else: break
            if not valid: return float('nan')
            n = int(valid, radix)
            return float(-n if neg else n)
        except: return float('nan')

    def parse_float(this, args):
        s = _to_str(_get_arg(args,0)).strip()
        if not s: return float('nan')
        try: return float(s)
        except:
            # Try partial parse
            for i in range(len(s),0,-1):
                try: return float(s[:i])
                except: pass
            return float('nan')

    def is_nan(this, args): return math.isnan(_to_num(_get_arg(args,0)))
    def is_finite(this, args): return math.isfinite(_to_num(_get_arg(args,0)))

    def encode_uri(this, args):
        import urllib.parse
        s = _to_str(_get_arg(args,0))
        return urllib.parse.quote(s, safe=";/?:@&=+$,#-_.!~*'()")
    def decode_uri(this, args):
        import urllib.parse
        s = _to_str(_get_arg(args,0))
        try: return urllib.parse.unquote(s, errors='strict')
        except: raise JSThrow(_mk_err('URIError','malformed URI'))
    def encode_uri_comp(this, args):
        import urllib.parse
        return urllib.parse.quote(_to_str(_get_arg(args,0)), safe="-_.!~*'()")
    def decode_uri_comp(this, args):
        import urllib.parse
        try: return urllib.parse.unquote(_to_str(_get_arg(args,0)), errors='strict')
        except: raise JSThrow(_mk_err('URIError','malformed URI'))

    def btoa(this, args):
        import base64
        s = _to_str(_get_arg(args,0))
        try: return base64.b64encode(s.encode('latin1')).decode('ascii')
        except: raise JSThrow(_mk_err('InvalidCharacterError','btoa failed'))
    def atob(this, args):
