    def queueMicrotask(this, args):
        fn = _get_arg(args, 0)
        if _callable(fn): _schedule(lambda: _call(fn, undefined, []))
        return undefined

    def structuredClone(this, args):
        v = _get_arg(args, 0)
        return _structured_clone(v, {})

    def _structured_clone(v, seen):
        if v is null or v is undefined or isinstance(v,(bool,str,Symbol)): return v
        if _is_num(v): return v
        if isinstance(v,BigInt): return BigInt(v.v)
        if _is_obj(v):
            oid=id(v)
            if oid in seen: return seen[oid]
            if isinstance(v,JSArr):
                result=JSArr(g_array_proto)
                seen[oid]=result
                for i in range(v._len):
                    item=v._items[i] if i<len(v._items) else _HOLE
                    if item is not _HOLE: result._arr_set(i,_structured_clone(item,seen))
                    result._len=v._len
                return result
            if v._cls in ('Map','Set'): # simplified
                result=JSObj(v._proto); result._cls=v._cls
                seen[oid]=result
                if v._cls=='Map': result.__dict__['_map']=[[_structured_clone(k,seen),_structured_clone(u,seen)] for k,u in v.__dict__.get('_map',[])]
                else: result.__dict__['_set']=[_structured_clone(x,seen) for x in v.__dict__.get('_set',[])]
                return result
            result=JSObj(v._proto); result._cls=v._cls
            seen[oid]=result
            for k,d in v._p.items():
                if isinstance(k,str): result._p[k]={'v':_structured_clone(d.get('v',undefined),seen),'w':d.get('w',True),'e':d.get('e',True),'c':d.get('c',True)}
            return result
        return v

