# ===== Evaluator =====

class Interpreter:
    """JavaScript interpreter - evaluates AST nodes"""

    def __init__(self, global_scope, filename='<unknown>', module=False):
        self.global_scope = global_scope
        self.filename = filename
        self.module = module
        self._pending_imports = {}  # module_name -> promise
        self._module_cache = {}  # module_name -> exports

    def eval_program(self, node, scope=None):
        if scope is None:
            scope = Scope(strict=node.is_module)
            scope.this_val = g_global

        if node.is_module:
            return self.eval_module(node, scope)

        # Hoist function declarations
        self._hoist_funcs(node.stmts, scope)
        # Hoist var declarations
        self._hoist_vars(node.stmts, scope)

        result = undefined
        for stmt in node.stmts:
            result = self.eval_stmt(stmt, scope)

        _flush_microtasks()
        return result

    def eval_module(self, node, scope):
        # Collect exports
        exports = JSObj(g_object_proto)
        scope._module_exports = exports

        self._hoist_funcs(node.stmts, scope)
        self._hoist_vars(node.stmts, scope)

        for stmt in node.stmts:
            self.eval_stmt(stmt, scope)

        _flush_microtasks()
        return exports

    def _hoist_funcs(self, stmts, scope):
        for stmt in stmts:
            if stmt is None: continue
            if stmt.t == 'FuncDecl':
                fn = self.make_function(stmt.func, scope)
                if stmt.func.name:
                    scope.def_v(stmt.func.name, fn)

    def _hoist_vars(self, stmts, scope):
        for stmt in stmts:
            if stmt is None: continue
            if stmt.t == 'VarDecl' and stmt.kind == 'var':
                for decl in stmt.decls:
                    self._hoist_var_pattern(decl.pattern, scope)
            elif stmt.t in ('Block', 'If', 'While', 'DoWhile', 'For', 'ForIn', 'ForOf', 'Switch', 'Try', 'With', 'Labeled'):
                self._hoist_vars_in_stmt(stmt, scope)

    def _hoist_var_pattern(self, pat, scope):
        if pat.t == 'Ident':
            if not scope.has_own(pat.name):
                scope.def_v(pat.name, undefined)
        elif pat.t in ('ObjPat', 'ArrPat'):
            self._hoist_pattern_vars(pat, scope)

    def _hoist_pattern_vars(self, pat, scope):
        if pat.t == 'Ident':
            if not scope.has_own(pat.name): scope.def_v(pat.name, undefined)
        elif pat.t == 'ObjPat':
            for p in pat.props:
                if p.t == 'ObjPropPat': self._hoist_pattern_vars(p.val, scope)
                elif p.t == 'ObjShortPat': self._hoist_pattern_vars(p.key, scope)
                elif p.t == 'RestProp': self._hoist_pattern_vars(p.pattern, scope)
        elif pat.t == 'ArrPat':
            for item in pat.items:
                if item: self._hoist_pattern_vars(item.pattern if hasattr(item,'pattern') else item, scope)

    def _hoist_vars_in_stmt(self, stmt, scope):
        if stmt is None: return
        if stmt.t == 'Block':
            for s in stmt.body: self._hoist_vars([s], scope)
        elif stmt.t == 'If':
            self._hoist_vars_in_stmt(stmt.then, scope)
            if stmt.else_: self._hoist_vars_in_stmt(stmt.else_, scope)
        elif stmt.t in ('While','DoWhile','Labeled'):
            self._hoist_vars_in_stmt(stmt.body if hasattr(stmt,'body') else None, scope)
        elif stmt.t in ('For','ForIn','ForOf'):
            if hasattr(stmt,'body'): self._hoist_vars_in_stmt(stmt.body, scope)
        elif stmt.t == 'Switch':
            for c in stmt.cases:
                for s in (c.body if hasattr(c,'body') else []):
                    self._hoist_vars([s], scope)
        elif stmt.t == 'Try':
            self._hoist_vars_in_stmt(stmt.body, scope)
            if stmt.catch_: self._hoist_vars_in_stmt(stmt.catch_.body, scope)
            if stmt.finally_: self._hoist_vars_in_stmt(stmt.finally_, scope)

    def eval_stmt(self, stmt, scope):
        if stmt is None: return undefined
        t = stmt.t

        if t == 'ExprStmt':
            return self.eval_expr(stmt.expr, scope)
        elif t == 'Block':
            sub = Scope(scope)
            self._hoist_funcs(stmt.body, sub)
            result = undefined
            for s in stmt.body:
                result = self.eval_stmt(s, sub)
            return result
        elif t == 'VarDecl':
            return self.eval_var_decl(stmt, scope)
        elif t == 'FuncDecl':
            # Already hoisted, but handle let/const function expressions
            fn = self.make_function(stmt.func, scope)
            if stmt.func.name:
                scope.set_own(stmt.func.name, fn) if scope.has_own(stmt.func.name) else scope.def_v(stmt.func.name, fn)
            return undefined
        elif t == 'ClassDecl':
            cls = self.eval_class(stmt, scope)
            if stmt.name: scope.def_l(stmt.name, cls) if not scope.has_own(stmt.name) else scope.set_own(stmt.name, cls)
            return undefined
        elif t == 'Return':
            val = self.eval_expr(stmt.value, scope) if stmt.value else undefined
            raise JSReturn(val)
        elif t == 'If':
            if _to_bool(self.eval_expr(stmt.test, scope)):
                return self.eval_stmt(stmt.then, scope)
            elif stmt.else_:
                return self.eval_stmt(stmt.else_, scope)
        elif t == 'While':
            return self.eval_while(stmt, scope)
        elif t == 'DoWhile':
            return self.eval_do_while(stmt, scope)
        elif t == 'For':
            return self.eval_for(stmt, scope)
        elif t == 'ForIn':
            return self.eval_for_in(stmt, scope)
        elif t == 'ForOf':
            return self.eval_for_of(stmt, scope)
        elif t == 'Break':
            raise JSBreak(stmt.label)
        elif t == 'Continue':
            raise JSContinue(stmt.label)
        elif t == 'Throw':
            val = self.eval_expr(stmt.value, scope)
            if _is_obj(val) and _is_err(val):
                # Ensure stack trace
                pass
            raise JSThrow(val)
        elif t == 'Try':
            return self.eval_try(stmt, scope)
        elif t == 'Switch':
            return self.eval_switch(stmt, scope)
        elif t == 'Labeled':
            return self.eval_labeled(stmt, scope)
        elif t == 'With':
            return self.eval_with(stmt, scope)
        elif t == 'Debugger':
            return undefined
        elif t == 'Import':
            return self.eval_import(stmt, scope)
        elif t in ('Export','ExportDefault','ExportDecl','ExportNamed','ExportAll'):
            return self.eval_export(stmt, scope)
        elif t == 'StaticBlock':
            sub = Scope(scope)
            for s in stmt.body.body: self.eval_stmt(s, sub)
            return undefined
        return undefined

    def eval_var_decl(self, stmt, scope):
        kind = stmt.kind
        for decl in stmt.decls:
            val = undefined
            if decl.init:
                val = self.eval_expr(decl.init, scope)
            self.bind_pattern(decl.pattern, val, scope, kind)
        return undefined

    def bind_pattern(self, pat, val, scope, kind='let'):
        if pat.t == 'Ident':
            name = pat.name
            if kind == 'var':
                # Find var scope
                s = scope
                while s and s.parent: s = s.parent
                s = scope  # actually use current for simplicity
                scope.def_v(name, val)
            elif kind in ('let','const'):
                scope.def_l(name, val)
            else:
                scope.set(name, val)
        elif pat.t == 'ObjPat':
            obj = _to_obj(val)
            for prop in pat.props:
                if prop.t == 'RestProp':
                    # Collect remaining keys
                    assigned = set()
                    for p2 in pat.props:
                        if p2.t != 'RestProp':
                            if p2.t == 'ObjPropPat': assigned.add(_to_str(self.eval_prop_key(p2.key, scope)))
                            elif p2.t == 'ObjShortPat': assigned.add(p2.key.name if hasattr(p2.key,'name') else _to_str(self.eval_prop_key(p2.key,scope)))
                    rest = JSObj(g_object_proto)
                    for k in obj._own_enum_keys():
                        if k not in assigned: rest._set(k, obj._get(k))
                    self.bind_pattern(prop.pattern, rest, scope, kind)
                elif prop.t == 'ObjPropPat':
                    key = _to_str(self.eval_prop_key(prop.key, scope))
                    v = obj._get(key)
                    if v is undefined and prop.default:
                        v = self.eval_expr(prop.default, scope)
                    self.bind_pattern(prop.val, v, scope, kind)
                elif prop.t == 'ObjShortPat':
                    key = prop.key.name if hasattr(prop.key,'name') else _to_str(self.eval_prop_key(prop.key,scope))
                    v = obj._get(key)
                    if v is undefined and hasattr(prop,'default') and prop.default:
                        v = self.eval_expr(prop.default, scope)
                    self.bind_pattern(prop.key, v, scope, kind)
        elif pat.t == 'ArrPat':
            it = _iter_to_list(val) if val is not undefined and val is not null else []
            for i, item in enumerate(pat.items):
                if item is None: continue
                if item.t == 'RestElem':
                    rest_val = _make_arr(it[i:])
                    self.bind_pattern(item.pattern, rest_val, scope, kind)
                    break
                v = it[i] if i < len(it) else undefined
                if v is undefined and hasattr(item,'default') and item.default:
                    v = self.eval_expr(item.default, scope)
                self.bind_pattern(item.pattern if hasattr(item,'pattern') else item, v, scope, kind)
        elif pat.t == 'Param':
            self.bind_pattern(pat.pattern, val, scope, kind)
        elif pat.t == 'Ident':
            self.bind_pattern(pat, val, scope, kind)

    def eval_prop_key(self, key, scope):
        if key.t == 'Ident': return key.name
        if key.t == 'Lit': return key.value
        if key.t == 'Str': return key.value
        if key.t == 'Computed': return self.eval_expr(key.expr, scope)
        if key.t == 'PrivKey': return key.name
        return _to_str(self.eval_expr(key, scope))

    def eval_while(self, stmt, scope):
        while _to_bool(self.eval_expr(stmt.test, scope)):
            try:
                sub = Scope(scope)
                self.eval_stmt(stmt.body, sub)
            except JSBreak as e:
                if e.label is None: break
                raise
            except JSContinue as e:
                if e.label is None: continue
                raise
        return undefined

    def eval_do_while(self, stmt, scope):
        while True:
            try:
                sub = Scope(scope)
                self.eval_stmt(stmt.body, sub)
            except JSBreak as e:
                if e.label is None: break
                raise
            except JSContinue as e:
                if e.label is None: pass
                else: raise
            if not _to_bool(self.eval_expr(stmt.test, scope)): break
        return undefined

    def eval_for(self, stmt, scope):
        sub = Scope(scope)
        if stmt.init:
            if hasattr(stmt.init,'t') and stmt.init.t == 'VarDecl':
                self.eval_stmt(stmt.init, sub)
            else:
                self.eval_expr(stmt.init, sub)
        while True:
            if stmt.test and not _to_bool(self.eval_expr(stmt.test, sub)): break
            try:
                body_scope = Scope(sub)
                self.eval_stmt(stmt.body, body_scope)
            except JSBreak as e:
                if e.label is None: break
                raise
            except JSContinue as e:
                if e.label is None: pass
                else: raise
