            if stmt.finally_:
                sub2 = Scope(scope)
                try: self.eval_stmt(stmt.finally_, sub2)
                except: pass
            raise
        if stmt.finally_:
            sub2 = Scope(scope)
            self.eval_stmt(stmt.finally_, sub2)
        return undefined

    def eval_switch(self, stmt, scope):
        disc = self.eval_expr(stmt.disc, scope)
        matched = False
        result = undefined
        for case in stmt.cases:
            if not matched:
                if case.t == 'Default':
                    pass
                else:
                    test_val = self.eval_expr(case.test, scope)
                    if _seq(disc, test_val): matched = True
            if matched or case.t == 'Default':
                if case.t == 'Default' and not matched:
                    continue
                try:
                    sub = Scope(scope)
                    for s in case.body:
                        result = self.eval_stmt(s, sub)
                except JSBreak as e:
                    if e.label is None: return result
                    raise
        # Try default case if nothing matched
        if not matched:
            for case in stmt.cases:
                if case.t == 'Default':
                    try:
                        sub = Scope(scope)
                        for s in case.body:
                            result = self.eval_stmt(s, sub)
                    except JSBreak as e:
                        if e.label is None: return result
                        raise
                    break
        return result

    def eval_labeled(self, stmt, scope):
        try:
            return self.eval_stmt(stmt.body, scope)
        except JSBreak as e:
            if e.label == stmt.label: return undefined
            raise
        except JSContinue as e:
            if e.label == stmt.label: return undefined
            raise

    def eval_with(self, stmt, scope):
        obj = _to_obj(self.eval_expr(stmt.obj, scope))
        sub = Scope(scope)
        # Add obj's properties to scope
        class WithScope(Scope):
            def get(self, name):
