            exports = JSObj(g_object_proto)
            if module_name == 'std': _setup_std_module(exports)
            elif module_name == 'os': _setup_os_module(exports)
            self._module_cache[module_name] = exports
            return exports

        # File module
        if not os.path.isabs(module_name):
            base = os.path.dirname(self.filename)
            path = os.path.join(base, module_name)
        else:
            path = module_name

        # Try with .js extension
        if not os.path.exists(path):
            for ext in ('.js', '.mjs', '.cjs'):
                if os.path.exists(path + ext):
                    path = path + ext
                    break

