                src = f.read()
        except IOError as e:
            raise JSThrow(_mk_err('Error', str(e)))

        try:
            ast = parse_js(src, path, module=True)
        except SyntaxError as e:
            raise JSThrow(_mk_err('SyntaxError', str(e)))

        interp = Interpreter(self.global_scope, path, module=True)
