        for case in stmt.cases:
            if not matched:
                if case.t == 'Default':
                    pass
                else:
                    test_val = self.eval_expr(case.test, scope)
                    if _seq(disc, test_val): matched = True
            if matched or case.t == 'Default':
                if case.t == 'Default' and not matched:
                    continue
