    def eval_export(self, stmt, scope):
        exports = scope._module_exports
        if stmt.t == 'ExportDefault':
            val = undefined
            if hasattr(stmt,'decl') and stmt.decl:
                val = self.eval_stmt(stmt.decl, scope)
                if _is_obj(val) and val._name: pass
            elif hasattr(stmt,'expr') and stmt.expr:
                val = self.eval_expr(stmt.expr, scope)
            if _is_obj(exports): exports._set('default', val)
        elif stmt.t == 'ExportDecl':
            self.eval_stmt(stmt.decl, scope)
