    def eval_expr(self, node, scope):
        if node is None: return undefined
        t = node.t

        if t == 'Num': return float(node.value) if not isinstance(node.value, bool) else node.value
        if t == 'Str': return node.value
        if t == 'Bool': return node.value
        if t == 'Null': return null
        if t == 'Undefined': return undefined
        if t == 'BigInt': return BigInt(node.value)
        if t == 'Regexp': return _create_regexp(node.pattern, node.flags)

        if t == 'Ident':
            name = node.name
            try:
                return scope.get(name)
            except JSThrow:
                raise

        if t == 'This': return scope.get_this()
        if t == 'Super': return scope.get_this()

        if t == 'Template':
            parts = node.parts
            exprs = node.exprs
            result = parts[0] if parts else ''
            for i, expr in enumerate(exprs):
                val = self.eval_expr(expr, scope)
                result += _to_str(val)
                if i+1 < len(parts): result += parts[i+1]
            return result

        if t == 'TaggedTemplate':
            tag = self.eval_expr(node.tag, scope)
            parts = node.parts
            exprs_vals = [self.eval_expr(e, scope) for e in node.exprs]
            # Create template strings array
            str_arr = _make_arr(list(parts))
            raw_arr = _make_arr(list(parts))
            str_arr._set('raw', raw_arr)
            return _call(tag, undefined, [str_arr] + exprs_vals)

        if t == 'Paren': return self.eval_expr(node.expr, scope)
        if t == 'SeqExpr':
            result = undefined
            for e in node.exprs: result = self.eval_expr(e, scope)
            return result

        if t == 'ArrLit':
            items = []
            for item in node.items:
                if item is None:
                    items.append(_HOLE)
                elif item.t == 'Spread':
                    val = self.eval_expr(item.arg, scope)
                    items.extend(_iter_to_list(val) if not isinstance(val,str) else list(val))
                else:
                    items.append(self.eval_expr(item, scope))
            a = JSArr(g_array_proto)
            for i, v in enumerate(items):
                if v is not _HOLE: a._arr_set(i, v)
            a._len = len(items)
            return a

        if t == 'ObjLit':
            o = JSObj(g_object_proto)
            for prop in node.props:
                if prop.t == 'Spread':
                    val = self.eval_expr(prop.arg, scope)
                    if _is_obj(val):
                        for k in val._own_enum_keys(): o._set(k, val._get(k))
                elif prop.t == 'Prop':
                    key = self.eval_prop_key(prop.key, scope)
                    val = self.eval_expr(prop.value, scope)
                    if isinstance(key, Symbol):
                        o._p[key] = {'v':val,'w':True,'e':True,'c':True}
                    else:
                        o._set(_to_str(key) if not isinstance(key,str) else key, val)
                elif prop.t == 'ShortProp':
                    name = prop.key.name if hasattr(prop.key,'name') else _to_str(self.eval_prop_key(prop.key,scope))
                    try: val = scope.get(name)
                    except: val = undefined
                    o._set(name, val)
                elif prop.t == 'MethodProp':
                    key = self.eval_prop_key(prop.key, scope)
                    fn = self.make_function(prop.func, scope)
                    fn._home_object = o
                    kind = prop.kind if hasattr(prop,'kind') else 'init'
                    if kind == 'get':
                        existing = o._p.get(key if isinstance(key,str) else _to_str(key), {})
                        d = {'get':fn,'e':True,'c':True}
                        if 'set' in existing: d['set'] = existing['set']
                        o._p[key if isinstance(key,str) else _to_str(key)] = d
                    elif kind == 'set':
                        existing = o._p.get(key if isinstance(key,str) else _to_str(key), {})
                        d = {'set':fn,'e':True,'c':True}
                        if 'get' in existing: d['get'] = existing['get']
                        o._p[key if isinstance(key,str) else _to_str(key)] = d
                    else:
                        k = key if isinstance(key,(str,Symbol)) else _to_str(key)
                        o._p[k] = {'v':fn,'w':True,'e':True,'c':True}
            return o

        if t == 'Member':
            obj = self.eval_expr(node.obj, scope)
            if node.optional and (obj is null or obj is undefined): return undefined
            if obj is null:
                raise JSThrow(_mk_err('TypeError', f"Cannot read properties of null (reading '{node.name}')"))
            if obj is undefined:
                raise JSThrow(_mk_err('TypeError', f"Cannot read properties of undefined (reading '{node.name}')"))
            target = _to_obj(obj)
            val = target._get(node.name)
            # String indexing
            if isinstance(obj, str) and val is undefined:
                try:
                    i = int(node.name)
                    if 0 <= i < len(obj): return obj[i]
                except (ValueError, OverflowError): pass
                if node.name == 'length': return len(obj)
            return val

        if t == 'Index':
            obj = self.eval_expr(node.obj, scope)
            key = self.eval_expr(node.idx, scope)
            if node.optional and (obj is null or obj is undefined): return undefined
            if obj is null: raise JSThrow(_mk_err('TypeError', f"Cannot read properties of null"))
            if obj is undefined: raise JSThrow(_mk_err('TypeError', f"Cannot read properties of undefined"))
            k = key
            if isinstance(key, (int, float)) and not isinstance(key, bool):
                k = str(int(key)) if key == int(key) else _to_str(key)
            elif isinstance(key, bool): k = 'true' if key else 'false'
            elif not isinstance(key, (str, Symbol)): k = _to_str(key)
            target = _to_obj(obj)
            val = target._get(k) if isinstance(k, Symbol) else target._get(k)
            if isinstance(obj, str) and val is undefined:
                try:
                    i = int(k) if isinstance(k,str) else int(k)
                    if 0 <= i < len(obj): return obj[i]
                except (ValueError, OverflowError, TypeError): pass
                if k == 'length': return len(obj)
            return val

        if t == 'Call':
            return self.eval_call(node, scope)

        if t == 'New':
            return self.eval_new(node, scope)

        if t == 'Assign':
            return self.eval_assign(node, scope)

        if t == 'Bin':
            return self.eval_bin(node, scope)

        if t == 'Unary':
            return self.eval_unary(node, scope)

        if t == 'Update':
            return self.eval_update(node, scope)

        if t == 'Cond':
            test = self.eval_expr(node.test, scope)
            return self.eval_expr(node.then if _to_bool(test) else node.else_, scope)

        if t == 'Typeof':
            try:
                val = self.eval_typeof_arg(node.arg, scope)
            except JSThrow:
                return 'undefined'
            return _typeof(val)

        if t == 'Void':
            self.eval_expr(node.arg, scope)
            return undefined

        if t == 'Delete':
            return self.eval_delete(node, scope)

        if t == 'Await':
            val = self.eval_expr(node.arg, scope)
            if _is_obj(val) and val._cls == 'Promise':
                # Simple synchronous await - resolve promise synchronously
                _flush_microtasks()
                if val.__dict__['_state'] == 'fulfilled':
                    return val.__dict__['_value']
                elif val.__dict__['_state'] == 'rejected':
                    raise JSThrow(val.__dict__['_value'])
            return val

        if t == 'Yield':
            val = self.eval_expr(node.value, scope) if node.value else undefined
            raise _YieldSignal(val, node.delegate)

        if t == 'Func':
            return self.make_function(node, scope)

        if t == 'ClassExpr' or t == 'ClassDecl':
            return self.eval_class(node, scope)

        if t == 'Arrow':
            return self.make_arrow(node, scope)

        if t == 'NewTarget':
            # new.target
            return undefined  # simplified

        if t == 'Super':
            return scope.get_this()

        if t == 'SuperCall':
            this = scope.get_this()
            args = [self.eval_expr(a, scope) if a.t != 'Spread' else None for a in node.args]
            flat_args = self.eval_args(node.args, scope)
            # Find super class
            fn = self._find_super_class(scope)
            if fn:
                result = _construct(fn, flat_args, this)
                if _is_obj(result) and _is_obj(this):
                    # Copy properties to this
                    for k, d in result._p.items(): this._p[k] = d
            return this

        if t == 'SuperMember':
            this = scope.get_this()
            proto = this._proto if _is_obj(this) else None
            if proto and proto._proto:
                return proto._proto._get(node.name)
            elif proto:
                return proto._get(node.name)
            return undefined

        if t == 'SuperIndex':
            this = scope.get_this()
            key = _to_str(self.eval_expr(node.idx, scope))
            proto = this._proto if _is_obj(this) else None
            if proto and proto._proto: return proto._proto._get(key)
            elif proto: return proto._get(key)
            return undefined

        if t == 'ImportCall':
            src = _to_str(self.eval_expr(node.src, scope))
            try:
                mod = self.load_module(src, scope)
                p = JSObj(g_promise_proto); p._cls='Promise'
                p.__dict__['_state']='fulfilled'; p.__dict__['_value']=mod; p.__dict__['_callbacks']=[]
                return p
            except JSThrow as e:
                p = JSObj(g_promise_proto); p._cls='Promise'
                p.__dict__['_state']='rejected'; p.__dict__['_value']=e.v; p.__dict__['_callbacks']=[]
                return p

        if t == 'ImportMeta':
            try:
                meta = scope.get('__import_meta__')
                return meta if meta is not undefined else JSObj(g_object_proto)
            except: 
                meta = JSObj(g_object_proto)
                meta._set('url', 'file://'+os.path.abspath(self.filename))
                return meta

        if t == 'PrivField':
            name = node.name
            this = scope.get_this()
            if _is_obj(this) and '_private' in this.__dict__:
                return this.__dict__['_private'].get(name, undefined)
            return undefined

        return undefined

    def _find_super_class(self, scope):
        """Find the super class constructor in scope"""
        s = scope
        while s:
            if hasattr(s, '_super_class'): return s._super_class
            s = s.parent
        return None

    def eval_typeof_arg(self, arg, scope):
        """Evaluate argument for typeof (no ReferenceError)"""
        if arg.t == 'Ident':
            try: return scope.get(arg.name)
            except JSThrow: return undefined
        return self.eval_expr(arg, scope)

    def eval_call(self, node, scope):
        callee = node.callee
        args = self.eval_args(node.args, scope)

        # Optional chaining
        if node.optional:
            fn = self.eval_expr(callee, scope)
            if fn is null or fn is undefined: return undefined
            return _call(fn, undefined, args)

        # Get method and this
        if callee.t == 'Member':
            obj = self.eval_expr(callee.obj, scope)
            if obj is null:
                raise JSThrow(_mk_err('TypeError', f"Cannot read properties of null (reading '{callee.name}')"))
            if obj is undefined:
                raise JSThrow(_mk_err('TypeError', f"Cannot read properties of undefined (reading '{callee.name}')"))
            target = _to_obj(obj)
            fn = target._get(callee.name)
            if isinstance(obj, str):
                if fn is undefined:
                    fn = g_string_proto._get(callee.name)
            return _call(fn, obj, args)
        elif callee.t == 'Index':
            obj = self.eval_expr(callee.obj, scope)
            if obj is null: raise JSThrow(_mk_err('TypeError', 'Cannot read properties of null'))
            if obj is undefined: raise JSThrow(_mk_err('TypeError', 'Cannot read properties of undefined'))
            key = self.eval_expr(callee.idx, scope)
            k = str(int(key)) if _is_num(key) and key==int(key) else _to_str(key)
            target = _to_obj(obj)
            fn = target._get(k)
            if isinstance(obj, str) and fn is undefined:
                fn = g_string_proto._get(k)
            return _call(fn, obj, args)
        elif callee.t == 'SuperCall':
            return self.eval_expr(callee, scope)
        elif callee.t == 'SuperMember':
            this = scope.get_this()
            fn = self.eval_expr(callee, scope)
            return _call(fn, this, args)
        else:
            fn = self.eval_expr(callee, scope)
            this = undefined
            if callee.t == 'Ident' and callee.name not in ('eval',):
                this = scope.get_this()
                # Actually for regular function calls, this is undefined in strict mode
                if scope.strict() or (isinstance(fn, JSObj) and fn._is_arrow):
                    this = undefined
            if callee.t == 'Ident' and callee.name == 'eval':
                # Direct eval
                if args:
                    s = args[0]
                    if isinstance(s, str):
                        return _eval_source(s, '<eval>', scope.strict(), False, scope)
                return undefined
            return _call(fn, undefined, args)

    def eval_args(self, arg_nodes, scope):
        args = []
        for a in arg_nodes:
            if hasattr(a,'t') and a.t == 'Spread':
                val = self.eval_expr(a.arg, scope)
                args.extend(_iter_to_list(val) if not isinstance(val,str) else list(val))
            else:
                args.append(self.eval_expr(a, scope))
        return args

    def eval_new(self, node, scope):
        callee = self.eval_expr(node.callee, scope)
        args = self.eval_args(node.args, scope)

        if not _is_obj(callee):
            raise JSThrow(_mk_err('TypeError', f"'{_to_str(callee)}' is not a constructor"))

        return _construct(callee, args)

    def eval_assign(self, node, scope):
        op = node.op

        if op == '=':
            val = self.eval_expr(node.right, scope)
            self.assign_to(node.left, val, scope)
            return val

        # Compound assignment
        left_val = self.eval_expr(node.left, scope)

        # Short-circuit operators
        if op == '&&=':
            if not _to_bool(left_val): return left_val
            val = self.eval_expr(node.right, scope)
            self.assign_to(node.left, val, scope)
            return val
        if op == '||=':
            if _to_bool(left_val): return left_val
            val = self.eval_expr(node.right, scope)
            self.assign_to(node.left, val, scope)
            return val
        if op == '??=':
            if left_val is not null and left_val is not undefined: return left_val
            val = self.eval_expr(node.right, scope)
            self.assign_to(node.left, val, scope)
            return val

        right_val = self.eval_expr(node.right, scope)
        result = self.apply_bin_op(op[:-1], left_val, right_val)
        self.assign_to(node.left, result, scope)
        return result

    def eval_bin(self, node, scope):
        op = node.op

        # Short-circuit
        if op == '&&':
            left = self.eval_expr(node.left, scope)
            return left if not _to_bool(left) else self.eval_expr(node.right, scope)
        if op == '||':
            left = self.eval_expr(node.left, scope)
            return left if _to_bool(left) else self.eval_expr(node.right, scope)
        if op == '??':
            left = self.eval_expr(node.left, scope)
            return left if left is not null and left is not undefined else self.eval_expr(node.right, scope)

        left = self.eval_expr(node.left, scope)
        right = self.eval_expr(node.right, scope)
        return self.apply_bin_op(op, left, right)

    def apply_bin_op(self, op, left, right):
        if op == '+':
            if isinstance(left, str) or isinstance(right, str):
                return _to_str(left) + _to_str(right)
            if isinstance(left, BigInt) and isinstance(right, BigInt): return left + right
            if isinstance(left, (JSObj,)) or isinstance(right, (JSObj,)):
                lp = _to_prim(left) if _is_obj(left) else left
                rp = _to_prim(right) if _is_obj(right) else right
                if isinstance(lp, str) or isinstance(rp, str): return _to_str(lp)+_to_str(rp)
                return _to_num(lp)+_to_num(rp)
            return _to_num(left)+_to_num(right)
        if op == '-':
            if isinstance(left,BigInt) and isinstance(right,BigInt): return left-right
            return _to_num(left)-_to_num(right)
        if op == '*':
            if isinstance(left,BigInt) and isinstance(right,BigInt): return left*right
            return _to_num(left)*_to_num(right)
        if op == '/':
            n,d = _to_num(left),_to_num(right)
            if d==0:
                if n==0: return float('nan')
                return math.copysign(float('inf'),n) if math.copysign(1,n)==math.copysign(1,d) else math.copysign(float('-inf'),n)
            return n/d
        if op == '%':
            if isinstance(left,BigInt) and isinstance(right,BigInt): return left%right
            n,d = _to_num(left),_to_num(right)
            if d==0: return float('nan')
            return math.fmod(n,d)
        if op == '**':
            if isinstance(left,BigInt) and isinstance(right,BigInt): return left**right
            return float(_to_num(left))**float(_to_num(right))
        if op == '==': return _eq(left, right)
        if op == '!=': return not _eq(left, right)
        if op == '===': return _seq(left, right)
        if op == '!==': return not _seq(left, right)
        if op == '<':
            r = _lt(left, right)
            return False if r is undefined else r
        if op == '>':
            r = _lt(right, left)
            return False if r is undefined else r
        if op == '<=':
            r = _lt(right, left)
            return False if r is True else True if r is False else False
        if op == '>=':
            r = _lt(left, right)
            return False if r is True else True if r is False else False
        if op == '<<': return float(_to_int32(left) << (_to_uint32(right)&31))
        if op == '>>': return float(_to_int32(left) >> (_to_uint32(right)&31))
        if op == '>>>': return float(_to_uint32(left) >> (_to_uint32(right)&31))
        if op == '&':
            if isinstance(left,BigInt) and isinstance(right,BigInt): return left&right
            return float(_to_int32(left) & _to_int32(right))
        if op == '|':
            if isinstance(left,BigInt) and isinstance(right,BigInt): return left|right
            return float(_to_int32(left) | _to_int32(right))
        if op == '^':
            if isinstance(left,BigInt) and isinstance(right,BigInt): return left^right
            return float(_to_int32(left) ^ _to_int32(right))
        if op == 'instanceof':
            if not _is_obj(right): raise JSThrow(_mk_err('TypeError',f"Right-hand side of 'instanceof' is not an object"))
            # Check Symbol.hasInstance
            hi = right._get(sym_hasInstance)
            if _callable(hi): return _to_bool(_call(hi, right, [left]))
            if not _is_obj(left): return False
            proto = right._get('prototype')
            if not _is_obj(proto): raise JSThrow(_mk_err('TypeError','instanceof: prototype is not an object'))
            o = left
            while o is not None:
                if o is proto: return True
                o = o._proto if _is_obj(o) else None
            return False
        if op == 'in':
            if not _is_obj(right): raise JSThrow(_mk_err('TypeError',f"Cannot use 'in' operator to search for '{left}' in {_to_str(right)}"))
            k = left
            if isinstance(k, str): pass
            elif isinstance(k, Symbol): pass
            elif isinstance(k, (int,float)) and not isinstance(k,bool):
                ki = int(k)
                if ki == k: k = str(ki)
                else: k = _to_str(k)
            else: k = _to_str(k)
            return right._has(k)
        return undefined

    def eval_unary(self, node, scope):
        op = node.op
        if op == '+': return _to_num(self.eval_expr(node.arg, scope))
        if op == '-':
            v = self.eval_expr(node.arg, scope)
            if isinstance(v, BigInt): return BigInt(-v.v)
            n = _to_num(v)
            return float(-n)
        if op == '!': return not _to_bool(self.eval_expr(node.arg, scope))
        if op == '~':
            v = self.eval_expr(node.arg, scope)
            if isinstance(v,BigInt): return BigInt(~v.v)
            return float(~_to_int32(v))
        return undefined

    def eval_update(self, node, scope):
        op = node.op
        val = self.eval_expr(node.arg, scope)

        if isinstance(val, BigInt):
            delta = BigInt(1)
            new_val = val + delta if op == '++' else val - delta
        else:
            n = _to_num(val)
            new_val = float(n+1) if op == '++' else float(n-1)

        self.assign_to(node.arg, new_val, scope)
        return val if not node.prefix else new_val

    def eval_delete(self, node, scope):
        arg = node.arg
        if arg.t == 'Member':
            obj = self.eval_expr(arg.obj, scope)
            return _to_obj(obj)._del(arg.name, scope.strict())
        elif arg.t == 'Index':
            obj = self.eval_expr(arg.obj, scope)
            key = self.eval_expr(arg.idx, scope)
            k = str(int(key)) if _is_num(key) and key==int(key) else _to_str(key)
            return _to_obj(obj)._del(k, scope.strict())
        elif arg.t == 'Ident':
            # delete var - in non-strict, returns true but doesn't work
            return True
        return True

    def make_function(self, node, closure_scope):
        name = node.name or ''
        params = node.params
        body = node.body
        is_gen = node.is_gen
        is_async = node.is_async

        interp = self

        if is_gen:
            def gen_fn(this, args, nt=None):
                fn_scope = Scope(closure_scope, strict=closure_scope.strict())
                fn_scope.this_val = this
                interp.bind_args(params, args, fn_scope)

                def gen_impl():
                    try:
                        interp.eval_func_body(body, fn_scope, is_gen=True)
                    except JSReturn as e:
                        return e.value

                return _make_python_generator(gen_impl, fn_scope, interp, body, params, args, closure_scope, this)
            fn = _make_fn(gen_fn, name, len(params))
            fn._is_gen = True
            fn._is_async = is_async
        elif is_async:
            def async_fn(this, args, nt=None):
                fn_scope = Scope(closure_scope, strict=closure_scope.strict())
                fn_scope.this_val = this
                interp.bind_args(params, args, fn_scope)

                p, res_fn, rej_fn = _make_promise()

                def run():
                    try:
                        result = interp.eval_func_body(body, fn_scope)
                        _resolve_promise(p, result)
                    except JSThrow as e:
                        _reject_promise(p, e.v)
                    except JSReturn as e:
                        _resolve_promise(p, e.value)

                run()
                _flush_microtasks()
                return p
            fn = _make_fn(async_fn, name, len(params))
            fn._is_async = True
        else:
            def regular_fn(this, args, nt=None):
                fn_scope = Scope(closure_scope, strict=closure_scope.strict())
                fn_scope.this_val = this
                interp.bind_args(params, args, fn_scope)
                return interp.eval_func_body(body, fn_scope)
            fn = _make_fn(regular_fn, name, len(params))

        fn._is_arrow = False
        fn._name = name

        # Set up prototype for non-arrow functions
        if not fn._is_arrow and not fn._is_gen:
            proto = JSObj(g_object_proto)
            proto._p['constructor'] = {'v':fn,'w':True,'e':False,'c':True}
            fn._p['prototype'] = {'v':proto,'w':True,'e':False,'c':False}

        if name:
            fn._name = name

        return fn

    def make_arrow(self, node, closure_scope):
        params = node.params
        body = node.body
        is_async = node.is_async
        interp = self

        if is_async:
            def async_arrow(this, args, nt=None):
                # this is from lexical scope
                fn_scope = Scope(closure_scope, strict=closure_scope.strict())
                fn_scope.this_val = closure_scope.get_this()
                interp.bind_args(params, args, fn_scope)
                p, res_fn, rej_fn = _make_promise()
                def run():
                    try:
                        result = interp.eval_func_body(body, fn_scope)
                        _resolve_promise(p, result)
                    except JSThrow as e: _reject_promise(p, e.v)
                    except JSReturn as e: _resolve_promise(p, e.value)
                run(); _flush_microtasks(); return p
            fn = _make_fn(async_arrow, '', len(params))
        else:
            def arrow_fn(this, args, nt=None):
                fn_scope = Scope(closure_scope, strict=closure_scope.strict())
                fn_scope.this_val = closure_scope.get_this()
                interp.bind_args(params, args, fn_scope)
                return interp.eval_func_body(body, fn_scope)
            fn = _make_fn(arrow_fn, '', len(params))

        fn._is_arrow = True
        fn._is_async = is_async
        return fn

    def bind_args(self, params, args, scope):
        for i, param in enumerate(params):
            if param.t == 'RestParam':
                rest_val = _make_arr(args[i:])
                self.bind_pattern(param.pattern, rest_val, scope, 'let')
                break
            elif param.t == 'Param':
                val = args[i] if i < len(args) else undefined
                if val is undefined and hasattr(param,'default') and param.default:
                    val = self.eval_expr(param.default, scope)
                self.bind_pattern(param.pattern, val, scope, 'let')
            else:
                val = args[i] if i < len(args) else undefined
                self.bind_pattern(param, val, scope, 'let')

        # 'arguments' object
        args_obj = JSObj(g_object_proto)
        for i, v in enumerate(args): args_obj._set(str(i), v)
        args_obj._set('length', float(len(args)))
        scope.def_v('arguments', args_obj)

    def eval_func_body(self, body, scope, is_gen=False):
        if body.t == 'Block':
            # It's a function body
            self._hoist_funcs(body.body, scope)
            self._hoist_vars(body.body, scope)
            for stmt in body.body:
                self.eval_stmt(stmt, scope)
        else:
            # Arrow function with expression body
            return self.eval_expr(body, scope)
        return undefined

    def eval_class(self, node, scope):
        superclass = None
        if hasattr(node,'superclass') and node.superclass:
            superclass = self.eval_expr(node.superclass, scope)

        proto = JSObj(superclass._get('prototype') if superclass and _is_obj(superclass) else g_object_proto)

        # Create constructor
        ctor_method = None
        for m in node.methods:
            if hasattr(m,'key') and hasattr(m.key,'name') and m.key.name == 'constructor' and not getattr(m,'is_static',False):
                ctor_method = m
                break

        class_scope = Scope(scope)
        if superclass: class_scope.__dict__['_super_class'] = superclass

        private_fields = {}  # name -> initial value expr

        def make_ctor(ctor_method=ctor_method, proto=proto, superclass=superclass, private_fields=private_fields):
            interp = self

            def ctor(this, args, nt=None):
                # Initialize private fields
                for fname, init_expr in private_fields.items():
                    if '_private' not in this.__dict__:
                        this.__dict__['_private'] = {}
                    this.__dict__['_private'][fname] = undefined

                if ctor_method:
                    fn = interp.make_function(ctor_method.func, class_scope)
                    fn_scope = Scope(class_scope, strict=True)
                    fn_scope.this_val = this
                    fn_scope.__dict__['_super_class'] = superclass
                    interp.bind_args(ctor_method.func.params, args, fn_scope)

                    try:
                        interp.eval_func_body(ctor_method.func.body, fn_scope)
                    except JSReturn as e:
                        if _is_obj(e.value): return e.value
                elif superclass:
