        if op == '??':
            left = self.eval_expr(node.left, scope)
            return left if left is not null and left is not undefined else self.eval_expr(node.right, scope)

        left = self.eval_expr(node.left, scope)
        right = self.eval_expr(node.right, scope)
        return self.apply_bin_op(op, left, right)

    def apply_bin_op(self, op, left, right):
        if op == '+':
            if isinstance(left, str) or isinstance(right, str):
                return _to_str(left) + _to_str(right)
            if isinstance(left, BigInt) and isinstance(right, BigInt): return left + right
            if isinstance(left, (JSObj,)) or isinstance(right, (JSObj,)):
                lp = _to_prim(left) if _is_obj(left) else left
                rp = _to_prim(right) if _is_obj(right) else right
                if isinstance(lp, str) or isinstance(rp, str): return _to_str(lp)+_to_str(rp)
                return _to_num(lp)+_to_num(rp)
            return _to_num(left)+_to_num(right)
        if op == '-':
            if isinstance(left,BigInt) and isinstance(right,BigInt): return left-right
            return _to_num(left)-_to_num(right)
        if op == '*':
            if isinstance(left,BigInt) and isinstance(right,BigInt): return left*right
            return _to_num(left)*_to_num(right)
        if op == '/':
            n,d = _to_num(left),_to_num(right)
            if d==0:
                if n==0: return float('nan')
                return math.copysign(float('inf'),n) if math.copysign(1,n)==math.copysign(1,d) else math.copysign(float('-inf'),n)
            return n/d
        if op == '%':
            if isinstance(left,BigInt) and isinstance(right,BigInt): return left%right
            n,d = _to_num(left),_to_num(right)
            if d==0: return float('nan')
            return math.fmod(n,d)
        if op == '**':
            if isinstance(left,BigInt) and isinstance(right,BigInt): return left**right
            return float(_to_num(left))**float(_to_num(right))
        if op == '==': return _eq(left, right)
        if op == '!=': return not _eq(left, right)
        if op == '===': return _seq(left, right)
        if op == '!==': return not _seq(left, right)
        if op == '<':
            r = _lt(left, right)
            return False if r is undefined else r
        if op == '>':
            r = _lt(right, left)
            return False if r is undefined else r
        if op == '<=':
            r = _lt(right, left)
            return False if r is True else True if r is False else False
        if op == '>=':
            r = _lt(left, right)
            return False if r is True else True if r is False else False
        if op == '<<': return float(_to_int32(left) << (_to_uint32(right)&31))
        if op == '>>': return float(_to_int32(left) >> (_to_uint32(right)&31))
        if op == '>>>': return float(_to_uint32(left) >> (_to_uint32(right)&31))
        if op == '&':
            if isinstance(left,BigInt) and isinstance(right,BigInt): return left&right
            return float(_to_int32(left) & _to_int32(right))
        if op == '|':
            if isinstance(left,BigInt) and isinstance(right,BigInt): return left|right
            return float(_to_int32(left) | _to_int32(right))
        if op == '^':
            if isinstance(left,BigInt) and isinstance(right,BigInt): return left^right
            return float(_to_int32(left) ^ _to_int32(right))
        if op == 'instanceof':
            if not _is_obj(right): raise JSThrow(_mk_err('TypeError',f"Right-hand side of 'instanceof' is not an object"))
            # Check Symbol.hasInstance
            hi = right._get(sym_hasInstance)
            if _callable(hi): return _to_bool(_call(hi, right, [left]))
            if not _is_obj(left): return False
            proto = right._get('prototype')
            if not _is_obj(proto): raise JSThrow(_mk_err('TypeError','instanceof: prototype is not an object'))
            o = left
            while o is not None:
                if o is proto: return True
                o = o._proto if _is_obj(o) else None
            return False
        if op == 'in':
            if not _is_obj(right): raise JSThrow(_mk_err('TypeError',f"Cannot use 'in' operator to search for '{left}' in {_to_str(right)}"))
            k = left
            if isinstance(k, str): pass
            elif isinstance(k, Symbol): pass
            elif isinstance(k, (int,float)) and not isinstance(k,bool):
                ki = int(k)
                if ki == k: k = str(ki)
                else: k = _to_str(k)
            else: k = _to_str(k)
            return right._has(k)
        return undefined

    def eval_unary(self, node, scope):
        op = node.op
        if op == '+': return _to_num(self.eval_expr(node.arg, scope))
        if op == '-':
            v = self.eval_expr(node.arg, scope)
            if isinstance(v, BigInt): return BigInt(-v.v)
            n = _to_num(v)
            return float(-n)
        if op == '!': return not _to_bool(self.eval_expr(node.arg, scope))
        if op == '~':
            v = self.eval_expr(node.arg, scope)
            if isinstance(v,BigInt): return BigInt(~v.v)
            return float(~_to_int32(v))
        return undefined

    def eval_update(self, node, scope):
        op = node.op
        val = self.eval_expr(node.arg, scope)

        if isinstance(val, BigInt):
            delta = BigInt(1)
            new_val = val + delta if op == '++' else val - delta
        else:
            n = _to_num(val)
            new_val = float(n+1) if op == '++' else float(n-1)

        self.assign_to(node.arg, new_val, scope)
        return val if not node.prefix else new_val

    def eval_delete(self, node, scope):
        arg = node.arg
        if arg.t == 'Member':
            obj = self.eval_expr(arg.obj, scope)
            return _to_obj(obj)._del(arg.name, scope.strict())
        elif arg.t == 'Index':
            obj = self.eval_expr(arg.obj, scope)
            key = self.eval_expr(arg.idx, scope)
            k = str(int(key)) if _is_num(key) and key==int(key) else _to_str(key)
            return _to_obj(obj)._del(k, scope.strict())
        elif arg.t == 'Ident':
            # delete var - in non-strict, returns true but doesn't work
            return True
        return True

    def make_function(self, node, closure_scope):
        name = node.name or ''
        params = node.params
        body = node.body
        is_gen = node.is_gen
        is_async = node.is_async

        interp = self

        if is_gen:
            def gen_fn(this, args, nt=None):
                fn_scope = Scope(closure_scope, strict=closure_scope.strict())
                fn_scope.this_val = this
                interp.bind_args(params, args, fn_scope)

                def gen_impl():
                    try:
                        interp.eval_func_body(body, fn_scope, is_gen=True)
                    except JSReturn as e:
                        return e.value

                return _make_python_generator(gen_impl, fn_scope, interp, body, params, args, closure_scope, this)
            fn = _make_fn(gen_fn, name, len(params))
            fn._is_gen = True
            fn._is_async = is_async
        elif is_async:
            def async_fn(this, args, nt=None):
                fn_scope = Scope(closure_scope, strict=closure_scope.strict())
                fn_scope.this_val = this
                interp.bind_args(params, args, fn_scope)

                p, res_fn, rej_fn = _make_promise()

                def run():
                    try:
                        result = interp.eval_func_body(body, fn_scope)
                        _resolve_promise(p, result)
                    except JSThrow as e:
                        _reject_promise(p, e.v)
                    except JSReturn as e:
                        _resolve_promise(p, e.value)

                run()
                _flush_microtasks()
                return p
            fn = _make_fn(async_fn, name, len(params))
            fn._is_async = True
        else:
            def regular_fn(this, args, nt=None):
                fn_scope = Scope(closure_scope, strict=closure_scope.strict())
                fn_scope.this_val = this
                interp.bind_args(params, args, fn_scope)
                return interp.eval_func_body(body, fn_scope)
            fn = _make_fn(regular_fn, name, len(params))

        fn._is_arrow = False
        fn._name = name

        # Set up prototype for non-arrow functions
        if not fn._is_arrow and not fn._is_gen:
            proto = JSObj(g_object_proto)
            proto._p['constructor'] = {'v':fn,'w':True,'e':False,'c':True}
            fn._p['prototype'] = {'v':proto,'w':True,'e':False,'c':False}

        if name:
            fn._name = name

        return fn

    def make_arrow(self, node, closure_scope):
        params = node.params
        body = node.body
        is_async = node.is_async
        interp = self

        if is_async:
            def async_arrow(this, args, nt=None):
                # this is from lexical scope
                fn_scope = Scope(closure_scope, strict=closure_scope.strict())
                fn_scope.this_val = closure_scope.get_this()
                interp.bind_args(params, args, fn_scope)
                p, res_fn, rej_fn = _make_promise()
                def run():
                    try:
                        result = interp.eval_func_body(body, fn_scope)
                        _resolve_promise(p, result)
                    except JSThrow as e: _reject_promise(p, e.v)
                    except JSReturn as e: _resolve_promise(p, e.value)
                run(); _flush_microtasks(); return p
            fn = _make_fn(async_arrow, '', len(params))
        else:
            def arrow_fn(this, args, nt=None):
                fn_scope = Scope(closure_scope, strict=closure_scope.strict())
                fn_scope.this_val = closure_scope.get_this()
                interp.bind_args(params, args, fn_scope)
                return interp.eval_func_body(body, fn_scope)
            fn = _make_fn(arrow_fn, '', len(params))

        fn._is_arrow = True
        fn._is_async = is_async
        return fn

    def bind_args(self, params, args, scope):
        for i, param in enumerate(params):
            if param.t == 'RestParam':
                rest_val = _make_arr(args[i:])
                self.bind_pattern(param.pattern, rest_val, scope, 'let')
                break
            elif param.t == 'Param':
                val = args[i] if i < len(args) else undefined
                if val is undefined and hasattr(param,'default') and param.default:
                    val = self.eval_expr(param.default, scope)
                self.bind_pattern(param.pattern, val, scope, 'let')
            else:
                val = args[i] if i < len(args) else undefined
                self.bind_pattern(param, val, scope, 'let')

        # 'arguments' object
        args_obj = JSObj(g_object_proto)
        for i, v in enumerate(args): args_obj._set(str(i), v)
        args_obj._set('length', float(len(args)))
        scope.def_v('arguments', args_obj)

    def eval_func_body(self, body, scope, is_gen=False):
        if body.t == 'Block':
            # It's a function body
            self._hoist_funcs(body.body, scope)
            self._hoist_vars(body.body, scope)
            for stmt in body.body:
                self.eval_stmt(stmt, scope)
        else:
            # Arrow function with expression body
            return self.eval_expr(body, scope)
        return undefined

    def eval_class(self, node, scope):
        superclass = None
        if hasattr(node,'superclass') and node.superclass:
            superclass = self.eval_expr(node.superclass, scope)

        proto = JSObj(superclass._get('prototype') if superclass and _is_obj(superclass) else g_object_proto)

        # Create constructor
        ctor_method = None
        for m in node.methods:
            if hasattr(m,'key') and hasattr(m.key,'name') and m.key.name == 'constructor' and not getattr(m,'is_static',False):
                ctor_method = m
                break

        class_scope = Scope(scope)
        if superclass: class_scope.__dict__['_super_class'] = superclass

        private_fields = {}  # name -> initial value expr

        def make_ctor(ctor_method=ctor_method, proto=proto, superclass=superclass, private_fields=private_fields):
            interp = self

            def ctor(this, args, nt=None):
                # Initialize private fields
                for fname, init_expr in private_fields.items():
                    if '_private' not in this.__dict__:
                        this.__dict__['_private'] = {}
                    this.__dict__['_private'][fname] = undefined

                if ctor_method:
                    fn = interp.make_function(ctor_method.func, class_scope)
                    fn_scope = Scope(class_scope, strict=True)
                    fn_scope.this_val = this
                    fn_scope.__dict__['_super_class'] = superclass
                    interp.bind_args(ctor_method.func.params, args, fn_scope)

                    try:
                        interp.eval_func_body(ctor_method.func.body, fn_scope)
                    except JSReturn as e:
                        if _is_obj(e.value): return e.value
                elif superclass:
                    _construct(superclass, args, this)

                # Initialize instance fields
                for m in node.methods:
                    if m.t == 'ClassField' and not getattr(m,'is_static',False):
                        key = interp.eval_prop_key(m.key, class_scope)
                        val = interp.eval_expr(m.init, class_scope) if m.init else undefined
                        if hasattr(m,'is_private') and m.is_private:
                            if '_private' not in this.__dict__: this.__dict__['_private'] = {}
                            this.__dict__['_private'][key] = val
                        else:
                            k = key if isinstance(key,(str,Symbol)) else _to_str(key)
                            this._p[k] = {'v':val,'w':True,'e':True,'c':True}

                return this
            return ctor

        cls_ctor = make_ctor()
        cls_obj = _make_fn(cls_ctor, node.name or '', 0, False)
        cls_obj._ctor = cls_ctor
        cls_obj._p['prototype'] = {'v':proto,'w':False,'e':False,'c':False}
        cls_obj._is_class = True
        proto._p['constructor'] = {'v':cls_obj,'w':True,'e':False,'c':True}

        # Process methods
        for m in node.methods:
            if m.t == 'ClassMethod':
                key = self.eval_prop_key(m.key, class_scope)
                is_static = getattr(m,'is_static',False)
                is_private = getattr(m,'is_private',False)
                kind = getattr(m,'kind','method')

                fn = self.make_function(m.func, class_scope)
                fn._home_object = cls_obj if is_static else proto

                if is_private and not is_static:
                    private_fields[key] = None

                target = cls_obj if is_static else proto
                k = key if isinstance(key,(str,Symbol)) else _to_str(key)

                if kind == 'get':
                    existing = target._p.get(k, {})
                    d = {'get':fn,'e':False,'c':True}
                    if 'set' in existing: d['set'] = existing['set']
                    target._p[k] = d
                elif kind == 'set':
                    existing = target._p.get(k, {})
                    d = {'set':fn,'e':False,'c':True}
                    if 'get' in existing: d['get'] = existing['get']
                    target._p[k] = d
                else:
                    target._p[k] = {'v':fn,'w':True,'e':False,'c':True}

            elif m.t == 'ClassField':
                if getattr(m,'is_static',False):
                    key = self.eval_prop_key(m.key, class_scope)
                    val = self.eval_expr(m.init, class_scope) if m.init else undefined
                    k = key if isinstance(key,(str,Symbol)) else _to_str(key)
                    cls_obj._p[k] = {'v':val,'w':True,'e':True,'c':True}
                elif getattr(m,'is_private',False):
                    key = self.eval_prop_key(m.key, class_scope)
                    private_fields[key] = m.init

            elif m.t == 'StaticBlock':
                static_scope = Scope(class_scope)
                static_scope.this_val = cls_obj
                for s in m.body.body: self.eval_stmt(s, static_scope)

        # Symbol.hasInstance
        if superclass:
            proto._proto = superclass._get('prototype') if _is_obj(superclass._get('prototype')) else g_object_proto

        if node.name and hasattr(scope,'def_l'):
            pass  # handled by caller

        return cls_obj

