                mod = self.load_module(src, scope)
                p = JSObj(g_promise_proto); p._cls='Promise'
                p.__dict__['_state']='fulfilled'; p.__dict__['_value']=mod; p.__dict__['_callbacks']=[]
                return p
            except JSThrow as e:
