        if t.t=='ID' or (t.t.startswith('KW:') and t.t not in ('KW:null','KW:true','KW:false','KW:this')):
            name=self.ts.next().v
        func=self._func_rest(name,is_gen,async_)
        return Node('FuncDecl',line=ln,func=func)

    def _func_rest(self, name, is_gen=False, is_async=False):
        ln=self.ts.peek().line
        self.ts.expect('('); params=self._params(); self.ts.expect(')')
        prev_gen,prev_async=self._in_gen,self._in_async
        self._in_func+=1; self._in_gen=1 if is_gen else 0; self._in_async=1 if is_async else 0
        body=self._block()
        self._in_func-=1; self._in_gen=prev_gen; self._in_async=prev_async
        return Node('Func',line=ln,name=name,params=params,body=body,is_gen=is_gen,is_async=is_async)

    def _params(self):
        params=[]
        while self.ts.peek().t!=')':
            if self.ts.peek().t=='...':
                self.ts.next(); rest=self._binding_pattern(); params.append(Node('RestParam',pattern=rest)); break
            pat=self._binding_pattern(); default=None
            if self.ts.match('='): default=self._assign_expr()
            params.append(Node('Param',pattern=pat,default=default))
            if not self.ts.match(','): break
        return params

    def _class_decl(self):
        ln=self.ts.peek().line; self.ts.next()
        name=None
        if self.ts.peek().t=='ID': name=self.ts.next().v
        superclass=None
        if self.ts.match_kw('extends'): superclass=self._left_expr()
        self.ts.expect('{')
        methods=[]
        while self.ts.peek().t!='}':
            if self.ts.peek().t==';': self.ts.next(); continue
            m=self._class_member()
            if m: methods.append(m)
        self.ts.expect('}')
        return Node('ClassDecl',line=ln,name=name,superclass=superclass,methods=methods)

    def _class_member(self):
        ln=self.ts.peek().line
        is_static=False
        if self.ts.is_kw('static'):
            self.ts.next(); is_static=True
            if self.ts.peek().t=='{':
                block=self._block(); return Node('StaticBlock',line=ln,body=block)

        is_private=False; kind='method'; is_async=False; is_gen=False

        t=self.ts.peek()
        if t.t in ('KW:get','KW:set') or (t.t=='ID' and t.v in ('get','set')):
            nxt=self.ts.peek(1)
            if nxt.t not in ('(','=',';','}','EOF',','):
                kind=t.v; self.ts.next(); t=self.ts.peek()
        if t.t=='KW:async' and not self.ts.nl_before_current() and self.ts.peek(1).t!='(':
            self.ts.next(); is_async=True; t=self.ts.peek()
        if t.t=='*': self.ts.next(); is_gen=True; t=self.ts.peek()

        if t.t=='#!':
            self.ts.next(); pname='#'+self.ts.next().v; is_private=True
            key_node=Node('PrivKey',name=pname)
        else:
            key_node=self._prop_name()

        if self.ts.peek().t!='(':
            init=None
            if self.ts.match('='): init=self._assign_expr()
            self.ts.semi()
            return Node('ClassField',line=ln,key=key_node,init=init,is_static=is_static,is_private=is_private)

        self.ts.expect('('); params=self._params(); self.ts.expect(')')
        prev_gen,prev_async=self._in_gen,self._in_async
        self._in_func+=1; self._in_gen=1 if is_gen else 0; self._in_async=1 if is_async else 0
        body=self._block()
        self._in_func-=1; self._in_gen=prev_gen; self._in_async=prev_async
        func=Node('Func',line=ln,name=None,params=params,body=body,is_gen=is_gen,is_async=is_async)
        return Node('ClassMethod',line=ln,key=key_node,func=func,kind=kind,is_static=is_static,is_private=is_private)

    def _if(self):
        ln=self.ts.peek().line; self.ts.next()
        self.ts.expect('('); test=self._expr(); self.ts.expect(')')
        then=self._stmt(); else_=None
        if self.ts.match_kw('else'): else_=self._stmt()
        return Node('If',line=ln,test=test,then=then,else_=else_)

    def _while(self):
        ln=self.ts.peek().line; self.ts.next()
        self.ts.expect('('); test=self._expr(); self.ts.expect(')')
        body=self._stmt()
        return Node('While',line=ln,test=test,body=body)

    def _do_while(self):
        ln=self.ts.peek().line; self.ts.next()
        body=self._stmt()
        self.ts.expect_kw('while'); self.ts.expect('('); test=self._expr(); self.ts.expect(')')
        self.ts.semi()
        return Node('DoWhile',line=ln,test=test,body=body)

    def _for(self):
        ln=self.ts.peek().line; self.ts.next()
        is_await=bool(self.ts.match_kw('await'))
        self.ts.expect('(')

        init=None; kind=None; pat=None
        t=self.ts.peek()
        if t.t in ('KW:var','KW:let','KW:const'):
            kind=t.v[3:]; self.ts.next()
            pat=self._binding_pattern()
            if self.ts.is_kw('of'):
                self.ts.next(); iter_=self._assign_expr(); self.ts.expect(')')
                body=self._stmt()
                return Node('ForOf',line=ln,is_await=is_await,kind=kind,pat=pat,iter=iter_,body=body)
            if self.ts.match_kw('in'):
                iter_=self._expr(); self.ts.expect(')')
                body=self._stmt()
                return Node('ForIn',line=ln,kind=kind,pat=pat,iter=iter_,body=body)
            init_val=None
            if self.ts.match('='): init_val=self._assign_expr()
            decls=[Node('Decl',pattern=pat,init=init_val)]
            while self.ts.match(','):
                p2=self._binding_pattern(); v2=None
                if self.ts.match('='): v2=self._assign_expr()
                decls.append(Node('Decl',pattern=p2,init=v2))
            init=Node('VarDecl',line=ln,kind=kind,decls=decls)
        elif t.t!=';':
            expr=self._assign_expr()
            if self.ts.is_kw('of'):
                self.ts.next(); iter_=self._assign_expr(); self.ts.expect(')')
                body=self._stmt()
                return Node('ForOf',line=ln,is_await=is_await,kind=None,pat=expr,iter=iter_,body=body)
            if self.ts.match_kw('in'):
                iter_=self._expr(); self.ts.expect(')')
                body=self._stmt()
                return Node('ForIn',line=ln,kind=None,pat=expr,iter=iter_,body=body)
            if self.ts.peek().t==',':
                self.ts.next(); rest=[expr]+[self._assign_expr()]
                while self.ts.match(','): rest.append(self._assign_expr())
                init=Node('SeqExpr',exprs=rest)
            else: init=expr

        self.ts.expect(';')
        test=None
        if self.ts.peek().t!=';': test=self._expr()
        self.ts.expect(';')
        update=None
        if self.ts.peek().t!=')': update=self._expr()
        self.ts.expect(')')
        body=self._stmt()
        return Node('For',line=ln,init=init,test=test,update=update,body=body)

    def _try(self):
        ln=self.ts.peek().line; self.ts.next()
        body=self._block(); catch_=None; finally_=None
        if self.ts.match_kw('catch'):
            param=None
            if self.ts.match('('):
                param=self._binding_pattern(); self.ts.expect(')')
            catch_body=self._block()
            catch_=Node('Catch',param=param,body=catch_body)
        if self.ts.match_kw('finally'):
            finally_=self._block()
        return Node('Try',line=ln,body=body,catch_=catch_,finally_=finally_)

    def _switch(self):
        ln=self.ts.peek().line; self.ts.next()
        self.ts.expect('('); disc=self._expr(); self.ts.expect(')')
        self.ts.expect('{'); cases=[]
        while self.ts.peek().t!='}':
            if self.ts.match_kw('case'):
                test=self._expr(); self.ts.expect(':')
                stmts=[]
                while self.ts.peek().t not in ('}',) and not self.ts.is_kw('case','default'):
                    s=self._stmt()
                    if s: stmts.append(s)
                cases.append(Node('Case',test=test,body=stmts))
            elif self.ts.match_kw('default'):
                self.ts.expect(':'); stmts=[]
                while self.ts.peek().t not in ('}',) and not self.ts.is_kw('case','default'):
                    s=self._stmt()
                    if s: stmts.append(s)
                cases.append(Node('Default',body=stmts))
            else: break
        self.ts.expect('}')
        return Node('Switch',line=ln,disc=disc,cases=cases)

    def _with(self):
        ln=self.ts.peek().line; self.ts.next()
        self.ts.expect('('); obj=self._expr(); self.ts.expect(')')
        body=self._stmt()
        return Node('With',line=ln,obj=obj,body=body)

    def _import_stmt(self):
        ln=self.ts.peek().line; self.ts.next()
        if self.ts.peek().t=='STR':
            src=self.ts.next().v; self.ts.semi()
            return Node('Import',line=ln,specifiers=[],src=src)
        specs=[]; src=None
        if self.ts.peek().t=='ID':
            name=self.ts.next().v; specs.append(Node('ImportDefault',name=name))
        if self.ts.match(',') or not specs:
            if self.ts.peek().t=='*':
                self.ts.next(); self.ts.expect_kw('as'); name=self.ts.next().v
                specs.append(Node('ImportNS',name=name))
            elif self.ts.peek().t=='{':
                self.ts.next()
                while self.ts.peek().t!='}':
                    orig=self.ts.next().v; local=orig
                    if self.ts.match_kw('as'): local=self.ts.next().v
                    specs.append(Node('ImportSpec',orig=orig,local=local))
                    if not self.ts.match(','): break
                self.ts.expect('}')
        self.ts.expect_kw('from'); src=self.ts.next().v
        self.ts.semi()
        return Node('Import',line=ln,specifiers=specs,src=src)

    def _export_stmt(self):
        ln=self.ts.peek().line; self.ts.next()
        if self.ts.match_kw('default'):
            if self.ts.is_kw('function'): decl=self._func_decl(); return Node('ExportDefault',line=ln,decl=decl)
            if self.ts.is_kw('class'): decl=self._class_decl(); return Node('ExportDefault',line=ln,decl=decl)
            if self.ts.is_kw('async') and self.ts.peek(1).t=='KW:function': decl=self._func_decl(async_=True); return Node('ExportDefault',line=ln,decl=decl)
            expr=self._assign_expr(); self.ts.semi()
            return Node('ExportDefault',line=ln,expr=expr)
        if self.ts.match('*'):
            src=None
            if self.ts.match_kw('from'): src=self.ts.next().v
            self.ts.semi(); return Node('ExportAll',line=ln,src=src)
        if self.ts.peek().t=='{':
            self.ts.next(); specs=[]
            while self.ts.peek().t!='}':
                local=self.ts.next().v; exported=local
                if self.ts.match_kw('as'): exported=self.ts.next().v
                specs.append(Node('ExportSpec',local=local,exported=exported))
                if not self.ts.match(','): break
            self.ts.expect('}')
            src=None
            if self.ts.match_kw('from'): src=self.ts.next().v
            self.ts.semi(); return Node('ExportNamed',line=ln,specs=specs,src=src)
        if self.ts.is_kw('var','let','const'): decl=self._var_decl(self.ts.peek().v[3:]); return Node('ExportDecl',line=ln,decl=decl)
        if self.ts.is_kw('function'): decl=self._func_decl(); return Node('ExportDecl',line=ln,decl=decl)
        if self.ts.is_kw('class'): decl=self._class_decl(); return Node('ExportDecl',line=ln,decl=decl)
        if self.ts.is_kw('async'): decl=self._func_decl(async_=True); return Node('ExportDecl',line=ln,decl=decl)
        expr=self._expr(); self.ts.semi()
        return Node('ExportDecl',line=ln,decl=Node('ExprStmt',expr=expr))

    # ===== Expressions =====

    def _expr(self):
        exprs=[self._assign_expr()]
        while self.ts.match(','):
            exprs.append(self._assign_expr())
        if len(exprs)==1: return exprs[0]
        return Node('SeqExpr',exprs=exprs)

    def _assign_expr(self):
        ln,cl=self.ts.peek().line,self.ts.peek().col

        if self._in_gen and self.ts.is_kw('yield'):
            self.ts.next(); delegate=bool(self.ts.match('*')); val=None
            if not self.ts.nl_before_current() and self.ts.peek().t not in (';','}',')','EOF',']',','):
                val=self._assign_expr()
            return Node('Yield',line=ln,value=val,delegate=delegate)

        if self._in_async and self.ts.is_kw('await') and not self.ts.nl_before_current():
            if self.ts.peek(1).t not in (';','}',')','EOF',']',','):
                self.ts.next(); arg=self._unary()
                return Node('Await',line=ln,arg=arg)

        # Check for async arrow: async (params) => or async id =>
        if self.ts.is_kw('async') and not self.ts.nl_before_current():
            nxt=self.ts.peek(1)
            if nxt.t=='(':
                saved=self.ts.pos; self.ts.next(); self.ts.next()
                try:
                    params=self._params(); self.ts.expect(')')
                    if self.ts.peek().t=='=>':
                        self.ts.next()
                        prev_async=self._in_async; self._in_async=1
                        body=self._arrow_body(True)
                        self._in_async=prev_async
                        return Node('Arrow',line=ln,params=params,body=body,is_async=True)
                except: pass
                self.ts.pos=saved
            elif nxt.t=='ID':
                saved=self.ts.pos; self.ts.next(); name=self.ts.next().v
                if self.ts.peek().t=='=>' and not self.ts.nl_before_current():
                    self.ts.next()
                    prev_async=self._in_async; self._in_async=1
                    body=self._arrow_body(True)
                    self._in_async=prev_async
                    params=[Node('Param',pattern=Node('Ident',name=name),default=None)]
                    return Node('Arrow',line=ln,params=params,body=body,is_async=True)
                self.ts.pos=saved

        left=self._cond_expr()

        # Arrow with single param
        if left.t=='Ident' and self.ts.peek().t=='=>' and not self.ts.nl_before_current():
            self.ts.next()
            body=self._arrow_body(False)
            params=[Node('Param',pattern=left,default=None)]
            return Node('Arrow',line=ln,params=params,body=body,is_async=False)

        # Check for arrow with paren-wrapped params
        # (already handled in primary - check for => after paren expr)
        if left.t=='Paren' and self.ts.peek().t=='=>':
            self.ts.next()
            params=self._expr_to_params(left.expr)
            body=self._arrow_body(False)
            return Node('Arrow',line=ln,params=params,body=body,is_async=False)

        ops=('=','+=','-=','*=','/=','%=','**=','&=','|=','^=','<<=','>>=','>>>=','&&=','||=','??=')
        t=self.ts.peek()
        if t.t in ops:
            op=t.t; self.ts.next(); right=self._assign_expr()
            return Node('Assign',line=ln,op=op,left=left,right=right)
        return left

    def _arrow_body(self, is_async):
        self._in_func+=1
        if self.ts.peek().t=='{':
            body=self._block()
        else:
            body=self._assign_expr()
        self._in_func-=1
        return body

    def _expr_to_params(self, expr):
        if expr.t=='SeqExpr': return [self._e2p(e) for e in expr.exprs]
        return [self._e2p(expr)]

    def _e2p(self, e):
        if e.t=='Ident': return Node('Param',pattern=e,default=None)
        if e.t=='Assign' and e.op=='=': return Node('Param',pattern=e.left,default=e.right)
        if e.t=='Spread': return Node('RestParam',pattern=e.arg)
        return Node('Param',pattern=e,default=None)

    def _cond_expr(self):
        ln=self.ts.peek().line; test=self._nullish()
        if self.ts.match('?'):
            then=self._assign_expr(); self.ts.expect(':'); else_=self._assign_expr()
            return Node('Cond',line=ln,test=test,then=then,else_=else_)
        return test

    def _nullish(self):
        ln=self.ts.peek().line; left=self._or()
        while self.ts.match('??'):
            right=self._or(); left=Node('Bin',line=ln,op='??',left=left,right=right)
        return left
    def _or(self):
        ln=self.ts.peek().line; left=self._and()
        while self.ts.match('||'):
            right=self._and(); left=Node('Bin',line=ln,op='||',left=left,right=right)
        return left
    def _and(self):
        ln=self.ts.peek().line; left=self._bitor()
        while self.ts.match('&&'):
            right=self._bitor(); left=Node('Bin',line=ln,op='&&',left=left,right=right)
        return left
    def _bitor(self):
        ln=self.ts.peek().line; left=self._bitxor()
        while self.ts.peek().t=='|': self.ts.next(); right=self._bitxor(); left=Node('Bin',line=ln,op='|',left=left,right=right)
        return left
    def _bitxor(self):
        ln=self.ts.peek().line; left=self._bitand()
        while self.ts.peek().t=='^': self.ts.next(); right=self._bitand(); left=Node('Bin',line=ln,op='^',left=left,right=right)
        return left
    def _bitand(self):
        ln=self.ts.peek().line; left=self._eq()
        while self.ts.peek().t=='&': self.ts.next(); right=self._eq(); left=Node('Bin',line=ln,op='&',left=left,right=right)
        return left
    def _eq(self):
        ln=self.ts.peek().line; left=self._rel()
        while True:
            t=self.ts.peek()
            if t.t in ('==','!=','===','!=='): op=t.t; self.ts.next(); right=self._rel(); left=Node('Bin',line=ln,op=op,left=left,right=right)
            else: break
        return left
    def _rel(self):
        ln=self.ts.peek().line; left=self._shift()
        while True:
            t=self.ts.peek()
            if t.t in ('<','>','<=','>='): op=t.t; self.ts.next(); right=self._shift(); left=Node('Bin',line=ln,op=op,left=left,right=right)
            elif t.t=='KW:instanceof': self.ts.next(); right=self._shift(); left=Node('Bin',line=ln,op='instanceof',left=left,right=right)
            elif t.t=='KW:in': self.ts.next(); right=self._shift(); left=Node('Bin',line=ln,op='in',left=left,right=right)
            else: break
        return left
    def _shift(self):
        ln=self.ts.peek().line; left=self._add()
        while True:
            t=self.ts.peek()
            if t.t in ('<<','>>','>>>'): op=t.t; self.ts.next(); right=self._add(); left=Node('Bin',line=ln,op=op,left=left,right=right)
            else: break
        return left
    def _add(self):
        ln=self.ts.peek().line; left=self._mult()
        while True:
            t=self.ts.peek()
            if t.t in ('+','-'): op=t.t; self.ts.next(); right=self._mult(); left=Node('Bin',line=ln,op=op,left=left,right=right)
            else: break
        return left
    def _mult(self):
        ln=self.ts.peek().line; left=self._exp()
        while True:
            t=self.ts.peek()
            if t.t in ('*','/',  '%'): op=t.t; self.ts.next(); right=self._exp(); left=Node('Bin',line=ln,op=op,left=left,right=right)
            else: break
        return left
    def _exp(self):
        ln=self.ts.peek().line; left=self._unary()
        if self.ts.match('**'): right=self._exp(); return Node('Bin',line=ln,op='**',left=left,right=right)
        return left
    def _unary(self):
        ln,cl=self.ts.peek().line,self.ts.peek().col; t=self.ts.peek()
        if t.t in ('!','~','+','-'): op=t.t; self.ts.next(); return Node('Unary',line=ln,op=op,arg=self._unary())
        if t.t=='KW:typeof': self.ts.next(); return Node('Typeof',line=ln,arg=self._unary())
        if t.t=='KW:void': self.ts.next(); return Node('Void',line=ln,arg=self._unary())
        if t.t=='KW:delete': self.ts.next(); return Node('Delete',line=ln,arg=self._unary())
        if t.t=='KW:await' and self._in_async: self.ts.next(); return Node('Await',line=ln,arg=self._unary())
        if t.t=='++': self.ts.next(); return Node('Update',line=ln,op='++',prefix=True,arg=self._unary())
        if t.t=='--': self.ts.next(); return Node('Update',line=ln,op='--',prefix=True,arg=self._unary())
        return self._postfix()
    def _postfix(self):
        ln=self.ts.peek().line; expr=self._call_expr()
        if not self.ts.nl_before_current():
            if self.ts.peek().t=='++': self.ts.next(); return Node('Update',line=ln,op='++',prefix=False,arg=expr)
            if self.ts.peek().t=='--': self.ts.next(); return Node('Update',line=ln,op='--',prefix=False,arg=expr)
        return expr

    def _call_expr(self):
        ln=self.ts.peek().line
        if self.ts.is_kw('new') and self.ts.peek(1).t!='.' : return self._new_expr()
        expr=self._left_expr()
        while True:
            t=self.ts.peek()
            if t.t=='(':
                self.ts.next(); args=self._args(); self.ts.expect(')')
                expr=Node('Call',line=t.line,callee=expr,args=args,optional=False)
            elif t.t=='.':
                self.ts.next(); name=self.ts.next().v
                expr=Node('Member',line=t.line,obj=expr,name=name,optional=False)
            elif t.t=='[':
                self.ts.next(); idx=self._expr(); self.ts.expect(']')
                expr=Node('Index',line=t.line,obj=expr,idx=idx,optional=False)
            elif t.t=='?.':
                self.ts.next()
                nt=self.ts.peek()
                if nt.t=='(':
                    self.ts.next(); args=self._args(); self.ts.expect(')')
                    expr=Node('Call',line=t.line,callee=expr,args=args,optional=True)
                elif nt.t=='[':
                    self.ts.next(); idx=self._expr(); self.ts.expect(']')
                    expr=Node('Index',line=t.line,obj=expr,idx=idx,optional=True)
                else:
                    name=self.ts.next().v
                    expr=Node('Member',line=t.line,obj=expr,name=name,optional=True)
            elif t.t=='TMPL_FULL':
                val=t.v; self.ts.next()
                parts=[val]; exprs_nodes=[]
                expr=Node('TaggedTemplate',line=t.line,tag=expr,parts=parts,exprs=exprs_nodes)
            elif t.t=='TMPL_HEAD':
                parts,exprs_nodes=self._template_rest(t.v)
                expr=Node('TaggedTemplate',line=t.line,tag=expr,parts=parts,exprs=exprs_nodes)
            else: break
        return expr

    def _template_rest(self, head):
        parts=[head]; exprs=[]
        self.ts.next()  # consume TMPL_HEAD
        while True:
            e=self._assign_expr(); exprs.append(e)
            t=self.ts.peek()
            if t.t=='TMPL_FULL': parts.append(t.v); self.ts.next(); break
            elif t.t=='TMPL_HEAD': parts.append(t.v); self.ts.next()
            else: parts.append(''); break
        return parts, exprs

    def _new_expr(self):
        ln=self.ts.peek().line; self.ts.next()
        if self.ts.peek().t=='.':
            self.ts.next(); self.ts.next(); return Node('NewTarget',line=ln)
        callee=self._left_expr_no_call()
        while True:
            t=self.ts.peek()
