def _print_error(val, filename):
    """Print error to stderr like QuickJS"""
    if _is_obj(val) and _is_err(val):
        stk = val._p.get('stack',{}).get('v')
        if isinstance(stk, str):
            sys.stderr.write(stk)
            if not stk.endswith('\n'): sys.stderr.write('\n')
        else:
            nm = val._p.get('name',{}).get('v','Error')
            msg = val._p.get('message',{}).get('v','')
            if msg: sys.stderr.write(f'{nm}: {msg}\n')
            else: sys.stderr.write(f'{nm}\n')
    else:
        sys.stderr.write(_inspect(val)+'\n')

_unhandled_rejections_pending = []

def _check_unhandled_rejections():
    # Check for unhandled promise rejections
    for p, reason in list(_pending_rejections):
        if _is_obj(p) and p._cls=='Promise' and p.__dict__.get('_state')=='rejected':
            if not p.__dict__.get('_handled', False):
                sys.stderr.write('Possibly unhandled promise rejection: ')
                _print_error(reason, '')
                _pending_rejections.remove((p, reason))
                return 1
    _pending_rejections.clear()
    return 0

