_global_interp = None

def _eval_source(src, filename, strict, module, scope=None):
    global _global_interp
    try:
        ast = parse_js(src, filename, module)
    except SyntaxError as e:
        msg = str(e)
        # Format like QuickJS
        line = 1
        col = 1
        m = re.search(r'line (\d+):(\d+)', msg)
        if m: line,col = int(m.group(1)),int(m.group(2))
        else:
            m2 = re.search(r'line (\d+)', msg)
            if m2: line = int(m2.group(1))
        raise JSThrow(_make_syntax_error(str(e), filename, line, col))

    if _global_interp is None:
        _global_interp = Interpreter(g_global, filename, module)

    interp = _global_interp
    old_filename = interp.filename
    interp.filename = filename

    try:
        if scope is not None:
            # Use existing scope for direct eval
            return interp.eval_program(ast, scope)

        sc = Scope(strict=strict or module)
        sc.this_val = g_global
        if module:
            meta = JSObj(g_object_proto)
            meta._set('url', 'file://'+os.path.abspath(filename))
            sc.def_v('__import_meta__', meta)

        return interp.eval_program(ast, sc)
    finally:
        interp.filename = old_filename

def _make_syntax_error(msg, filename, line, col):
    # Format like QuickJS: "SyntaxError: message\n    at filename:line:col\n"
    o = _mk_err('SyntaxError', _clean_syntax_msg(msg))
    stack = f"SyntaxError: {_clean_syntax_msg(msg)}\n    at {filename}:{line}:{col}\n"
    o._p['stack'] = {'v':stack,'w':True,'e':False,'c':True}
    return o

def _clean_syntax_msg(msg):
    # Extract meaningful part of syntax error
    m = re.match(r"Expected '(.+)' got '(.+)' \(.+\) at line \d+:\d+", msg)
    if m:
        exp,got = m.group(1),m.group(2)
        if exp == ';': return f"expecting ';'"
        return f"unexpected token in expression: '{got}'"
    if 'Unexpected token' in msg:
        m2 = re.search(r"Unexpected token '(.+)'", msg)
        if m2: return f"unexpected token in expression: '{m2.group(1)}'"
    return msg

# ===== Main entry point =====
def run_js(source, filename='<cmdline>', module=False, strict=False):
    """Run JavaScript source code"""
    if g_global is None: _init_globals()

    try:
        _eval_source(source, filename, strict, module)
        _flush_microtasks()
    except JSThrow as e:
        # Unhandled exception
        _print_error(e.v, filename)
        return 1
    except JSReturn as e:
        pass

    # Check for pending unhandled rejections
    _check_unhandled_rejections()

    return 0

def _print_error(val, filename):
    """Print error to stderr like QuickJS"""
    if _is_obj(val) and _is_err(val):
        stk = val._p.get('stack',{}).get('v')
        if isinstance(stk, str):
            sys.stderr.write(stk)
            if not stk.endswith('\n'): sys.stderr.write('\n')
        else:
            nm = val._p.get('name',{}).get('v','Error')
            msg = val._p.get('message',{}).get('v','')
            if msg: sys.stderr.write(f'{nm}: {msg}\n')
            else: sys.stderr.write(f'{nm}\n')
    else:
        sys.stderr.write(_inspect(val)+'\n')

_unhandled_rejections_pending = []

def _check_unhandled_rejections():
    # Check for unhandled promise rejections
    for p, reason in list(_pending_rejections):
        if _is_obj(p) and p._cls=='Promise' and p.__dict__.get('_state')=='rejected':
            if not p.__dict__.get('_handled', False):
                sys.stderr.write('Possibly unhandled promise rejection: ')
                _print_error(reason, '')
                _pending_rejections.remove((p, reason))
                return 1
    _pending_rejections.clear()
    return 0

