    def _sprintf_impl(fmt, args):
        result = []; i = 0; ai = 0
        while i < len(fmt):
            c = fmt[i]
            if c == '%' and i+1 < len(fmt):
                i += 1; nc = fmt[i]
                if nc == 'd' or nc == 'i':
                    v = args[ai] if ai < len(args) else 0; ai += 1
                    result.append(str(int(_to_num(v))))
                elif nc == 'f':
                    v = args[ai] if ai < len(args) else 0; ai += 1
                    result.append(f'{float(_to_num(v)):.6f}')
                elif nc == 's':
                    v = args[ai] if ai < len(args) else ''; ai += 1
                    result.append(_to_str(v))
                elif nc == 'g':
                    v = args[ai] if ai < len(args) else 0; ai += 1
                    result.append(_js_num_str(float(_to_num(v))))
                elif nc == '%':
                    result.append('%')
                else:
                    result.append('%'+nc)
            else:
                result.append(c)
            i += 1
        return ''.join(result)

