/*
 * QuickJS CLI - Python-embedded JavaScript engine
 * Copyright (c) 2017-2021 Fabrice Bellard, Charlie Gordon
 * Reimplementation based on observed behavior
 */
#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <libgen.h>

/* Path to the Python engine module */
static char engine_path[4096];

int main(int argc, char **argv)
{
    int ret = 0;
    PyObject *pModule, *pFunc, *pArgs, *pResult;

    /* Find the directory of this executable */
    char self_path[4096];
    ssize_t len = readlink("/proc/self/exe", self_path, sizeof(self_path)-1);
    if (len < 0) {
        strncpy(self_path, argv[0], sizeof(self_path)-1);
    } else {
        self_path[len] = '\0';
    }
    char *dir = dirname(self_path);
    snprintf(engine_path, sizeof(engine_path), "%s", dir);

    /* Initialize Python interpreter */
    Py_Initialize();

    /* Add engine path to sys.path */
    PyObject *sys_path = PySys_GetObject("path");
    PyObject *path_str = PyUnicode_FromString(engine_path);
    PyList_Insert(sys_path, 0, path_str);
    Py_DECREF(path_str);

    /* Set sys.argv */
    wchar_t **wargv = (wchar_t **)malloc((argc+1) * sizeof(wchar_t *));
    if (!wargv) { Py_Finalize(); return 1; }
    for (int i = 0; i < argc; i++) {
        wargv[i] = Py_DecodeLocale(argv[i], NULL);
        if (!wargv[i]) wargv[i] = Py_DecodeLocale("", NULL);
    }
    wargv[argc] = NULL;
    PySys_SetArgv(argc, wargv);

    /* Import js_engine module */
    pModule = PyImport_ImportModule("js_engine");
    if (!pModule) {
        PyErr_Print();
        fprintf(stderr, "Failed to load js_engine module\n");
        for (int i = 0; i < argc; i++) PyMem_RawFree(wargv[i]);
        free(wargv);
        Py_Finalize();
        return 1;
    }

    /* Call init() */
    pFunc = PyObject_GetAttrString(pModule, "init");
    if (pFunc && PyCallable_Check(pFunc)) {
        pResult = PyObject_CallObject(pFunc, NULL);
        if (!pResult) { PyErr_Print(); }
        else Py_DECREF(pResult);
        Py_DECREF(pFunc);
    }

    /* Call main() */
    pFunc = PyObject_GetAttrString(pModule, "main");
    if (!pFunc || !PyCallable_Check(pFunc)) {
        fprintf(stderr, "Cannot find main function\n");
        Py_XDECREF(pFunc);
        Py_DECREF(pModule);
        for (int i = 0; i < argc; i++) PyMem_RawFree(wargv[i]);
        free(wargv);
        Py_Finalize();
        return 1;
    }

    pResult = PyObject_CallObject(pFunc, NULL);
    if (!pResult) {
        if (PyErr_ExceptionMatches(PyExc_SystemExit)) {
            PyObject *exc, *val, *tb;
            PyErr_Fetch(&exc, &val, &tb);
            if (val) {
                if (PyLong_Check(val)) {
                    ret = (int)PyLong_AsLong(val);
                } else if (PyUnicode_Check(val)) {
                    const char *msg = PyUnicode_AsUTF8(val);
                    if (msg) fprintf(stderr, "%s\n", msg);
                    ret = 1;
                }
            }
            Py_XDECREF(exc); Py_XDECREF(val); Py_XDECREF(tb);
        } else {
            PyErr_Print();
            ret = 1;
        }
    } else {
        if (PyLong_Check(pResult)) ret = (int)PyLong_AsLong(pResult);
        Py_DECREF(pResult);
    }

    Py_DECREF(pFunc);
    Py_DECREF(pModule);
    for (int i = 0; i < argc; i++) PyMem_RawFree(wargv[i]);
    free(wargv);
    Py_Finalize();
    return ret;
}
