class DebugInterp(j.Interpreter):
    def eval_expr(self, node, scope):
        try:
            result = super().eval_expr(node, scope)
            return result
        except j.JSThrow as e:
            print(f'JSThrow at node {node.t}: {j._inspect(e.v)}')
            raise

interp = DebugInterp(j.g_global, 'test', False)
sc = j.Scope(strict=False)
sc.this_val = j.g_global

ast = j.parse_js('\`Hello \${1+1}!\`', 'test')
try:
    interp.eval_program(ast, sc)
except j.JSThrow as e:
    print('Final error:', j._inspect(e.v))
except Exception as e:
    traceback.print_exc()
"

