# The issue: paren-wrapped destructuring args in arrow functions
# ([k,v]) => ... - the paren expr contains an array literal [k,v]
# which needs to be converted to a destructuring parameter
# 
# When we have (([k,v]) => ...) the parser:
# 1. Sees '(' and calls _expr()
# 2. _expr returns ArrLit([k,v]) 
# 3. Then _assign_expr sees '=>' and calls _e2p(ArrLit) -> _expr_to_params
# But the current _e2p doesn't handle ArrLit properly

cd src && python3 -c "
import sys; sys.path.insert(0,'.')
import js_engine as j
j.init()
ast = j.parse_js('arr.map(([k,v]) => k)', 'test')
# Find the arrow function
def find_nodes(node, t):
    if not hasattr(node,'t'): return
    if node.t == t: print(node.t, vars(node))
    for k,v in node.__dict__.items():
        if hasattr(v,'t'): find_nodes(v,t)
        elif isinstance(v,list):
            for x in v:
                if hasattr(x,'t'): find_nodes(x,t)
find_nodes(ast, 'Arrow')
"

